class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        import bisect

        parts = p.split('*')
        # p has exactly two '*', so 3 parts
        A, B, C = parts[0], parts[1], parts[2]
        n = len(s)

        def kmp_find_all(text, pat):
            if not pat:
                return list(range(len(text) + 1))
            m = len(pat)
            fail = [0] * m
            k = 0
            for i in range(1, m):
                while k > 0 and pat[k] != pat[i]:
                    k = fail[k - 1]
                if pat[k] == pat[i]:
                    k += 1
                fail[i] = k

            result = []
            k = 0
            for i in range(len(text)):
                while k > 0 and pat[k] != text[i]:
                    k = fail[k - 1]
                if pat[k] == text[i]:
                    k += 1
                if k == m:
                    result.append(i - m + 1)
                    k = fail[k - 1]
            return result

        matches_A = kmp_find_all(s, A)
        matches_B = kmp_find_all(s, B)
        matches_C = kmp_find_all(s, C)

        if not matches_A or not matches_B or not matches_C:
            return -1

        lenA, lenB, lenC = len(A), len(B), len(C)

        ans = float('inf')

        for k in matches_C:
            # latest B start j with j + lenB <= k  =>  j <= k - lenB
            idx_b = bisect.bisect_right(matches_B, k - lenB) - 1
            if idx_b < 0:
                continue
            j = matches_B[idx_b]
            # latest A start i with i + lenA <= j  =>  i <= j - lenA
            idx_a = bisect.bisect_right(matches_A, j - lenA) - 1
            if idx_a < 0:
                continue
            i = matches_A[idx_a]
            length = k + lenC - i
            if length < ans:
                ans = length

        return ans if ans != float('inf') else -1

import bisect

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        def kmp_find_all(text, pattern):
            n, m = len(text), len(pattern)
            if m == 0:
                return list(range(n + 1))
            fail = [0] * m
            k = 0
            for i in range(1, m):
                while k > 0 and pattern[k] != pattern[i]:
                    k = fail[k - 1]
                if pattern[k] == pattern[i]:
                    k += 1
                fail[i] = k
            result = []
            k = 0
            for i in range(n):
                while k > 0 and pattern[k] != text[i]:
                    k = fail[k - 1]
                if pattern[k] == text[i]:
                    k += 1
                if k == m:
                    result.append(i - m + 1)
                    k = fail[k - 1]
            return result

        parts = p.split('*')
        # exactly two '*' so 3 parts
        A, B, C = parts[0], parts[1], parts[2]
        lA, lB, lC = len(A), len(B), len(C)

        a_pos = kmp_find_all(s, A)
        b_pos = kmp_find_all(s, B)
        c_pos = kmp_find_all(s, C)

        if not a_pos or not b_pos or not c_pos:
            return -1

        ans = float('inf')
        for ck in c_pos:
            # largest bj such that bj + lB <= ck  =>  bj <= ck - lB
            limit_b = ck - lB
            idx = bisect.bisect_right(b_pos, limit_b) - 1
            if idx < 0:
                continue
            bj = b_pos[idx]
            # largest ai such that ai + lA <= bj  =>  ai <= bj - lA
            limit_a = bj - lA
            idx2 = bisect.bisect_right(a_pos, limit_a) - 1
            if idx2 < 0:
                continue
            ai = a_pos[idx2]
            length = ck + lC - ai
            if length < ans:
                ans = length

        return ans if ans != float('inf') else -1

class Solution:
    def countSubstrings(self, s: str) -> int:
        # For each digit d in 1..9, maintain cnt[d][r] = number of substrings
        # ending at the current index whose value mod d == r.
        # When extending by a new digit, residue r -> (r*10 + new_digit) % d.
        cnt = [None] + [[0] * d for d in range(1, 10)]
        ans = 0
        for ch in s:
            digit = ord(ch) - 48
            new_cnt = [None] + [[0] * d for d in range(1, 10)]
            for d in range(1, 10):
                old = cnt[d]
                nc = new_cnt[d]
                for r in range(d):
                    c = old[r]
                    if c:
                        nc[(r * 10 + digit) % d] += c
                nc[digit % d] += 1
            cnt = new_cnt
            if digit != 0:
                ans += cnt[digit][0]
        return ans

class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        ans = 0
        digits = [int(c) for c in s]
        # For each possible non-zero last digit d (1..9), count substrings
        # ending at positions where s[j] == d that are divisible by d.
        # Maintain cnt[r] = number of substrings ending at current j with value % d == r.
        # When moving from j-1 to j: new value = old_value * 10 + dj
        for d in range(1, 10):
            cnt = [0] * d
            for j in range(n):
                dj = digits[j]
                new_cnt = [0] * d
                for r in range(d):
                    if cnt[r]:
                        new_cnt[(r * 10 + dj) % d] += cnt[r]
                # Add the new single-character substring starting at j
                new_cnt[dj % d] += 1
                cnt = new_cnt
                if dj == d:
                    ans += cnt[0]
        return ans

