from math import lcm

class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        k = len(target)
        full = 1 << k

        # Precompute LCM for each subset of targets
        lcm_mask = [1] * full
        for mask in range(1, full):
            l = 1
            for i in range(k):
                if mask & (1 << i):
                    l = lcm(l, target[i])
            lcm_mask[mask] = l

        INF = float('inf')
        f = [INF] * full
        f[0] = 0

        for num in nums:
            # Cost to make num a multiple of lcm_mask[s] for each subset s
            cost = [0] * full
            for s in range(1, full):
                L = lcm_mask[s]
                r = num % L
                cost[s] = 0 if r == 0 else L - r

            new_f = f[:]
            for m in range(full):
                if f[m] == INF:
                    continue
                base = f[m]
                for s in range(full):
                    nm = m | s
                    v = base + cost[s]
                    if v < new_f[nm]:
                        new_f[nm] = v
            f = new_f

        return f[full - 1]

class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        s = [ord(ch) - ord('a') for ch in caption]
        INF = 10**18

        F = [None] * (n + 1)
        F[n] = [[INF, INF, 0] for _ in range(26)]

        for i in range(n - 1, -1, -1):
            f_next = F[i + 1]
            f_curr = [[INF, INF, INF] for _ in range(26)]
            si = s[i]

            switch_costs = [INF] * 26
            for c_ in range(26):
                if f_next[c_][0] < INF:
                    switch_costs[c_] = abs(si - c_) + f_next[c_][0]

            min1_val = INF; min1_idx = -1; min2_val = INF
            for c_ in range(26):
                if switch_costs[c_] < min1_val:
                    min2_val = min1_val
                    min1_val = switch_costs[c_]
                    min1_idx = c_
                elif switch_costs[c_] < min2_val:
                    min2_val = switch_costs[c_]

            for c in range(26):
                cost_c = abs(si - c)
                if f_next[c][1] < INF:
                    f_curr[c][0] = cost_c + f_next[c][1]
                if f_next[c][2] < INF:
                    f_curr[c][1] = cost_c + f_next[c][2]
                continue_cost = (cost_c + f_next[c][2]) if f_next[c][2] < INF else INF
                switch_cost = min2_val if c == min1_idx else min1_val
                f_curr[c][2] = min(continue_cost, switch_cost)

            F[i] = f_curr

        F1 = F[1]
        s0 = s[0]
        initial_costs = [INF] * 26
        for c in range(26):
            if F1[c][0] < INF:
                initial_costs[c] = abs(s0 - c) + F1[c][0]

        min_total = min(initial_costs)
        if min_total >= INF:
            return ""

        result = []
        c = 0
        while initial_costs[c] != min_total:
            c += 1
        result.append(chr(c + ord('a')))
        run = 0

        for i in range(1, n):
            if run == 0:
                result.append(chr(c + ord('a')))
                run = 1
            elif run == 1:
                result.append(chr(c + ord('a')))
                run = 2
            else:
                f_i = F[i]
                f_next = F[i + 1]
                target = f_i[c][2]
                si = s[i]
                chosen = -1
                for cp in range(26):
                    if cp == c:
                        if f_next[c][2] < INF and abs(si - c) + f_next[c][2] == target:
                            chosen = cp
                            break
                    else:
                        if f_next[cp][0] < INF and abs(si - cp) + f_next[cp][0] == target:
                            chosen = cp
                            break
                result.append(chr(chosen + ord('a')))
                if chosen == c:
                    run = 2
                else:
                    c = chosen
                    run = 0

        return ''.join(result)

import sys
from functools import lru_cache
from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        sys.setrecursionlimit(10000)
        n, m = len(grid), len(grid[0])
        # Clockwise order: NW, NE, SE, SW
        dirs = [(-1, -1), (-1, 1), (1, 1), (1, -1)]

        @lru_cache(maxsize=None)
        def dp(r, c, d, can_turn):
            # Assumes (r,c) is a valid current cell of the segment.
            v = grid[r][c]
            # Next expected value: 1->2, 2->0, 0->2
            next_v = 2 if v != 2 else 0

            best = 1

            # Continue in same direction
            dr, dc = dirs[d]
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == next_v:
                best = max(best, 1 + dp(nr, nc, d, can_turn))

            # Take clockwise 90-degree turn
            if can_turn:
                nd = (d + 1) % 4
                dr, dc = dirs[nd]
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == next_v:
                    best = max(best, 1 + dp(nr, nc, nd, False))

            return best

        ans = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    for d in range(4):
                        length = dp(r, c, d, True)
                        if length > ans:
                            ans = length

        # Clear cache to avoid memory issues across test cases
        dp.cache_clear()
        return ans

from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def S(n):
            # sum of d(x) for x in [1, n], where d(x) = floor(log_4(x)) + 1
            if n <= 0:
                return 0
            total = 0
            k = 1
            lo = 1
            while lo <= n:
                hi = lo * 4 - 1
                if hi > n:
                    hi = n
                total += k * (hi - lo + 1)
                lo *= 4
                k += 1
            return total

        def d(x):
            # number of divisions by 4 to reach 0
            if x <= 0:
                return 0
            c = 0
            while x > 0:
                x //= 4
                c += 1
            return c

        ans = 0
        for l, r in queries:
            total = S(r) - S(l - 1)
            ops = max((total + 1) // 2, d(r))
            ans += ops
        return ans

