class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)
        max_p = max(points)

        def feasible(T: int) -> bool:
            if T <= 0:
                return True
            total = 0
            extra = 0  # carry-over visits to position i from oscillation at i-1
            for i in range(n):
                c_i = (T + points[i] - 1) // points[i]
                if i == n - 1:
                    # Last position: may skip advancing if extra already suffices
                    if extra >= c_i:
                        pass
                    else:
                        total += 1  # advance into position i
                        if 1 + extra < c_i:
                            need = c_i - 1 - extra
                            total += 2 * need
                            # oscillate to i-1 since i+1 doesn't exist; same move count
                else:
                    total += 1  # advance into position i
                    if 1 + extra < c_i:
                        need = c_i - 1 - extra
                        total += 2 * need
                        extra = need  # carry to position i+1
                    else:
                        extra = 0
                if total > m:
                    return False
            return total <= m

        lo, hi = 0, max_p * m
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)
        max_p = max(points)

        def check(T: int) -> bool:
            if T <= 0:
                return True
            total = 0
            carry = 0
            for i in range(n):
                need = (T + points[i] - 1) // points[i]
                # If this is the last position and carry already satisfies it,
                # we don't need to actually move to i (we can stop earlier).
                if i == n - 1 and carry >= need:
                    return total <= m
                total += 1  # move/arrive at i (+1 visit)
                cur = 1 + carry
                if cur < need:
                    extra = need - cur
                    # zigzag with i+1 (or i-1 if last): each adds 1 visit, costs 2 moves
                    total += 2 * extra
                    carry = extra if i < n - 1 else 0
                else:
                    carry = 0
                if total > m:
                    return False
            return total <= m

        lo, hi = 0, max_p * m  # upper bound: total points sum <= m * max_p
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if check(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        word = [None] * L
        fixed = [False] * L

        # Apply T constraints
        for i in range(n):
            if str1[i] == 'T':
                for k in range(m):
                    if word[i + k] is not None and word[i + k] != str2[k]:
                        return ""
                    word[i + k] = str2[k]
                    fixed[i + k] = True

        # Fill remaining free positions with 'a' (lex smallest)
        for i in range(L):
            if word[i] is None:
                word[i] = 'a'

        # Check F constraints, breaking matches lex-optimally
        for i in range(n):
            if str1[i] == 'F':
                # Check if current window equals str2
                match = True
                for k in range(m):
                    if word[i + k] != str2[k]:
                        match = False
                        break
                if match:
                    # Find rightmost free position in window
                    j = -1
                    for k in range(m - 1, -1, -1):
                        if not fixed[i + k]:
                            j = i + k
                            break
                    if j == -1:
                        return ""
                    # Free position is currently 'a' and str2 at that offset must be 'a',
                    # so 'b' is the smallest character that breaks equality
                    word[j] = 'b'

        return ''.join(word)

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        word = [''] * L
        fixed = [False] * L

        # Apply T constraints
        for i in range(n):
            if str1[i] == 'T':
                for k in range(m):
                    pos = i + k
                    if fixed[pos] and word[pos] != str2[k]:
                        return ""
                    word[pos] = str2[k]
                    fixed[pos] = True

        # Fill free positions with 'a'
        for pos in range(L):
            if not fixed[pos]:
                word[pos] = 'a'

        # Apply F constraints greedily
        for i in range(n):
            if str1[i] == 'F':
                # Check if window equals str2
                match = True
                for k in range(m):
                    if word[i + k] != str2[k]:
                        match = False
                        break
                if match:
                    # Find rightmost free position in window
                    j = -1
                    for k in range(m - 1, -1, -1):
                        if not fixed[i + k]:
                            j = i + k
                            break
                    if j == -1:
                        return ""
                    # str2 at this offset must be 'a' (since window matched and word[j]='a')
                    # change to 'b' to break match while keeping lex small
                    word[j] = 'b'

        # Final verification
        result = ''.join(word)
        for i in range(n):
            sub = result[i:i + m]
            if str1[i] == 'T' and sub != str2:
                return ""
            if str1[i] == 'F' and sub == str2:
                return ""

        return result

from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        OFFSET = 1800  # alt_sum in [-1800, 1800] since n<=150, val<=12
        target = k + OFFSET
        if not (0 <= target <= 3600):
            return -1

        # dp[parity] is a dict: shifted_alt_sum -> set of products
        # parity 0: even length so far (next add contributes +)
        # parity 1: odd length so far (next add contributes -)
        dp = [{}, {}]

        for num in nums:
            additions = []
            for parity in (0, 1):
                delta = num if parity == 0 else -num
                d = dp[parity]
                for s, prods in d.items():
                    new_s = s + delta
                    if new_s < 0 or new_s > 3600:
                        continue
                    new_parity = 1 - parity
                    for p in prods:
                        new_p = p * num
                        if new_p <= limit:
                            additions.append((new_parity, new_s, new_p))

            # Start a fresh subsequence with just `num`
            # (length becomes 1 -> parity 1, alt_sum = num, product = num)
            if num <= limit:
                additions.append((1, OFFSET + num, num))

            for parity, s, p in additions:
                bucket = dp[parity].get(s)
                if bucket is None:
                    dp[parity][s] = {p}
                else:
                    bucket.add(p)

        best = -1
        for parity in (0, 1):
            bucket = dp[parity].get(target)
            if bucket:
                m = max(bucket)
                if m > best:
                    best = m
        return best

class Solution:
    def maxProduct(self, nums, k, limit):
        # dp = set of reachable (parity_of_next_index, alt_sum, product)
        # parity 0 means next element added would be at even index
        dp = set()
        for v in nums:
            new_dp = set(dp)
            # Start a new subsequence with v as first (index 0, even) element
            if v <= limit:
                new_dp.add((1, v, v))
            for (p, s, prod) in dp:
                new_prod = prod * v
                if new_prod > limit:
                    continue
                if p == 0:
                    new_dp.add((1, s + v, new_prod))
                else:
                    new_dp.add((0, s - v, new_prod))
            dp = new_dp

        ans = -1
        for (p, s, prod) in dp:
            if s == k and prod > ans:
                ans = prod
        return ans

