import sys

def solve():
    data = sys.stdin.buffer.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    X = int(data[idx]); idx += 1
    foods = [[], [], []]
    for _ in range(N):
        V = int(data[idx]); idx += 1
        A = int(data[idx]); idx += 1
        C = int(data[idx]); idx += 1
        foods[V - 1].append((A, C))

    # For each vitamin, do a 0/1 knapsack: f[v][c] = max vitamin v with cost <= c
    f = []
    for v in range(3):
        dp = [0] * (X + 1)
        for A, C in foods[v]:
            for c in range(X, C - 1, -1):
                cand = dp[c - C] + A
                if cand > dp[c]:
                    dp[c] = cand
        f.append(dp)

    upper = min(f[v][X] for v in range(3))
    if upper == 0:
        print(0)
        return

    def min_cost(v, m):
        # smallest c with f[v][c] >= m; f[v] is non-decreasing
        if f[v][X] < m:
            return X + 1
        lo, hi = 0, X
        while lo < hi:
            mid = (lo + hi) // 2
            if f[v][mid] >= m:
                hi = mid
            else:
                lo = mid + 1
        return lo

    lo, hi = 0, upper
    while lo < hi:
        mid = (lo + hi + 1) // 2
        total = min_cost(0, mid) + min_cost(1, mid) + min_cost(2, mid)
        if total <= X:
            lo = mid
        else:
            hi = mid - 1
    print(lo)

solve()

import sys
from collections import deque

def solve():
    data = sys.stdin.buffer.read().split()
    N = int(data[0])
    C = [data[1+i].decode() for i in range(N)]

    in_by_label_u = [{} for _ in range(N)]
    out_by_label_v = [{} for _ in range(N)]

    for i in range(N):
        row = C[i]
        for j in range(N):
            c = row[j]
            if c != '-':
                out_by_label_v[i].setdefault(c, []).append(j)
                in_by_label_u[j].setdefault(c, []).append(i)

    def bfs(initial):
        dist = [[-1]*N for _ in range(N)]
        q = deque()
        for (u, v, d) in initial:
            if dist[u][v] == -1:
                dist[u][v] = d
                q.append((u, v))
        while q:
            u, v = q.popleft()
            d = dist[u][v]
            nd = d + 2
            ibl = in_by_label_u[u]
            obl = out_by_label_v[v]
            if not ibl or not obl:
                continue
            if len(ibl) <= len(obl):
                for c, ups in ibl.items():
                    vps = obl.get(c)
                    if vps is None:
                        continue
                    for up in ups:
                        row = dist[up]
                        for vp in vps:
                            if row[vp] == -1:
                                row[vp] = nd
                                q.append((up, vp))
            else:
                for c, vps in obl.items():
                    ups = ibl.get(c)
                    if ups is None:
                        continue
                    for up in ups:
                        row = dist[up]
                        for vp in vps:
                            if row[vp] == -1:
                                row[vp] = nd
                                q.append((up, vp))
        return dist

    even_init = [(i, i, 0) for i in range(N)]
    dist_even = bfs(even_init)

    odd_init = []
    for i in range(N):
        for j in range(N):
            if C[i][j] != '-':
                odd_init.append((i, j, 1))
    dist_odd = bfs(odd_init)

    out_lines = []
    for i in range(N):
        row = []
        for j in range(N):
            de = dist_even[i][j]
            do = dist_odd[i][j]
            if de == -1 and do == -1:
                row.append(-1)
            elif de == -1:
                row.append(do)
            elif do == -1:
                row.append(de)
            else:
                row.append(de if de < do else do)
        out_lines.append(' '.join(map(str, row)))
    sys.stdout.write('\n'.join(out_lines) + '\n')

solve()

import sys
import heapq

def main():
    data = sys.stdin.buffer.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    M = int(data[idx]); idx += 1
    X = int(data[idx]); idx += 1

    adj_fwd = [[] for _ in range(N + 1)]
    adj_bwd = [[] for _ in range(N + 1)]

    for _ in range(M):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        adj_fwd[u].append(v)
        adj_bwd[v].append(u)

    INF = float('inf')
    # dist[v][p]: minimum cost to be at vertex v with parity p (0 = original, 1 = reversed)
    dist0 = [INF] * (N + 1)
    dist1 = [INF] * (N + 1)
    dist0[1] = 0

    pq = [(0, 1, 0)]

    while pq:
        d, v, p = heapq.heappop(pq)
        if p == 0:
            if d > dist0[v]:
                continue
        else:
            if d > dist1[v]:
                continue

        if v == N:
            print(d)
            return

        # Move along an edge in current orientation
        if p == 0:
            nd = d + 1
            for u in adj_fwd[v]:
                if nd < dist0[u]:
                    dist0[u] = nd
                    heapq.heappush(pq, (nd, u, 0))
        else:
            nd = d + 1
            for u in adj_bwd[v]:
                if nd < dist1[u]:
                    dist1[u] = nd
                    heapq.heappush(pq, (nd, u, 1))

        # Reverse all edges
        nd = d + X
        if p == 0:
            if nd < dist1[v]:
                dist1[v] = nd
                heapq.heappush(pq, (nd, v, 1))
        else:
            if nd < dist0[v]:
                dist0[v] = nd
                heapq.heappush(pq, (nd, v, 0))

    print(min(dist0[N], dist1[N]))

main()

import sys

def main():
    data = sys.stdin.buffer.read().split()
    N = int(data[0])
    A = list(map(int, data[1:N+1]))

    L = [0] * N
    seen = [False] * (N + 2)
    distinct = 0
    for i in range(N):
        v = A[i]
        if not seen[v]:
            seen[v] = True
            distinct += 1
        L[i] = distinct

    R = [0] * N
    seen = [False] * (N + 2)
    distinct = 0
    for i in range(N-1, -1, -1):
        v = A[i]
        if not seen[v]:
            seen[v] = True
            distinct += 1
        R[i] = distinct

    M = N - 1
    size = 1
    while size < M:
        size *= 2
    NEG = -(1 << 60)
    tree = [NEG] * (2 * size)
    lazy = [0] * size

    for i in range(M):
        tree[size + i] = L[i]
    for i in range(size - 1, 0, -1):
        tree[i] = max(tree[2*i], tree[2*i+1])

    LOG = size.bit_length() - 1

    def push(node):
        if lazy[node]:
            v = lazy[node]
            l, r = 2*node, 2*node+1
            tree[l] += v
            if l < size:
                lazy[l] += v
            tree[r] += v
            if r < size:
                lazy[r] += v
            lazy[node] = 0

    def range_add(ql, qr, val):
        l = ql + size
        r = qr + size + 1
        for i in range(LOG, 0, -1):
            if (l >> i) << i != l:
                push(l >> i)
            if (r >> i) << i != r:
                push((r - 1) >> i)
        l2, r2 = l, r
        while l2 < r2:
            if l2 & 1:
                tree[l2] += val
                if l2 < size:
                    lazy[l2] += val
                l2 += 1
            if r2 & 1:
                r2 -= 1
                tree[r2] += val
                if r2 < size:
                    lazy[r2] += val
            l2 >>= 1
            r2 >>= 1
        for i in range(1, LOG + 1):
            if (l >> i) << i != l:
                node = l >> i
                tree[node] = max(tree[2*node], tree[2*node+1])
            if (r >> i) << i != r:
                node = (r - 1) >> i
                tree[node] = max(tree[2*node], tree[2*node+1])

    def range_max(ql, qr):
        l = ql + size
        r = qr + size + 1
        for i in range(LOG, 0, -1):
            if (l >> i) << i != l:
                push(l >> i)
            if (r >> i) << i != r:
                push((r - 1) >> i)
        res = NEG
        while l < r:
            if l & 1:
                if tree[l] > res:
                    res = tree[l]
                l += 1
            if r & 1:
                r -= 1
                if tree[r] > res:
                    res = tree[r]
            l >>= 1
            r >>= 1
        return res

    last_occ = {A[0]: 0}
    ans = 0

    for b in range(1, N - 1):
        x = A[b]
        p = last_occ.get(x, -1)
        l_range = p if p > 0 else 0
        r_range = b - 1
        if l_range <= r_range:
            range_add(l_range, r_range, 1)
        cand = range_max(0, b - 1) + R[b + 1]
        if cand > ans:
            ans = cand
        last_occ[x] = b

    print(ans)

main()

import sys
from collections import deque

def main():
    sys.setrecursionlimit(100000)
    data = sys.stdin.read().split()
    idx = 0
    N = int(data[idx]); idx+=1
    M = int(data[idx]); idx+=1
    K = int(data[idx]); idx+=1
    edges = []
    for _ in range(M):
        u = int(data[idx]); idx+=1
        v = int(data[idx]); idx+=1
        edges.append((u,v))

    def cost(d):
        if d == 0:
            return 0
        BIG = 10**9
        num_nodes = 2 + N * d
        s = 0; t = 1
        def nd(v, k):
            return 2 + (v-1)*d + (k-1)
        graph = [[] for _ in range(num_nodes)]
        def add_edge(a, b, cap):
            graph[a].append([b, cap, len(graph[b])])
            graph[b].append([a, 0, len(graph[a])-1])
        for k in range(1, d+1):
            add_edge(s, nd(1, k), BIG)
            add_edge(nd(N, k), t, BIG)
        for v in range(1, N+1):
            for k in range(1, d):
                add_edge(nd(v, k), nd(v, k+1), BIG)
        for (u, v) in edges:
            for k in range(2, d+1):
                add_edge(nd(u, k-1), nd(v, k), BIG)
            for k in range(1, d+1):
                add_edge(nd(u, k), nd(v, k), 1)
        level = [-1]*num_nodes
        def bfs():
            for i in range(num_nodes):
                level[i] = -1
            level[s] = 0
            q = deque([s])
            while q:
                u = q.popleft()
                for e in graph[u]:
                    if e[1] > 0 and level[e[0]] < 0:
                        level[e[0]] = level[u]+1
                        q.append(e[0])
            return level[t] >= 0
        it = [0]*num_nodes
        def dfs(u, pushed):
            if u == t:
                return pushed
            while it[u] < len(graph[u]):
                e = graph[u][it[u]]
                vn = e[0]
                if e[1] > 0 and level[vn] == level[u]+1:
                    dp = dfs(vn, min(pushed, e[1]))
                    if dp > 0:
                        e[1] -= dp
                        graph[vn][e[2]][1] += dp
                        return dp
                it[u] += 1
            return 0
        flow = 0
        while bfs():
            for i in range(num_nodes):
                it[i] = 0
            while True:
                f = dfs(s, BIG)
                if f == 0:
                    break
                flow += f
                if flow > K + 1:
                    return flow
        return flow

    ans = 0
    for d in range(1, N):
        c = cost(d)
        if c <= K:
            ans = d
        else:
            break
    print(ans)

main()

