def solve():
    data = sys.stdin.buffer.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    M = int(data[idx]); idx += 1
    K = int(data[idx]); idx += 1
    edges = []
    for _ in range(M):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        edges.append((u, v))

    BIG = 10**9

    def max_flow(num_nodes, src, snk, edge_list, limit):
        graph = [[] for _ in range(num_nodes)]
        def add(u, v, c):
            graph[u].append([v, c, len(graph[v])])
            graph[v].append([u, 0, len(graph[u]) - 1])
        for u, v, c in edge_list:
            add(u, v, c)

        flow = 0
        while True:
            level = [-1] * num_nodes
            level[src] = 0
            q = deque([src])
            while q:
                u = q.popleft()
                for e in graph[u]:
                    if e[1] > 0 and level[e[0]] < 0:
                        level[e[0]] = level[u] + 1
                        q.append(e[0])
            if level[snk] < 0:
                break
            it = [0] * num_nodes
            while True:
                # iterative DFS to find augmenting path
                stack = [src]
                parent_edge = [-1] * num_nodes
                parent = [-1] * num_nodes
                found = False
                while stack:
                    u = stack[-1]
                    if u == snk:
                        found = True
                        break
                    advanced = False
                    while it[u] < len(graph[u]):
                        e = graph[u][it[u]]
                        v, c, _ = e
                        if c > 0 and level[v] == level[u] + 1 and parent[v] == -1 and v != src:
                            parent[v] = u
                            parent_edge[v] = it[u]
                            stack.append(v)
                            advanced = True
                            break
                        else:
                            it[u] += 1
                    if not advanced:
                        stack.pop()
                        if stack:
                            it[stack[-1]] += 1
                if not found:
                    break
                # find bottleneck
                bn = BIG
                v = snk
                while v != src:
                    u = parent[v]
                    e = graph[u][parent_edge[v]]
                    bn = min(bn, e[1])
                    v = u
                v = snk
                while v != src:
                    u = parent[v]
                    e = graph[u][parent_edge[v]]
                    e[1] -= bn
                    graph[v][e[2]][1] += bn
                    v = u
                flow += bn
                if flow > limit:
                    return flow
        return flow

    def check(d):
        if d == 0:
            return 0
        def node(v, i):
            return 2 + (v - 1) * d + (i - 1)
        num_nodes = 2 + N * d
        SRC = 0
        SNK = 1
        elist = []
        for i in range(1, d + 1):
            elist.append((node(1, i), SNK, BIG))
            elist.append((SRC, node(N, i), BIG))
        for v in range(1, N + 1):
            for i in range(1, d):
                elist.append((node(v, i + 1), node(v, i), BIG))
        for (u, v) in edges:
            for i in range(1, d):
                elist.append((node(v, i + 1), node(u, i), BIG))
        for (u, v) in edges:
            for i in range(1, d + 1):
                elist.append((node(v, i), node(u, i), 1))
        return max_flow(num_nodes, SRC, SNK, elist, K)

    ans = 0
    for d in range(1, N):
        f = check(d)
        if f <= K:
            ans = d
        else:
            break
    print(ans)

solve()

import sys

def solve():
    data = sys.stdin.buffer.read().split()
    N = int(data[0])
    S = data[1].decode()
    T = data[2].decode()

    if S == T:
        print(0)
        return

    F = {}
    for s, t in zip(S, T):
        if s in F:
            if F[s] != t:
                print(-1)
                return
        else:
            F[s] = t

    A = set(S)
    image = set(F.values())

    # Impossible case: |A|=26 and image covers all 26 letters (non-identity permutation)
    if len(A) == 26 and len(image) == 26:
        print(-1)
        return

    edges = sum(1 for c in A if F[c] != c)

    processed = set()
    cycles = 0
    for start in A:
        if start in processed:
            continue
        path = []
        on_path = set()
        cur = start
        while True:
            if cur not in A or F[cur] == cur:
                break
            if cur in processed:
                break
            if cur in on_path:
                cycles += 1
                break
            on_path.add(cur)
            path.append(cur)
            cur = F[cur]
        for p in path:
            processed.add(p)

    print(edges + cycles)

