from typing import List
from bisect import bisect_left

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)
        arr = [(l, r, w, i) for i, (l, r, w) in enumerate(intervals)]
        arr.sort(key=lambda x: x[1])

        ends = [r for _, r, _, _ in arr]
        prev = [bisect_left(ends, l) for l, _, _, _ in arr]

        def add_idx(tup, idx):
            lst = list(tup)
            pos = bisect_left(lst, idx)
            lst.insert(pos, idx)
            return tuple(lst)

        def better(a, b):
            # Returns True if state a is better than state b.
            if a is None:
                return False
            if b is None:
                return True
            if a[0] != b[0]:
                return a[0] > b[0]
            return a[1] < b[1]

        dp = [[None] * 5 for _ in range(n + 1)]
        for i in range(n + 1):
            dp[i][0] = (0, ())

        for i, (l, r, w, idx) in enumerate(arr, 1):
            p = prev[i - 1]
            for k in range(1, 5):
                best = dp[i - 1][k]

                if dp[p][k - 1] is not None:
                    cand_weight = dp[p][k - 1][0] + w
                    cand_indices = add_idx(dp[p][k - 1][1], idx)
                    cand = (cand_weight, cand_indices)

                    if better(cand, best):
                        best = cand

                dp[i][k] = best

        ans = (0, ())
        for k in range(1, 5):
            if better(dp[n][k], ans):
                ans = dp[n][k]

        return list(ans[1])
