from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        if max(nums) < 0:
            return max(nums)

        cur = best = nums[0]
        has_negative = nums[0] < 0

        for a in nums[1:]:
            has_negative |= a < 0
            cur = max(a, cur + a)
            best = max(best, cur)

        if not has_negative:
            return best

        prefix = 0
        gain = {}
        floor = 0
        max_gain = 0
        best_deleted = -(10 ** 30)

        for a in nums:
            prefix += a

            if a < 0:
                updated = max(gain.get(a, 0), floor) - a
                gain[a] = updated
                max_gain = max(max_gain, updated)

            best_deleted = max(best_deleted, prefix + max_gain)

            floor = max(floor, -prefix)
            max_gain = max(max_gain, floor)

        return max(best, best_deleted)
