from typing import List

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        def occurrences(text: str, pat: str) -> List[int]:
            n, m = len(text), len(pat)
            if m == 0:
                return list(range(n + 1))

            lps = [0] * m
            j = 0
            for i in range(1, m):
                while j and pat[i] != pat[j]:
                    j = lps[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                    lps[i] = j

            res = []
            j = 0
            for i, ch in enumerate(text):
                while j and ch != pat[j]:
                    j = lps[j - 1]
                if ch == pat[j]:
                    j += 1
                    if j == m:
                        res.append(i - m + 1)
                        j = lps[j - 1]
            return res

        a, b, c = p.split("*")
        la, lb, lc = len(a), len(b), len(c)

        occ_a = occurrences(s, a)
        occ_b = occurrences(s, b)
        occ_c = occurrences(s, c)

        ans = float("inf")

        for mid in occ_b:
            # Need A to start at or before mid - len(A), choose the latest such A.
            ia = bisect_right(occ_a, mid - la) - 1
            if ia < 0:
                continue

            # Need C to start at or after the end of B, choose the earliest such C.
            ic = bisect_left(occ_c, mid + lb)
            if ic == len(occ_c):
                continue

            start = occ_a[ia]
            end = occ_c[ic] + lc
            ans = min(ans, end - start)

        return -1 if ans == float("inf") else ans
