class Solution:
    def countSubstrings(self, s: str) -> int:
        # counts[m][r] = number of substrings ending at the previous position
        # whose value is congruent to r modulo m.
        counts = [None] + [[0] * m for m in range(1, 10)]
        ans = 0

        for ch in s:
            digit = ord(ch) - ord('0')

            for m in range(1, 10):
                nxt = [0] * m

                for r, cnt in enumerate(counts[m]):
                    if cnt:
                        nxt[(r * 10 + digit) % m] += cnt

                # Substring consisting only of the current digit.
                nxt[digit % m] += 1
                counts[m] = nxt

            if digit != 0:
                ans += counts[digit][0]

        return ans

from typing import List

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def bounded_count(left: int, right: int) -> int:
            # Count pairs (a, b): 1 <= a <= left, 1 <= b <= right, a + b - 1 <= k
            s = k + 1
            m = min(left, s - 1)
            if m <= 0:
                return 0

            full = min(m, max(0, s - right))
            total = full * right

            rem = m - full
            if rem:
                first = full + 1
                last = m
                total += rem * s - (first + last) * rem // 2

            return total

        def contribution(is_max: bool) -> int:
            prev = [-1] * n
            nxt = [n] * n
            stack = []

            for i, x in enumerate(nums):
                if is_max:
                    while stack and nums[stack[-1]] <= x:
                        stack.pop()
                else:
                    while stack and nums[stack[-1]] >= x:
                        stack.pop()
                prev[i] = stack[-1] if stack else -1
                stack.append(i)

            stack.clear()

            for i in range(n - 1, -1, -1):
                x = nums[i]
                if is_max:
                    while stack and nums[stack[-1]] < x:
                        stack.pop()
                else:
                    while stack and nums[stack[-1]] > x:
                        stack.pop()
                nxt[i] = stack[-1] if stack else n
                stack.append(i)

            total = 0
            for i, x in enumerate(nums):
                left = i - prev[i]
                right = nxt[i] - i
                total += x * bounded_count(left, right)
            return total

        return contribution(True) + contribution(False)

