class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        length = n + m - 1
        pattern = [ord(c) - 97 for c in str2]

        forced = [-1] * length
        for i, flag in enumerate(str1):
            if flag == 'T':
                for j, c in enumerate(pattern):
                    pos = i + j
                    if forced[pos] != -1 and forced[pos] != c:
                        return ""
                    forced[pos] = c

        pi = [0] * m
        for i in range(1, m):
            k = pi[i - 1]
            while k and pattern[i] != pattern[k]:
                k = pi[k - 1]
            if pattern[i] == pattern[k]:
                k += 1
            pi[i] = k

        nxt = [[0] * 26 for _ in range(m)]
        hit = [[False] * 26 for _ in range(m)]

        for state in range(m):
            for c in range(26):
                k = state
                while k and c != pattern[k]:
                    k = pi[k - 1]
                if c == pattern[k]:
                    k += 1
                if k == m:
                    hit[state][c] = True
                    k = pi[m - 1]
                nxt[state][c] = k

        dp = [None] * (length + 1)
        dp[length] = bytearray([1]) * m
        letters = range(26)

        for pos in range(length - 1, -1, -1):
            row = bytearray(m)
            next_row = dp[pos + 1]
            fixed = forced[pos]
            start = pos - m + 1
            forbid = 0 <= start < n and str1[start] == 'F'

            if fixed != -1:
                c = fixed
                for state in range(m):
                    if (not forbid or not hit[state][c]) and next_row[nxt[state][c]]:
                        row[state] = 1
            else:
                for state in range(m):
                    ns_row = nxt[state]
                    hit_row = hit[state]
                    for c in letters:
                        if (not forbid or not hit_row[c]) and next_row[ns_row[c]]:
                            row[state] = 1
                            break

            dp[pos] = row

        if not dp[0][0]:
            return ""

        ans = []
        state = 0

        for pos in range(length):
            fixed = forced[pos]
            choices = (fixed,) if fixed != -1 else letters
            start = pos - m + 1
            forbid = 0 <= start < n and str1[start] == 'F'

            for c in choices:
                ns = nxt[state][c]
                if (not forbid or not hit[state][c]) and dp[pos + 1][ns]:
                    ans.append(chr(c + 97))
                    state = ns
                    break

        return "".join(ans)
