from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        s = side
        perimeter = 4 * s

        def perimeter_pos(x: int, y: int) -> int:
            if y == 0:
                return x
            if x == s:
                return s + y
            if y == s:
                return 3 * s - x
            return 4 * s - y

        pos = sorted(perimeter_pos(x, y) for x, y in points)
        n = len(pos)

        def can(d: int) -> bool:
            if d == 0:
                return True

            arr = pos + [p + perimeter for p in pos]
            m = 2 * n

            nxt = [m] * m
            j = 0
            for i in range(m):
                if j <= i:
                    j = i + 1
                while j < m and arr[j] < arr[i] + d:
                    j += 1
                nxt[i] = j

            for start in range(n):
                cur = start
                ok = True

                for _ in range(k - 1):
                    cur = nxt[cur]
                    if cur >= start + n:
                        ok = False
                        break

                if ok and arr[cur] <= arr[start] + perimeter - d:
                    return True

            return False

        lo, hi = 0, s
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo
