from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        CAP = 10**15

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(CAP + 1, fact[i - 1] * i)

        def count_completions(odd_left: int, even_left: int, last_parity: int) -> int:
            remaining = odd_left + even_left
            if remaining == 0:
                return 1

            next_parity = 1 - last_parity
            if next_parity == 1:
                needed_odd = (remaining + 1) // 2
                needed_even = remaining // 2
            else:
                needed_even = (remaining + 1) // 2
                needed_odd = remaining // 2

            if odd_left != needed_odd or even_left != needed_even:
                return 0

            return min(CAP + 1, fact[odd_left] * fact[even_left])

        remaining_nums = list(range(1, n + 1))
        odd_left = (n + 1) // 2
        even_left = n // 2
        ans = []
        prev_parity = -1

        for _ in range(n):
            picked = False

            for i, x in enumerate(remaining_nums):
                parity = x & 1
                if prev_parity != -1 and parity == prev_parity:
                    continue

                next_odd = odd_left - (1 if parity == 1 else 0)
                next_even = even_left - (1 if parity == 0 else 0)
                cnt = count_completions(next_odd, next_even, parity)

                if k > cnt:
                    k -= cnt
                else:
                    ans.append(x)
                    remaining_nums.pop(i)
                    odd_left = next_odd
                    even_left = next_even
                    prev_parity = parity
                    picked = True
                    break

            if not picked:
                return []

        return ans

