from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]

        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, idx))

        # Best and second-best active left endpoints among pairs with right <= r.
        top1_val = 0
        top1_count = 0
        top1_id = -1
        top2_val = 0

        base = 0
        gain = [0] * len(conflictingPairs)

        for r in range(1, n + 1):
            for left, idx in by_right[r]:
                if left > top1_val:
                    top2_val = top1_val
                    top1_val = left
                    top1_count = 1
                    top1_id = idx
                elif left == top1_val:
                    top1_count += 1
                    top1_id = -1
                elif left > top2_val:
                    top2_val = left

            base += r - top1_val

            if top1_count == 1:
                gain[top1_id] += top1_val - top2_val

        return base + max(gain)
