import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M, A, B = data[:4]
    intervals = []
    p = 4
    for _ in range(M):
        L, R = data[p], data[p + 1]
        intervals.append((L, R))
        p += 2

    limit = (1 << B) - 1
    step_mask = 0
    for jump in range(A, B + 1):
        step_mask |= 1 << (jump - 1)

    def one_safe_step(mask):
        reachable = 1 if (mask & step_mask) else 0
        return ((mask << 1) & limit) | reachable

    cache = {}

    def safe_power(mask, k):
        key = (mask, k)
        if key in cache:
            return cache[key]

        if k == 0:
            res = one_safe_step(mask)
        else:
            mid = safe_power(mask, k - 1)
            res = safe_power(mid, k - 1)

        cache[key] = res
        return res

    def advance_safe(mask, length):
        k = 0
        while length:
            if length & 1:
                mask = safe_power(mask, k)
            length >>= 1
            k += 1
        return mask

    def advance_bad(mask, length):
        if length >= B:
            return 0
        return (mask << length) & limit

    # Before processing square 2, bit 0 represents reachability of square 1.
    mask = 1
    cur = 2

    for L, R in intervals:
        if cur < L:
            mask = advance_safe(mask, L - cur)
        mask = advance_bad(mask, R - L + 1)
        cur = R + 1

    if cur <= N:
        mask = advance_safe(mask, N - cur + 1)

    print("Yes" if (mask & 1) else "No")

if __name__ == "__main__":
    main()
