import sys

class SegTree:
    def __init__(self, n):
        self.n = n
        self.size = 1
        while self.size < n:
            self.size <<= 1
        self.mn = [10**18] * (2 * self.size)
        self.mx = [-10**18] * (2 * self.size)
        self.lazy = [0] * (2 * self.size)

        for i in range(n):
            self.mn[self.size + i] = self.mx[self.size + i] = i + 1
        for i in range(self.size - 1, 0, -1):
            self.mn[i] = min(self.mn[i << 1], self.mn[i << 1 | 1])
            self.mx[i] = max(self.mx[i << 1], self.mx[i << 1 | 1])

    def _apply(self, idx, val):
        self.mn[idx] += val
        self.mx[idx] += val
        self.lazy[idx] += val

    def _push(self, idx):
        if self.lazy[idx]:
            v = self.lazy[idx]
            self._apply(idx << 1, v)
            self._apply(idx << 1 | 1, v)
            self.lazy[idx] = 0

    def range_add(self, left, right, val, idx=1, nl=0, nr=None):
        if nr is None:
            nr = self.size
        if right <= nl or nr <= left:
            return
        if left <= nl and nr <= right:
            self._apply(idx, val)
            return
        self._push(idx)
        mid = (nl + nr) >> 1
        self.range_add(left, right, val, idx << 1, nl, mid)
        self.range_add(left, right, val, idx << 1 | 1, mid, nr)
        self.mn[idx] = min(self.mn[idx << 1], self.mn[idx << 1 | 1])
        self.mx[idx] = max(self.mx[idx << 1], self.mx[idx << 1 | 1])

    def first_ge(self, x):
        if self.mx[1] < x:
            return self.n
        idx, nl, nr = 1, 0, self.size
        while idx < self.size:
            self._push(idx)
            mid = (nl + nr) >> 1
            if self.mx[idx << 1] >= x:
                idx = idx << 1
                nr = mid
            else:
                idx = idx << 1 | 1
                nl = mid
        return min(nl, self.n)

    def first_gt(self, x):
        if self.mx[1] <= x:
            return self.n
        idx, nl, nr = 1, 0, self.size
        while idx < self.size:
            self._push(idx)
            mid = (nl + nr) >> 1
            if self.mx[idx << 1] > x:
                idx = idx << 1
                nr = mid
            else:
                idx = idx << 1 | 1
                nl = mid
        return min(nl, self.n)

    def point_get(self, pos):
        idx, nl, nr = 1, 0, self.size
        while idx < self.size:
            self._push(idx)
            mid = (nl + nr) >> 1
            if pos < mid:
                idx = idx << 1
                nr = mid
            else:
                idx = idx << 1 | 1
                nl = mid
        return self.mn[idx]


def main():
    input = sys.stdin.readline
    N = int(input())
    contests = [tuple(map(int, input().split())) for _ in range(N)]

    MAX_X = 500000
    seg = SegTree(MAX_X)

    for l, r in contests:
        left = seg.first_ge(l)
        right = seg.first_gt(r)
        if left < right:
            seg.range_add(left, right, 1)

    Q = int(input())
    ans = []
    for _ in range(Q):
        x = int(input())
        ans.append(str(seg.point_get(x - 1)))

    print("\n".join(ans))


if __name__ == "__main__":
    main()

import sys

def main():
    N, P = map(int, sys.stdin.readline().split())
    H = N // 2
    E = N * (N - 1) // 2

    comb = [[0] * (E + 1) for _ in range(E + 1)]
    for i in range(E + 1):
        comb[i][0] = comb[i][i] = 1
        if i:
            prev = comb[i - 1]
            row = comb[i]
            for j in range(1, i):
                row[j] = (prev[j - 1] + prev[j]) % P

    fact = [1] * (N + 1)
    invfact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % P
    invfact[N] = pow(fact[N], P - 2, P)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % P

    trans = [[None] * (H + 1) for _ in range(H + 1)]
    for a in range(1, H + 1):
        for b in range(1, H + 1):
            poly = [0] * (a * b + 1)

            # ((1+x)^a - 1)^b
            for j in range(b + 1):
                coef = comb[b][j]
                if (b - j) & 1:
                    coef = P - coef
                row = comb[a * j]
                for d in range(a * j + 1):
                    poly[d] = (poly[d] + coef * row[d]) % P

            # Multiply by (1+x)^(b choose 2), for edges inside the new layer.
            inside = b * (b - 1) // 2
            res = [0] * (a * b + inside + 1)
            row_inside = comb[inside]
            for d, val in enumerate(poly):
                if val:
                    for r in range(inside + 1):
                        res[d + r] = (res[d + r] + val * row_inside[r]) % P

            scale = invfact[b]
            for i in range(len(res)):
                res[i] = res[i] * scale % P

            trans[a][b] = (b, res[b:], len(res) - 1)

    layers = [dict() for _ in range(N + 1)]
    start = [0] * (E + 1)
    start[0] = 1
    layers[1][(1, 0, 1, 0)] = [start, 0, 0]  # even_count, odd_count, last_size, parity

    for used in range(1, N):
        for (even, odd, last, parity), (src, lo, hi) in list(layers[used].items()):
            next_parity = 1 - parity
            remaining = H - (odd if next_parity else even)

            for b in range(1, remaining + 1):
                neven = even + (b if next_parity == 0 else 0)
                nodd = odd + (b if next_parity == 1 else 0)
                nused = used + b
                key = (neven, nodd, b, next_parity)

                item = layers[nused].get(key)
                if item is None:
                    item = [[0] * (E + 1), E + 1, -1]
                    layers[nused][key] = item

                dest = item[0]
                tlo, tcoef, thi = trans[last][b]

                for i in range(lo, hi + 1):
                    sv = src[i]
                    if sv:
                        pos = i + tlo
                        for tv in tcoef:
                            dest[pos] += sv * tv
                            pos += 1

                nlo = lo + tlo
                nhi = hi + thi
                for i in range(nlo, nhi + 1):
                    dest[i] %= P

                if nlo < item[1]:
                    item[1] = nlo
                if nhi > item[2]:
                    item[2] = nhi

    ans = [0] * (E + 1)
    for poly, lo, hi in layers[N].values():
        for m in range(lo, hi + 1):
            ans[m] = (ans[m] + poly[m]) % P

    label_factor = fact[N - 1]
    print(" ".join(str(ans[m] * label_factor % P) for m in range(N - 1, E + 1)))

if __name__ == "__main__":
    main()

import sys

def main():
    input = sys.stdin.readline
    N, X = map(int, input().split())

    foods = [[] for _ in range(3)]
    for _ in range(N):
        v, a, c = map(int, input().split())
        foods[v - 1].append((a, c))

    best = []
    for group in foods:
        dp = [0] * (X + 1)
        for a, c in group:
            for cal in range(X, c - 1, -1):
                nv = dp[cal - c] + a
                if nv > dp[cal]:
                    dp[cal] = nv

        for cal in range(1, X + 1):
            if dp[cal - 1] > dp[cal]:
                dp[cal] = dp[cal - 1]

        best.append(dp)

    def feasible(target):
        total_cal = 0
        for dp in best:
            need = None
            lo, hi = 0, X
            while lo <= hi:
                mid = (lo + hi) // 2
                if dp[mid] >= target:
                    need = mid
                    hi = mid - 1
                else:
                    lo = mid + 1

            if need is None:
                return False

            total_cal += need
            if total_cal > X:
                return False

        return True

    low, high = 0, min(best[0][X], best[1][X], best[2][X])
    while low < high:
        mid = (low + high + 1) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid - 1

    print(low)

if __name__ == "__main__":
    main()

