import sys

MOD = 998244353

def main():
    N, M = map(int, sys.stdin.readline().split())
    S = sys.stdin.readline().strip()

    size = 1 << N

    # Precompute transitions: state mask represents differences
    # d[i] = LCS(S[:i+1], T) - LCS(S[:i], T), each d[i] is 0 or 1.
    trans = [[0] * 26 for _ in range(size)]

    for mask in range(size):
        old = [0] * (N + 1)
        for i in range(N):
            old[i + 1] = old[i] + ((mask >> i) & 1)

        for ch in range(26):
            c = chr(ord('a') + ch)
            new = [0] * (N + 1)

            for i in range(1, N + 1):
                best = max(old[i], new[i - 1])
                if S[i - 1] == c:
                    best = max(best, old[i - 1] + 1)
                new[i] = best

            nxt = 0
            for i in range(N):
                if new[i + 1] - new[i]:
                    nxt |= 1 << i
            trans[mask][ch] = nxt

    dp = [0] * size
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * size
        for mask, val in enumerate(dp):
            if val == 0:
                continue
            for ch in range(26):
                nxt = trans[mask][ch]
                ndp[nxt] = (ndp[nxt] + val) % MOD
        dp = ndp

    ans = [0] * (N + 1)
    for mask, val in enumerate(dp):
        ans[mask.bit_count()] = (ans[mask.bit_count()] + val) % MOD

    print(*ans)

