import sys
from collections import deque

def main():
    input = sys.stdin.readline
    N = int(input())
    C = [input().strip() for _ in range(N)]

    INF = 10**18
    dist = [[INF] * N for _ in range(N)]

    in_by_char = [[[] for _ in range(26)] for _ in range(N)]
    out_by_char = [[[] for _ in range(26)] for _ in range(N)]

    for i in range(N):
        for j, ch in enumerate(C[i]):
            if ch != "-":
                k = ord(ch) - ord("a")
                out_by_char[i][k].append(j)
                in_by_char[j][k].append(i)

    q = deque()

    for i in range(N):
        dist[i][i] = 0
        q.append((i, i))

    for i in range(N):
        for j in range(N):
            if C[i][j] != "-" and dist[i][j] > 1:
                dist[i][j] = 1
                q.append((i, j))

    while q:
        u, v = q.popleft()
        nd = dist[u][v] + 2

        for k in range(26):
            lefts = in_by_char[u][k]
            rights = out_by_char[v][k]
            if not lefts or not rights:
                continue

            for a in lefts:
                row = dist[a]
                for b in rights:
                    if row[b] == INF:
                        row[b] = nd
                        q.append((a, b))

    for i in range(N):
        print(*[-1 if dist[i][j] == INF else dist[i][j] for j in range(N)])

if __name__ == "__main__":
