import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    adj = [[] for _ in range(n)]
    idx = 1
    for _ in range(n - 1):
        a = data[idx] - 1
        b = data[idx + 1] - 1
        idx += 2
        adj[a].append(b)
        adj[b].append(a)

    parent = [-1] * n
    order = [0]
    for u in order:
        for v in adj[u]:
            if v == parent[u]:
                continue
            parent[v] = u
            order.append(v)

    # down[u]: best branch size rooted at u when u is connected to its parent.
    # Then u may be a leaf, or it may choose exactly 3 child branches.
    down = [1] * n
    for u in reversed(order):
        vals = [down[v] for v in adj[u] if parent[v] == u]
        if len(vals) >= 3:
            vals.sort(reverse=True)
            down[u] = 1 + vals[0] + vals[1] + vals[2]

    # up[u]: best branch size coming from parent[u] into u.
    up = [0] * n
    ans = -1

    for u in order:
        incoming = []
        for v in adj[u]:
            if v == parent[u]:
                incoming.append((v, up[u]))
            else:
                incoming.append((v, down[v]))

        incoming.sort(key=lambda x: x[1], reverse=True)
        m = len(incoming)

        # Make u a degree-4 vertex and take the best 4 incident branches.
        if m >= 4:
            top4_sum = sum(incoming[i][1] for i in range(4))
            ans = max(ans, 1 + top4_sum)

            top3_sum = sum(incoming[i][1] for i in range(3))
            first3 = {incoming[i][0]: incoming[i][1] for i in range(3)}

            # Send branch values from u to each child, excluding that child.
            for v in adj[u]:
                if parent[v] == u:
                    if v in first3:
                        up[v] = 1 + top4_sum - first3[v]
                    else:
                        up[v] = 1 + top3_sum
        else:
            for v in adj[u]:
                if parent[v] == u:
                    up[v] = 1

    print(ans)

if __name__ == "__main__":
    main()

import sys


class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, x):
        while i <= self.n:
            self.bit[i] += x
            i += i & -i

    def sum(self, i):
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s


def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    A = list(map(int, input().split()))

    fw = Fenwick(M)
    inv = 0

    for i, a in enumerate(A):
        idx = a + 1
        inv += i - fw.sum(idx)
        fw.add(idx, 1)

    delta = [0] * M
    for i, a in enumerate(A):
        delta[a] += 2 * i - N + 1

    ans = []
    cur = inv
    for k in range(M):
        ans.append(str(cur))
        if k + 1 < M:
            cur += delta[M - 1 - k]

    print("\n".join(ans))


if __name__ == "__main__":
    main()

import sys
sys.setrecursionlimit(1_000_000)

def main():
    input = sys.stdin.readline
    N, K = map(int, input().split())
    M = N * K

    g = [[] for _ in range(M)]
    for _ in range(M - 1):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        g[u].append(v)
        g[v].append(u)

    if K == 1:
        print("Yes")
        return

    parent = [-1] * M
    order = [0]
    parent[0] = -2

    for v in order:
        for to in g[v]:
            if to == parent[v]:
                continue
            parent[to] = v
            order.append(to)

    ok = True
    rem = [0] * M

    for v in reversed(order):
        child_lengths = []
        for to in g[v]:
            if parent[to] == v and rem[to] > 0:
                child_lengths.append(rem[to])

        if len(child_lengths) >= 3:
            ok = False
            break

        if len(child_lengths) == 0:
            rem[v] = 1
        elif len(child_lengths) == 1:
            x = child_lengths[0]
            if x + 1 == K:
                rem[v] = 0
            else:
                rem[v] = x + 1
        else:
            a, b = child_lengths
            if a + b + 1 == K:
                rem[v] = 0
            else:
                ok = False
                break

        if rem[v] > K:
            ok = False
            break

    print("Yes" if ok and rem[0] == 0 else "No")

if __name__ == "__main__":
    main()

import sys

NEG = -10**18


class LazyMaxSegTree:
    def __init__(self, n):
        self.n = n
        self.size = 1
        self.log = 0
        while self.size < n:
            self.size <<= 1
            self.log += 1
        self.data = [NEG] * (2 * self.size)
        self.lazy = [0] * self.size

    def _update(self, k):
        self.data[k] = max(self.data[2 * k], self.data[2 * k + 1])

    def _all_apply(self, k, value):
        self.data[k] += value
        if k < self.size:
            self.lazy[k] += value

    def _push(self, k):
        if self.lazy[k]:
            value = self.lazy[k]
            self._all_apply(2 * k, value)
            self._all_apply(2 * k + 1, value)
            self.lazy[k] = 0

    def set(self, p, value):
        p += self.size
        for i in range(self.log, 0, -1):
            self._push(p >> i)
        self.data[p] = value
        for i in range(1, self.log + 1):
            self._update(p >> i)

    def add(self, left, right, value):
        if left >= right:
            return

        left += self.size
        right += self.size
        l0, r0 = left, right

        for i in range(self.log, 0, -1):
            if ((l0 >> i) << i) != l0:
                self._push(l0 >> i)
            if ((r0 >> i) << i) != r0:
                self._push((r0 - 1) >> i)

        while left < right:
            if left & 1:
                self._all_apply(left, value)
                left += 1
            if right & 1:
                right -= 1
                self._all_apply(right, value)
            left >>= 1
            right >>= 1

        left, right = l0, r0
        for i in range(1, self.log + 1):
            if ((left >> i) << i) != left:
                self._update(left >> i)
            if ((right >> i) << i) != right:
                self._update((right - 1) >> i)

    def max_all(self):
        return self.data[1]


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = [0] + data[1:]

    seen = [False] * (n + 1)
    prefix = [0] * (n + 1)
    count = 0
    for i in range(1, n + 1):
        if not seen[a[i]]:
            seen[a[i]] = True
            count += 1
        prefix[i] = count

    seen = [False] * (n + 1)
    suffix = [0] * (n + 2)
    count = 0
    for i in range(n, 0, -1):
        if not seen[a[i]]:
            seen[a[i]] = True
            count += 1
        suffix[i] = count

    seg = LazyMaxSegTree(n - 2)
    last = [0] * (n + 1)
    last[a[1]] = 1

    answer = 0

    for j in range(2, n):
        seg.set(j - 2, prefix[j - 1])

        x = a[j]
        previous = last[x]
        left_i = max(1, previous)
        seg.add(left_i - 1, j - 1, 1)

        last[x] = j
        answer = max(answer, seg.max_all() + suffix[j + 1])

    print(answer)


