    main()

import sys
from collections import deque

class Edge:
    __slots__ = ("to", "rev", "cap")

    def __init__(self, to, rev, cap):
        self.to = to
        self.rev = rev
        self.cap = cap

class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        fwd = Edge(to, len(self.g[to]), cap)
        rev = Edge(fr, len(self.g[fr]), 0)
        self.g[fr].append(fwd)
        self.g[to].append(rev)

    def max_flow(self, s, t, limit):
        flow = 0
        n = self.n

        while flow < limit:
            level = [-1] * n
            level[s] = 0
            q = deque([s])

            while q:
                v = q.popleft()
                for e in self.g[v]:
                    if e.cap > 0 and level[e.to] < 0:
                        level[e.to] = level[v] + 1
                        q.append(e.to)

            if level[t] < 0:
                break

            it = [0] * n

            def dfs(v, f):
                if v == t:
                    return f
                while it[v] < len(self.g[v]):
                    e = self.g[v][it[v]]
                    if e.cap > 0 and level[e.to] == level[v] + 1:
                        ret = dfs(e.to, min(f, e.cap))
                        if ret:
                            e.cap -= ret
                            self.g[e.to][e.rev].cap += ret
                            return ret
                    it[v] += 1
                return 0

            while flow < limit:
                pushed = dfs(s, limit - flow)
                if not pushed:
                    break
                flow += pushed

        return flow

def needed_edges(n, edges, d, k):
    if d == 0:
        return 0

    inf = 10**9
    total_nodes = n * d + 2
    src = total_nodes - 2
    sink = total_nodes - 1

    def node(v, level):
        return (level - 1) * n + v

    mf = Dinic(total_nodes)

    # z[v][i] means vertex v has potential at least i.
    # Source side of the cut represents z = 1.
    for level in range(1, d + 1):
        mf.add_edge(src, node(n - 1, level), inf)  # target potential is d
        mf.add_edge(node(0, level), sink, inf)     # start potential is 0

    for v in range(n):
        for level in range(1, d):
            mf.add_edge(node(v, level + 1), node(v, level), inf)

    for u, v in edges:
        for level in range(2, d + 1):
            mf.add_edge(node(v, level), node(u, level - 1), inf)

        for level in range(1, d + 1):
            mf.add_edge(node(v, level), node(u, level), 1)

    return mf.max_flow(src, sink, k + 1)

def main():
    input = sys.stdin.readline
    n, m, k = map(int, input().split())
    edges = []
    for _ in range(m):
        u, v = map(int, input().split())
        edges.append((u - 1, v - 1))

    ans = 0
    for d in range(1, min(k, n - 1) + 1):
        if needed_edges(n, edges, d, k) <= k:
            ans = d
        else:
            break

    print(ans)

if __name__ == "__main__":
    main()

