def main():
    s = sys.stdin.readline().strip()
    r = s[::-1]
    n = len(s)

    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        while j > 0 and r[i] != r[j]:
            j = pi[j - 1]
        if r[i] == r[j]:
            j += 1
        pi[i] = j

    matched = 0
    for ch in s:
        while matched > 0 and ch != r[matched]:
            matched = pi[matched - 1]
        if ch == r[matched]:
            matched += 1
        if matched == n:
            matched = pi[matched - 1] if ch != s[-1] else matched

    ans = s + s[:n - matched][::-1]
    print(ans)

