import sys
from collections import deque

def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())

    adj = [[] for _ in range(N)]
    for _ in range(M):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        adj[u].append(v)
        adj[v].append(u)

    color = [-1] * N

    iso = 0          # isolated vertices
    odd = 0          # non-isolated components with odd total size
    both_odd = 0     # components whose two color classes are both odd
    filler_parity = 0

    for s in range(N):
        if color[s] != -1:
            continue

        color[s] = 0
        q = deque([s])
        cnt = [0, 0]
        edge_sum = 0

        while q:
            u = q.popleft()
            cnt[color[u]] += 1
            edge_sum += len(adj[u])

            for v in adj[u]:
                if color[v] == -1:
                    color[v] = color[u] ^ 1
                    q.append(v)

        edges = edge_sum // 2
        a, b = cnt

        filler_parity ^= (a * b - edges) & 1

        if a + b == 1:
            iso += 1
        else:
            pa, pb = a & 1, b & 1
            if pa == 1 and pb == 1:
                both_odd += 1
            elif pa != pb:
                odd += 1

    if odd == 0:
        if iso % 2 == 0:
            losing = filler_parity == ((iso // 2) & 1)
        else:
            losing = filler_parity == (both_odd & 1)
    elif (odd == 1 and iso % 2 == 1) or (odd == 2 and iso % 2 == 0):
        losing = False
    else:
        losing = filler_parity == (both_odd & 1)

    print("Takahashi" if losing else "Aoki")

if __name__ == "__main__":
    main()

import sys

MOD = 998244353

def main():
    input = sys.stdin.readline
    N, K = map(int, input().split())
    A = list(map(int, input().split()))

    comb = [[0] * (K + 1) for _ in range(K + 1)]
    for n in range(K + 1):
        comb[n][0] = comb[n][n] = 1
        for r in range(1, n):
            comb[n][r] = comb[n - 1][r - 1] + comb[n - 1][r]

    prefix_power_sums = [0] * (K + 1)
    prefix_power_sums[0] = 1  # S_0^0, where S_0 = 0

    ans = 0
    s = 0

    for a in A:
        s = (s + a) % MOD

        powers = [1] * (K + 1)
        for d in range(1, K + 1):
            powers[d] = powers[d - 1] * s % MOD

        add = 0
        for t in range(K + 1):
            term = comb[K][t] * powers[K - t] % MOD * prefix_power_sums[t] % MOD
            if t % 2:
                add -= term
            else:
                add += term

        ans = (ans + add) % MOD

        for t in range(K + 1):
            prefix_power_sums[t] = (prefix_power_sums[t] + powers[t]) % MOD

    print(ans % MOD)

