    main()

import sys

def mat_mul(A, B, mod):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        Ci = C[i]
        Ai = A[i]
        for k, a in enumerate(Ai):
            if a:
                Bk = B[k]
                for j in range(n):
                    Ci[j] += a * Bk[j]
        for j in range(n):
            Ci[j] %= mod
    return C

def mat_pow(A, exp, mod):
    n = len(A)
    R = [[0] * n for _ in range(n)]
    for i in range(n):
        R[i][i] = 1

    while exp:
        if exp & 1:
            R = mat_mul(R, A, mod)
        exp >>= 1
        if exp:
            A = mat_mul(A, A, mod)
    return R

def main():
    input = sys.stdin.readline
    N, p = map(int, input().split())
    A = [list(map(int, input().split())) for _ in range(N)]

    if p == 2:
        val = N % 2
        print("\n".join(" ".join(str(val) for _ in range(N)) for _ in range(N)))
        return

    K = 0
    zeros = []
    F = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if A[i][j] == 0:
                K += 1
                zeros.append((i, j))
            else:
                F[i][j] = A[i][j] % p

    ans = mat_pow(F, p, p)

    correction = [[0] * N for _ in range(N)]
    for u, v in zeros:
        if u == v:
            for j in range(N):
                correction[u][j] += F[u][j]
            for i in range(N):
                correction[i][u] += F[i][u]
        elif p == 3:
            correction[u][v] += F[v][u]

    sign = p - 1 if K % 2 else 1
    for i in range(N):
        row = []
        for j in range(N):
            row.append(str(((ans[i][j] + correction[i][j]) % p) * sign % p))
        print(" ".join(row))

if __name__ == "__main__":
    main()

import sys
import math

def build_primes(limit: int):
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0:2] = b"\x00\x00"
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            start = i * i
            sieve[start:limit + 1:i] = b"\x00" * (((limit - start) // i) + 1)
    return [i for i in range(limit + 1) if sieve[i]]

PRIMES = build_primes(31623)

def factorize(n: int):
    res = []
    x = n
    for p in PRIMES:
        if p * p > x:
            break
        if x % p == 0:
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            res.append((p, e))
    if x > 1:
        res.append((x, 1))
    return res

def crt_pair(x, mod, r, m):
    t = ((r - x) % m) * pow(mod % m, -1, m) % m
    return x + mod * t, mod * m

def solve_one(n: int):
    if n == 1:
        return 1, 1

    x, mod = 0, 1

    for p, e in factorize(n):
        if p == 2:
            if e == 1:
                m, r = 4, 3
            else:
                m, r = 1 << (e + 2), 5
        else:
            m, r = p ** (e + 1), p + 1

        x, mod = crt_pair(x, mod, r, m)

    return x, mod

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    t = data[0]
    out = []
    for i in range(1, t + 1):
        a, m = solve_one(data[i])
        out.append(f"{a} {m}")
    print("\n".join(out))

if __name__ == "__main__":
    main()

