import sys

MOD = 998244353

def main():
    input = sys.stdin.readline
    N = int(input())
    A = list(map(int, input().split()))

    exps = {}

    for i, x in enumerate(A):
        t = x
        p = 2
        while p * p <= t:
            if t % p == 0:
                c = 0
                while t % p == 0:
                    t //= p
                    c += 1
                if p not in exps:
                    exps[p] = [0] * (N - 1)
                exps[p][i] = c
            p += 1
        if t > 1:
            if t not in exps:
                exps[t] = [0] * (N - 1)
            exps[t][i] = 1

    ans = 1

    for p, diff in exps.items():
        D = sum(diff)

        pow_p = [1] * (D + 1)
        for i in range(1, D + 1):
            pow_p[i] = pow_p[i - 1] * p % MOD

        unseen_zero = [0] * (D + 1)
        seen_zero = [0] * (D + 1)

        seen_zero[0] = 1
        for h in range(1, D + 1):
            unseen_zero[h] = pow_p[h]

        for d in diff:
            next_unseen = [0] * (D + 1)
            next_seen = [0] * (D + 1)

            if d == 0:
                for h in range(D + 1):
                    w = pow_p[h]
                    if unseen_zero[h]:
                        next_unseen[h] = unseen_zero[h] * w % MOD
                    if seen_zero[h]:
                        next_seen[h] = seen_zero[h] * w % MOD
            else:
                for h in range(D + 1):
                    a = unseen_zero[h]
                    b = seen_zero[h]
                    if not a and not b:
                        continue

                    nh = h + d
                    if nh <= D:
                        w = pow_p[nh]
                        if a:
                            next_unseen[nh] = (next_unseen[nh] + a * w) % MOD
                        if b:
                            next_seen[nh] = (next_seen[nh] + b * w) % MOD

                    nh = h - d
                    if nh >= 0:
                        w = pow_p[nh]
                        if a:
                            if nh == 0:
                                next_seen[nh] = (next_seen[nh] + a * w) % MOD
                            else:
                                next_unseen[nh] = (next_unseen[nh] + a * w) % MOD
                        if b:
                            next_seen[nh] = (next_seen[nh] + b * w) % MOD

            unseen_zero, seen_zero = next_unseen, next_seen

        ans = ans * (sum(seen_zero) % MOD) % MOD

    print(ans)

if __name__ == "__main__":
    main()

import sys

MOD = 998244353
ID = 9          # bits for 0->0 and 1->1
BLOCK = 12

# Relation bit layout: bit (a*2+b) means state a can move to state b.
MATS = (
    (2, 9, 4),        # s_i = 0, labels d = 0,1,2
    (2, 11, 13, 4),   # s_i = 1, labels d = 0,1,2,3
)


def compose(a, b):
    c = 0
    if a & 1:
        c |= b & 3
    if a & 2:
        c |= (b & 12) >> 2
    if a & 4:
        c |= (b & 3) << 2
    if a & 8:
        c |= b & 12
    return c


TRANS = []
for mats in MATS:
    arr = []
    for mask in range(16):
        counts = {}
        for m in mats:
            nm = compose(mask, m)
            if nm:
                counts[nm] = counts.get(nm, 0) + 1
        arr.append(tuple(counts.items()))
    TRANS.append(arr)


cache = {}


def build_block(pattern):
    block = [()] * 16
    for src in range(1, 16):
        vec = {src: 1}
        for pos in range(BLOCK - 1, -1, -1):
            tr = TRANS[(pattern >> pos) & 1]
            nxt = {}
            for st, val in vec.items():
                for nm, cnt in tr[st]:
                    nxt[nm] = nxt.get(nm, 0) + val * cnt
            vec = nxt
        block[src] = tuple(vec.items())
    return block


def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    n = int(data[0])
    s = data[1]

    dp = [0] * 16
    dp[ID] = 1

    i = 0
    while i + BLOCK <= n:
        pattern = 0
        end = i + BLOCK
        while i < end:
            pattern = (pattern << 1) | (s[i] & 1)
            i += 1

        block = cache.get(pattern)
        if block is None:
            block = build_block(pattern)
            cache[pattern] = block

        ndp = [0] * 16
        for src in range(1, 16):
            v = dp[src]
            if v:
                for dst, cnt in block[src]:
                    ndp[dst] += v * cnt
        for j in range(1, 16):
            ndp[j] %= MOD
        dp = ndp

    while i < n:
        tr = TRANS[s[i] & 1]
        ndp = [0] * 16
        for src in range(1, 16):
            v = dp[src]
            if v:
                for dst, cnt in tr[src]:
                    ndp[dst] += v * cnt
        for j in range(1, 16):
            ndp[j] %= MOD
        dp = ndp
        i += 1

    ans = sum(dp[m] for m in range(1, 16) if m & ID) % MOD
    print(ans)


if __name__ == "__main__":
    main()

import sys

MOD = 998244353
G = 3


def ntt(a, invert=False):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(G, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)
        half = length >> 1
        for i in range(0, n, length):
            w = 1
            for k in range(i, i + half):
                u = a[k]
                v = a[k + half] * w % MOD
                x = u + v
                y = u - v
                if x >= MOD:
                    x -= MOD
                if y < 0:
                    y += MOD
                a[k] = x
                a[k + half] = y
                w = w * wlen % MOD
        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD


def convolution(a, b):
    if not a or not b:
        return []
    if len(a) * len(b) <= 40000:
        res = [0] * (len(a) + len(b) - 1)
        for i, x in enumerate(a):
            if x:
                for j, y in enumerate(b):
                    res[i + j] = (res[i + j] + x * y) % MOD
        return res

    need = len(a) + len(b) - 1
    n = 1
    while n < need:
        n <<= 1

    fa = a[:] + [0] * (n - len(a))
    fb = b[:] + [0] * (n - len(b))
    ntt(fa)
    ntt(fb)
    for i in range(n):
        fa[i] = fa[i] * fb[i] % MOD
    ntt(fa, True)
    return fa[:need]


def main():
    input = sys.stdin.readline
    N = int(input())
    S = input().strip()

    if S[0] != "B" or S[-1] != "W":
        print(0)
        return

    a = [0] * N
    whites = 0
    blacks = 0
    for c in S:
        if c == "W":
            whites += 1
        else:
            blacks += 1
            if blacks >= 2:
                a[blacks - 1] = whites

    fac = [1] * (N + 1)
    invfac = [1] * (N + 1)
    for i in range(1, N + 1):
        fac[i] = fac[i - 1] * i % MOD
    invfac[N] = pow(fac[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        invfac[i - 1] = invfac[i] * i % MOD

    active = [False] * N
    for j in range(1, N):
        active[j] = a[j] >= j

    h = [0] * N
    acc = [0] * N
    h[0] = 1

    def add_contrib(l, mid, r):
        js = [j for j in range(mid, r) if active[j]]
        if not js:
            return

        left = h[l:mid]
        if not any(left):
            return

        xmin = a[js[0]]
        xmax = a[js[-1]]
        k0 = xmin - mid + 1
        kernel = [fac[k0 + t] for t in range(xmax - xmin + mid - l)]
        conv = convolution(left, kernel)
        shift = l + k0

        for j in js:
            acc[j] = (acc[j] + conv[a[j] - shift]) % MOD

    sys.setrecursionlimit(1_000_000)

    def cdq(l, r):
        if r - l == 1:
            if l == 0:
                h[l] = 1
            elif active[l]:
                h[l] = (-acc[l] * invfac[a[l] - l]) % MOD
            else:
                h[l] = 0
            return

        mid = (l + r) >> 1
        cdq(l, mid)
        add_contrib(l, mid, r)
        cdq(mid, r)

    cdq(0, N)

    ans = 0
    for i in range(N):
        ans = (ans + h[i] * fac[N - i]) % MOD
    print(ans)


if __name__ == "__main__":
    main()

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        import bisect

        star1 = p.index('*')
        star2 = p.index('*', star1 + 1)
        A = p[:star1]
        B = p[star1 + 1:star2]
        C = p[star2 + 1:]

        def kmp_all(text: str, pat: str):
            if not pat:
                return list(range(len(text) + 1))

            m = len(pat)
            lps = [0] * m
            j = 0

            for i in range(1, m):
                while j and pat[i] != pat[j]:
                    j = lps[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                lps[i] = j

            res = []
            j = 0
            for i, ch in enumerate(text):
                while j and ch != pat[j]:
                    j = lps[j - 1]
                if ch == pat[j]:
                    j += 1
                if j == m:
                    res.append(i - m + 1)
                    j = lps[j - 1]

            return res

        occA = kmp_all(s, A)
        occB = kmp_all(s, B)
        occC = kmp_all(s, C)

        lenA, lenB, lenC = len(A), len(B), len(C)
        ans = float("inf")

        for i in occA:
            idxB = bisect.bisect_left(occB, i + lenA)
            if idxB == len(occB):
                break

            j = occB[idxB]
            idxC = bisect.bisect_left(occC, j + lenB)
            if idxC == len(occC):
                break

            k = occC[idxC]
            ans = min(ans, k + lenC - i)

        return -1 if ans == float("inf") else ans

class Solution:
    def countSubstrings(self, s: str) -> int:
        cnt3 = [0] * 3
        cnt9 = [0] * 9
        cnt7 = [0] * 7
        cnt3[0] = cnt9[0] = cnt7[0] = 1

        d3 = d9 = q7 = 0
        pow5 = 1
        ans = 0

        for j, ch in enumerate(s):
            d = ord(ch) - ord('0')

            d3 = (d3 + d) % 3
            d9 = (d9 + d) % 9
            pow5 = (pow5 * 5) % 7
            q7 = (q7 + d * pow5) % 7

            if d in (1, 2, 5):
                ans += j + 1
            elif d == 3 or d == 6:
                ans += cnt3[d3]
            elif d == 9:
                ans += cnt9[d9]
            elif d == 4:
                ans += 1
                if j >= 1 and (int(s[j - 1]) * 10 + d) % 4 == 0:
                    ans += j
            elif d == 8:
                ans += 1
                if j >= 1 and (int(s[j - 1]) * 10 + d) % 8 == 0:
                    ans += 1
                if j >= 2 and (int(s[j - 2]) * 100 + int(s[j - 1]) * 10 + d) % 8 == 0:
                    ans += j - 1
            elif d == 7:
                ans += cnt7[q7]

            cnt3[d3] += 1
            cnt9[d9] += 1
            cnt7[q7] += 1

        return ans

from functools import lru_cache
from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = ((1, 1), (1, -1), (-1, -1), (-1, 1))

        @lru_cache(None)
        def dp(r: int, c: int, d: int, turned: int, expected: int) -> int:
            if not (0 <= r < n and 0 <= c < m) or grid[r][c] != expected:
                return 0

            next_expected = 0 if expected == 2 else 2
            dr, dc = dirs[d]

            best = 1 + dp(r + dr, c + dc, d, turned, next_expected)

            if not turned:
                nd = (d + 1) % 4
                ndr, ndc = dirs[nd]
                best = max(best, 1 + dp(r + ndr, c + ndc, nd, 1, next_expected))

            return best

        ans = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    ans = max(ans, 1)
                    for d, (dr, dc) in enumerate(dirs):
                        ans = max(ans, 1 + dp(r + dr, c + dc, d, 0, 2))

        return ans

from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can(target: int) -> bool:
            moves = 0
            carry = 0

            for i, p in enumerate(points):
                need = (target + p - 1) // p

                if i == n - 1:
                    if carry < need:
                        moves += 1
                        visits = carry + 1
                        if visits < need:
                            moves += 2 * (need - visits)
                    return moves <= m

                moves += 1
                visits = carry + 1

                if visits < need:
                    extra = need - visits
                    moves += 2 * extra
                    carry = extra
                else:
                    carry = 0

                if moves > m:
                    return False

            return True

        left, right = 0, max(points) * m
        while left < right:
            mid = (left + right + 1) // 2
            if can(mid):
                left = mid
            else:
                right = mid - 1

        return left

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        ans = ['a'] * L
        fixed = [False] * L

        for i, c in enumerate(str1):
            if c == 'T':
                for j, ch in enumerate(str2):
                    k = i + j
                    if fixed[k] and ans[k] != ch:
                        return ""
                    ans[k] = ch
                    fixed[k] = True

        for i, c in enumerate(str1):
            if c != 'F':
                continue

            differs = False
            candidate = -1

            for j, ch in enumerate(str2):
                k = i + j
                if ans[k] != ch:
                    differs = True
                    break
                if not fixed[k]:
                    candidate = k

            if differs:
                continue

            if candidate == -1:
                return ""

            ans[candidate] = 'b' if ans[candidate] == 'a' else 'a'

        res = ''.join(ans)

        for i, c in enumerate(str1):
            sub = res[i:i + m]
            if c == 'T' and sub != str2:
                return ""
            if c == 'F' and sub == str2:
                return ""

        return res

from typing import List
from collections import defaultdict

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        OVER = limit + 1
        dp = [defaultdict(set), defaultdict(set)]

        for x in nums:
            ndp = [defaultdict(set), defaultdict(set)]

            for p in range(2):
                for s, products in dp[p].items():
                    ndp[p][s].update(products)

                    ns = s + x if p == 0 else s - x
                    np = 1 - p
                    for prod in products:
                        if prod == OVER:
                            new_prod = 0 if x == 0 else OVER
                        else:
                            val = prod * x
                            new_prod = val if val <= limit else OVER
                        ndp[np][ns].add(new_prod)

            ndp[1][x].add(x if x <= limit else OVER)
            dp = ndp

        ans = -1
        for p in range(2):
            for prod in dp[p].get(k, ()):
                if prod != OVER:
                    ans = max(ans, prod)

        return ans

from typing import List
from math import factorial

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        available = list(range(1, n + 1))
        result = []
        rem_odd = (n + 1) // 2
        rem_even = n // 2
        prev_parity = -1

        for _ in range(n):
            picked = False

            for i, val in enumerate(available):
                parity = val % 2

                if prev_parity != -1 and parity == prev_parity:
                    continue

                next_odd = rem_odd - (parity == 1)
                next_even = rem_even - (parity == 0)

                if next_odd + next_even == 0:
                    count = 1
                else:
                    required_start = 1 - parity
                    if required_start == 1:
                        feasible = next_odd == next_even or next_odd == next_even + 1
                    else:
                        feasible = next_even == next_odd or next_even == next_odd + 1

                    count = factorial(next_odd) * factorial(next_even) if feasible else 0

                if k > count:
                    k -= count
                else:
                    result.append(val)
                    available.pop(i)
                    rem_odd = next_odd
                    rem_even = next_even
                    prev_parity = parity
                    picked = True
                    break

            if not picked:
                return []

        return result

from typing import List
from collections import defaultdict

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = defaultdict(list)

        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, i))

        max1 = 0
        max2 = 0
        count1 = 0
        unique_idx = -1

        baseline = 0
        gain = [0] * len(conflictingPairs)

        for r in range(1, n + 1):
            for a, idx in by_right[r]:
                if a > max1:
                    max2 = max1
                    max1 = a
                    count1 = 1
                    unique_idx = idx
                elif a == max1:
                    count1 += 1
                    unique_idx = -1
                elif a > max2:
                    max2 = a

            baseline += r - max1

            if count1 == 1:
                gain[unique_idx] += max1 - max2

        return baseline + max(gain)

from functools import lru_cache

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        return self._count(r) - self._count(l - 1)

    def _count(self, n: int) -> int:
        if n <= 0:
            return 0

        digits = list(map(int, str(n)))
        length = len(digits)
        ans = 0

        for target_sum in range(1, 9 * length + 1):
            @lru_cache(None)
            def dp(pos: int, digit_sum: int, prod_mod: int, tight: bool, started: bool) -> int:
                if digit_sum > target_sum:
                    return 0

                if pos == length:
                    return int(started and digit_sum == target_sum and prod_mod == 0)

                limit = digits[pos] if tight else 9
                total = 0

                for d in range(limit + 1):
                    next_tight = tight and d == limit

                    if not started and d == 0:
                        total += dp(pos + 1, 0, 1, next_tight, False)
                    else:
                        total += dp(
                            pos + 1,
                            digit_sum + d,
                            (prod_mod * d) % target_sum,
                            next_tight,
                            True,
                        )

                return total

            ans += dp(0, 0, 1, True, False)

        return ans

import sys

MOD = 998244353

def solve():
    data = sys.stdin.buffer.read().split()
    N = int(data[0])
    M = int(data[1])
    A = [int(x) - 1 for x in data[2:2 + N]]

    on_cycle = [False] * N
    visited = [False] * N
    cycles = []

    for start in range(N):
        if visited[start]:
            continue

        path = []
        pos = {}
        u = start

        while not visited[u] and u not in pos:
            pos[u] = len(path)
            path.append(u)
            u = A[u]

        if u in pos:
            cycle = path[pos[u]:]
            cycles.append(cycle)
            for v in cycle:
                on_cycle[v] = True

        for v in path:
            visited[v] = True

    children = [[] for _ in range(N)]
    for i, p in enumerate(A):
        children[p].append(i)

    f = [None] * N
    order = []

    for cycle in cycles:
        for root in cycle:
            for child in children[root]:
                if on_cycle[child]:
                    continue

                stack = [(child, False)]
                while stack:
                    u, done = stack.pop()
                    if done:
                        order.append(u)
                    else:
                        stack.append((u, True))
                        for v in children[u]:
                            stack.append((v, False))

    for u in order:
        ways_exact = [1] * (M + 1)

        for child in children[u]:
            fc = f[child]
            for v in range(1, M + 1):
                ways_exact[v] = ways_exact[v] * fc[v] % MOD

        fu = [0] * (M + 1)
        prefix = 0
        for v in range(1, M + 1):
            prefix = (prefix + ways_exact[v]) % MOD
            fu[v] = prefix

        f[u] = fu

    ans = 1

    for cycle in cycles:
        ways = [1] * (M + 1)

        for u in cycle:
            for child in children[u]:
                if on_cycle[child]:
                    continue

                fc = f[child]
                for v in range(1, M + 1):
                    ways[v] = ways[v] * fc[v] % MOD

        total = sum(ways[1:]) % MOD
        ans = ans * total % MOD

    print(ans)

if __name__ == "__main__":
    solve()

