import sys

MOD = 998244353

def solve():
    data = sys.stdin.read().split()
    N = int(data[0])
    M = int(data[1])
    S = data[2]

    size = 1 << N
    s_vals = [ord(ch) - ord('a') for ch in S]

    trans = [[0] * 26 for _ in range(size)]

    for mask in range(size):
        prev = [0] * (N + 1)
        for i in range(N):
            prev[i + 1] = prev[i] + ((mask >> i) & 1)

        for c in range(26):
            cur = [0] * (N + 1)
            for i in range(1, N + 1):
                if s_vals[i - 1] == c:
                    cur[i] = prev[i - 1] + 1
                else:
                    cur[i] = max(prev[i], cur[i - 1])

            nxt = 0
            for i in range(N):
                if cur[i + 1] - cur[i] == 1:
                    nxt |= 1 << i
            trans[mask][c] = nxt

    dp = [0] * size
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * size
        for mask, val in enumerate(dp):
            if val == 0:
                continue
            for nxt in trans[mask]:
                ndp[nxt] = (ndp[nxt] + val) % MOD
        dp = ndp

    ans = [0] * (N + 1)
    for mask, val in enumerate(dp):
        ans[mask.bit_count()] = (ans[mask.bit_count()] + val) % MOD

    print(*ans)

if __name__ == "__main__":
    solve()

import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N = data[0]
    P = data[1:]

    bit = [0] * (N + 1)

    def add(i, x):
        while i <= N:
            bit[i] += x
            i += i & -i

    for i in range(1, N + 1):
        add(i, 1)

    bit_mask = 1
    while bit_mask * 2 <= N:
        bit_mask *= 2

    def kth(k):
        idx = 0
        mask = bit_mask
        while mask:
            nxt = idx + mask
            if nxt <= N and bit[nxt] < k:
                idx = nxt
                k -= bit[nxt]
            mask >>= 1
        return idx + 1

    ans = [0] * N

    for i in range(N, 0, -1):
        pos = kth(P[i - 1])
        ans[pos - 1] = i
        add(pos, -1)

    print(*ans)

