import sys
from collections import deque

def solve():
    input = sys.stdin.readline
    N = int(input())
    C = [input().strip() for _ in range(N)]

    dist = [[-1] * N for _ in range(N)]
    in_edges = [[[] for _ in range(26)] for _ in range(N)]
    out_edges = [[[] for _ in range(26)] for _ in range(N)]

    for i in range(N):
        for j, ch in enumerate(C[i]):
            if ch != '-':
                k = ord(ch) - ord('a')
                out_edges[i][k].append(j)
                in_edges[j][k].append(i)

    q = deque()

    for i in range(N):
        dist[i][i] = 0
        q.append((i, i))

    for i in range(N):
        for j, ch in enumerate(C[i]):
            if ch != '-' and dist[i][j] == -1:
                dist[i][j] = 1
                q.append((i, j))

    while q:
        u, v = q.popleft()
        nd = dist[u][v] + 2

        for c in range(26):
            for a in in_edges[u][c]:
                row = dist[a]
                for b in out_edges[v][c]:
                    if row[b] == -1:
                        row[b] = nd
                        q.append((a, b))

    print('\n'.join(' '.join(map(str, row)) for row in dist))

if __name__ == "__main__":
    solve()

import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    adj = [[] for _ in range(n + 1)]
    idx = 1
    for _ in range(n - 1):
        a = data[idx]
        b = data[idx + 1]
        idx += 2
        adj[a].append(b)
        adj[b].append(a)

    active = [False] * (n + 1)
    for v in range(1, n + 1):
        active[v] = len(adj[v]) >= 4

    parent = [0] * (n + 1)
    visited = [False] * (n + 1)
    dp = [0] * (n + 1)
    best = 0

    for root in range(1, n + 1):
        if not active[root] or visited[root]:
            continue

        visited[root] = True
        parent[root] = -1
        stack = [root]
        order = []

        while stack:
            u = stack.pop()
            order.append(u)
            for v in adj[u]:
                if active[v] and not visited[v]:
                    visited[v] = True
                    parent[v] = u
                    stack.append(v)

        for u in reversed(order):
            t1 = t2 = t3 = t4 = 0

            for v in adj[u]:
                if active[v] and parent[v] == u:
                    x = dp[v]
                    if x > t1:
                        t1, t2, t3, t4 = x, t1, t2, t3
                    elif x > t2:
                        t2, t3, t4 = x, t2, t3
                    elif x > t3:
                        t3, t4 = x, t3
                    elif x > t4:
                        t4 = x

            dp[u] = 1 + t1 + t2 + t3
            best = max(best, 1 + t1 + t2 + t3 + t4)

    if best == 0:
        print(-1)
    else:
        print(3 * best + 2)

