import math

def solve():
    N = int(input())

    def icbrt(n):
        lo, hi = 0, 1
        while hi ** 3 <= n:
            hi *= 2
        while hi - lo > 1:
            mid = (lo + hi) // 2
            if mid ** 3 <= n:
                lo = mid
            else:
                hi = mid
        return lo

    for d in range(1, icbrt(N - 1) + 1):
        if N % d != 0:
            continue

        q = N // d
        disc = 12 * q - 3 * d * d
        if disc < 0:
            continue

        s = math.isqrt(disc)
        if s * s != disc:
            continue

        num = -3 * d + s
        if num <= 0 or num % 6 != 0:
            continue

        y = num // 6
        x = y + d
        if y > 0 and x ** 3 - y ** 3 == N:
            print(x, y)
            return

    print(-1)

solve()

