def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, K = data[0], data[1]
    M = N * K

    if K == 1:
        print("Yes")
        return

    adj = [[] for _ in range(M)]
    idx = 2
    for _ in range(M - 1):
        u = data[idx] - 1
        v = data[idx + 1] - 1
        idx += 2
        adj[u].append(v)
        adj[v].append(u)

    parent = [-1] * M
    order = [0]
    parent[0] = 0

    for u in order:
        for v in adj[u]:
            if parent[v] == -1:
                parent[v] = u
                order.append(v)

    rem = [0] * M

    for u in reversed(order):
        open_paths = []

        for v in adj[u]:
            if v == parent[u]:
                continue
            if rem[v] != K:
                open_paths.append(rem[v])

        if len(open_paths) > 2:
            print("No")
            return

        if len(open_paths) == 0:
            rem[u] = 1
        elif len(open_paths) == 1:
            rem[u] = open_paths[0] + 1
            if rem[u] > K:
                print("No")
                return
        else:
            if open_paths[0] + open_paths[1] + 1 != K:
                print("No")
                return
            rem[u] = K

