import sys

def solve():
    input = sys.stdin.buffer.readline
    N = int(input())
    A = list(map(int, input().split()))

    L = [0] * (N + 1)
    seen = [False] * (N + 1)
    cnt = 0
    for i, x in enumerate(A, 1):
        if not seen[x]:
            seen[x] = True
            cnt += 1
        L[i] = cnt

    R = [0] * (N + 1)
    seen = [False] * (N + 1)
    cnt = 0
    for i in range(N - 1, -1, -1):
        x = A[i]
        if not seen[x]:
            seen[x] = True
            cnt += 1
        R[i] = cnt

    size = 1
    while size < N + 1:
        size <<= 1

    neg = -10**18
    seg = [neg] * (2 * size)
    lazy = [0] * (2 * size)

    for i in range(N + 1):
        seg[size + i] = L[i]
    for i in range(size - 1, 0, -1):
        seg[i] = max(seg[i << 1], seg[i << 1 | 1])

    def apply(node, val):
        seg[node] += val
        lazy[node] += val

    def range_add(l, r, val, node=1, nl=0, nr=None):
        if nr is None:
            nr = size - 1
        if r < nl or nr < l:
            return
        if l <= nl and nr <= r:
            apply(node, val)
            return
        mid = (nl + nr) >> 1
        range_add(l, r, val, node << 1, nl, mid)
        range_add(l, r, val, node << 1 | 1, mid + 1, nr)
        seg[node] = max(seg[node << 1], seg[node << 1 | 1]) + lazy[node]

    def range_max(l, r, node=1, nl=0, nr=None):
        if nr is None:
            nr = size - 1
        if r < nl or nr < l:
            return neg
        if l <= nl and nr <= r:
            return seg[node]
        mid = (nl + nr) >> 1
        return lazy[node] + max(
            range_max(l, r, node << 1, nl, mid),
            range_max(l, r, node << 1 | 1, mid + 1, nr),
        )

    last = [-1] * (N + 1)
    ans = 0

    for j in range(1, N):
        x = A[j - 1]
        l = last[x] + 1
        r = j - 1
        if l <= r:
            range_add(l, r, 1)
        last[x] = r

        if j >= 2:
            ans = max(ans, range_max(1, j - 1) + R[j])

    print(ans)

if __name__ == "__main__":
    solve()

import sys
from collections import deque

def solve():
    input = sys.stdin.readline
    N, M, K = map(int, input().split())
    edges = [tuple(int(x) - 1 for x in input().split()) for _ in range(M)]

    INF = 10 ** 9

    def ok(d):
        if d == 0:
            return True

        def vid(v, dist):
            return v * d + dist

        V = N * d + 2
        S = N * d
        T = S + 1
        g = [[] for _ in range(V)]

        def add(fr, to, cap):
            g[fr].append([to, cap, len(g[to])])
            g[to].append([fr, 0, len(g[fr]) - 1])

        add(S, vid(0, 0), INF)
        for i in range(d):
            add(vid(N - 1, i), T, INF)

        for v in range(N):
            for i in range(d - 1):
                add(vid(v, i + 1), vid(v, i), INF)

        for u, v in edges:
            for i in range(d):
                add(vid(u, i), vid(v, i), INF)
                if i + 1 < d:
                    add(vid(u, i), vid(v, i + 1), 1)
                else:
                    add(vid(u, i), T, 1)

        flow = 0

        while True:
            level = [-1] * V
            level[S] = 0
            q = deque([S])
            while q:
                x = q.popleft()
                for to, cap, _ in g[x]:
                    if cap > 0 and level[to] == -1:
                        level[to] = level[x] + 1
                        q.append(to)

            if level[T] == -1:
                break

            it = [0] * V

            def dfs(x, f):
                if x == T:
                    return f
                while it[x] < len(g[x]):
                    e = g[x][it[x]]
                    to, cap, rev = e
                    if cap > 0 and level[to] == level[x] + 1:
                        ret = dfs(to, min(f, cap))
                        if ret:
                            e[1] -= ret
                            g[to][rev][1] += ret
                            return ret
                    it[x] += 1
                return 0

            while True:
                pushed = dfs(S, INF)
                if pushed == 0:
                    break
                flow += pushed
                if flow > K:
                    return False

        return flow <= K

    ans = 0
    for d in range(min(K, N - 1), -1, -1):
        if ok(d):
            ans = d
            break

    print(ans)

if __name__ == "__main__":
    solve()

