import sys

def solve():
    data = sys.stdin.read().split()
    n = int(data[0])
    s = data[1]
    t = data[2]

    to = [-1] * 26
    used = [False] * 26

    for a, b in zip(s, t):
        x = ord(a) - 97
        y = ord(b) - 97
        used[x] = True
        if to[x] != -1 and to[x] != y:
            print(-1)
            return
        to[x] = y

    ans = 0
    graph = [[] for _ in range(26)]
    indeg = [0] * 26

    for i in range(26):
        if used[i] and to[i] != i:
            ans += 1
            graph[i].append(to[i])
            indeg[to[i]] += 1

    color = [0] * 26
    cycles = 0

    def dfs(v):
        nonlocal cycles
        color[v] = 1
        for nv in graph[v]:
            if color[nv] == 0:
                dfs(nv)
            elif color[nv] == 1:
                cycles += 1
        color[v] = 2

    for i in range(26):
        if color[i] == 0:
            dfs(i)

    if cycles:
        if sum(used) == 26:
            print(-1)
            return
        ans += cycles

    print(ans)

