import sys

def matmul(A, B, mod):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        Ci = C[i]
        Ai = A[i]
        for k in range(n):
            if Ai[k]:
                aik = Ai[k]
                Bk = B[k]
                for j in range(n):
                    Ci[j] = (Ci[j] + aik * Bk[j]) % mod
    return C

def matpow(A, e, mod):
    n = len(A)
    R = [[0] * n for _ in range(n)]
    for i in range(n):
        R[i][i] = 1 % mod
    B = [row[:] for row in A]
    while e:
        if e & 1:
            R = matmul(R, B, mod)
        e >>= 1
        if e:
            B = matmul(B, B, mod)
    return R

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    N = next(it)
    p = next(it)
    A = [[next(it) for _ in range(N)] for _ in range(N)]

    if p == 2:
        B = [[1 if A[i][j] == 0 else A[i][j] for j in range(N)] for i in range(N)]
        ans = matmul(B, B, 2)
    else:
        K = sum(1 for i in range(N) for j in range(N) if A[i][j] == 0)
        ans = matpow(A, p, p)

        extra = [[0] * N for _ in range(N)]
        for u in range(N):
            for v in range(N):
                if A[u][v] != 0:
                    continue

                if u == v:
                    for i in range(N):
                        if A[i][u]:
                            extra[i][u] = (extra[i][u] + A[i][u]) % p
                    for j in range(N):
                        if A[u][j]:
                            extra[u][j] = (extra[u][j] + A[u][j]) % p
                elif A[v][u]:
                    extra[u][v] = (extra[u][v] + (p - 2) * A[v][u]) % p

        sign = p - 1 if K % 2 else 1
        for i in range(N):
            for j in range(N):
                ans[i][j] = sign * ((ans[i][j] + extra[i][j]) % p) % p

    print("\n".join(" ".join(map(str, row)) for row in ans))

if __name__ == "__main__":
    solve()

import sys

MOD = 998244353

def factorize(n):
    res = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            res[d] = res.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        res[n] = res.get(n, 0) + 1
    return res

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N = data[0]
    A = data[1:]

    facs = [factorize(a) for a in A]
    primes = set()
    for f in facs:
        primes.update(f)

    ans = 1

    for p in primes:
        b = [f.get(p, 0) for f in facs]
        B = sum(b)

        pow_p = [1] * (B + 1)
        for i in range(1, B + 1):
            pow_p[i] = pow_p[i - 1] * p % MOD

        dp_no_zero = [0] * (B + 1)
        dp_has_zero = [0] * (B + 1)

        dp_has_zero[0] = 1
        for e in range(1, B + 1):
            dp_no_zero[e] = pow_p[e]

        for bi in b:
            ndp_no_zero = [0] * (B + 1)
            ndp_has_zero = [0] * (B + 1)

            for e in range(B + 1):
                val0 = dp_no_zero[e]
                val1 = dp_has_zero[e]

                if val0:
                    ne = e + bi
                    if ne <= B:
                        ndp_no_zero[ne] = (ndp_no_zero[ne] + val0 * pow_p[ne]) % MOD
                    ne = e - bi
                    if ne >= 0:
                        if ne == 0:
                            ndp_has_zero[ne] = (ndp_has_zero[ne] + val0 * pow_p[ne]) % MOD
                        else:
                            ndp_no_zero[ne] = (ndp_no_zero[ne] + val0 * pow_p[ne]) % MOD

                if val1:
                    ne = e + bi
                    if ne <= B:
                        ndp_has_zero[ne] = (ndp_has_zero[ne] + val1 * pow_p[ne]) % MOD
                    ne = e - bi
                    if ne >= 0:
                        ndp_has_zero[ne] = (ndp_has_zero[ne] + val1 * pow_p[ne]) % MOD

            dp_no_zero = ndp_no_zero
            dp_has_zero = ndp_has_zero

        ans = ans * (sum(dp_has_zero) % MOD) % MOD

    print(ans)

if __name__ == "__main__":
    solve()

import sys

MOD = 998244353

def compose(a, b):
    res = 0
    if ((a & 1) and (b & 1)) or ((a & 2) and (b & 4)):
        res |= 1
    if ((a & 1) and (b & 2)) or ((a & 2) and (b & 8)):
        res |= 2
    if ((a & 4) and (b & 1)) or ((a & 8) and (b & 4)):
        res |= 4
    if ((a & 4) and (b & 2)) or ((a & 8) and (b & 8)):
        res |= 8
    return res

def build_trans(labels):
    trans = []
    for m in range(16):
        counts = {}
        for r in labels:
            t = compose(m, r)
            if t:
                counts[t] = counts.get(t, 0) + 1
        trans.append(tuple(counts.items()))
    return trans

TRANS0 = build_trans((2, 9, 4))
TRANS1 = build_trans((2, 11, 13, 4))

def solve():
    data = sys.stdin.buffer.read().split()
    s = data[1]

    dp = [0] * 16
    dp[9] = 1

    for i, ch in enumerate(s):
        ndp = [0] * 16
        trans = TRANS1 if ch == 49 else TRANS0

        for m, v in enumerate(dp):
            if v:
                for t, mul in trans[m]:
                    ndp[t] += v * mul

        if (i & 7) == 7:
            for j in range(16):
                ndp[j] %= MOD

        dp = ndp

    ans = 0
    for m, v in enumerate(dp):
        if m & 9:
            ans += v

    print(ans % MOD)

if __name__ == "__main__":
    solve()

from typing import List
from bisect import bisect_left

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        items = [(l, r, w, i) for i, (l, r, w) in enumerate(intervals)]
        items.sort(key=lambda x: x[1])  # sort by right endpoint
        ends = [r for _, r, _, _ in items]

        n = len(items)
        NEG = -10**30

        # dp[i][c] = (best_score, lex_smallest_sorted_indices_tuple)
        # using exactly c intervals from the first i items in end-sorted order.
        dp = [[(NEG, ()) for _ in range(5)] for _ in range(n + 1)]
        for i in range(n + 1):
            dp[i][0] = (0, ())

        def better(a, b):
            if b[0] > a[0]:
                return b
            if b[0] == a[0] and b[1] < a[1]:
                return b
            return a

        for i, (l, r, w, idx) in enumerate(items, 1):
            # intervals with end < l (non-overlapping, since shared boundary counts as overlap)
            p = bisect_left(ends, l)

            for c in range(1, 5):
                best = dp[i - 1][c]

                prev_score, prev_indices = dp[p][c - 1]
                if prev_score != NEG:
                    cand_indices = tuple(sorted(prev_indices + (idx,)))
                    cand = (prev_score + w, cand_indices)
                    best = better(best, cand)

                dp[i][c] = best

        ans = (0, ())
        for c in range(1, 5):
            ans = better(ans, dp[n][c])

        return list(ans[1])

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = p.split('*')
        segs = [x for x in parts if x]

        if not segs:
            return 0

        n = len(s)

        def occurrences(pattern: str):
            m = len(pattern)
            if m == 0:
                return []
            lps = [0] * m
            j = 0
            for i in range(1, m):
                while j and pattern[i] != pattern[j]:
                    j = lps[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                    lps[i] = j

            starts = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != pattern[j]:
                    j = lps[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    starts.append(i - m + 1)
                    j = lps[j - 1]
            return starts

        occ = [occurrences(seg) for seg in segs]
        if any(not x for x in occ):
            return -1

        if len(segs) == 1:
            return len(segs[0])

        INF = 10**18

        if len(segs) == 2:
            a, b = segs
            occ_a, occ_b = occ
            j = 0
            ans = INF
            for start_a in occ_a:
                min_b_start = start_a + len(a)
                while j < len(occ_b) and occ_b[j] < min_b_start:
                    j += 1
                if j < len(occ_b):
                    ans = min(ans, occ_b[j] + len(b) - start_a)
                else:
                    break
            return -1 if ans == INF else ans

        a, b, c = segs
        occ_a, occ_b, occ_c = occ

        next_c = [INF] * (n + 2)
        idx = len(occ_c) - 1
        best = INF
        for pos in range(n + 1, -1, -1):
            while idx >= 0 and occ_c[idx] >= pos:
                best = occ_c[idx]
                idx -= 1
            next_c[pos] = best

        j = 0
        ans = INF
        for start_a in occ_a:
            min_b_start = start_a + len(a)
            while j < len(occ_b) and occ_b[j] < min_b_start:
                j += 1
            if j == len(occ_b):
                break

            start_b = occ_b[j]
            min_c_start = start_b + len(b)
            if min_c_start <= n and next_c[min_c_start] != INF:
                ans = min(ans, next_c[min_c_start] + len(c) - start_a)

        return -1 if ans == INF else ans

class Solution:
    def countSubstrings(self, s: str) -> int:
        counts = [None] + [[0] * m for m in range(1, 10)]
        ans = 0

        for ch in s:
            digit = ord(ch) - ord('0')

            for mod in range(1, 10):
                old = counts[mod]
                new = [0] * mod

                for rem, cnt in enumerate(old):
                    if cnt:
                        new[(rem * 10 + digit) % mod] += cnt

                new[digit % mod] += 1
                counts[mod] = new

            if digit != 0:
                ans += counts[digit][0]

        return ans

from typing import List


class Fenwick:
    def __init__(self, n: int):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i: int, delta: int) -> None:
        while i <= self.n:
            self.bit[i] += delta
            i += i & -i

    def sum(self, i: int) -> int:
        res = 0
        while i > 0:
            res += self.bit[i]
            i -= i & -i
        return res

    def kth(self, k: int) -> int:
        idx = 0
        step = 1 << (self.n.bit_length() - 1) if self.n > 0 else 0
        while step:
            nxt = idx + step
            if nxt <= self.n and self.bit[nxt] < k:
                idx = nxt
                k -= self.bit[nxt]
            step >>= 1
        return idx + 1


class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)
        vals = sorted(set(nums))
        comp = {v: i + 1 for i, v in enumerate(vals)}

        count_bit = Fenwick(len(vals))
        sum_bit = Fenwick(len(vals))
        total_sum = 0
        costs = []

        def add_value(v: int, sign: int) -> None:
            nonlocal total_sum
            idx = comp[v]
            count_bit.add(idx, sign)
            sum_bit.add(idx, sign * v)
            total_sum += sign * v

        def window_cost() -> int:
            median_pos = (x + 1) // 2
            mid_idx = count_bit.kth(median_pos)
            median = vals[mid_idx - 1]

            left_count = count_bit.sum(mid_idx)
            left_sum = sum_bit.sum(mid_idx)

            return (
                median * left_count - left_sum
                + (total_sum - left_sum) - median * (x - left_count)
            )

        for i in range(x):
            add_value(nums[i], 1)
        costs.append(window_cost())

        for start in range(1, n - x + 1):
            add_value(nums[start - 1], -1)
            add_value(nums[start + x - 1], 1)
            costs.append(window_cost())

        INF = 10 ** 30
        prev = [0] * (n + 1)

        for _ in range(1, k + 1):
            cur = [INF] * (n + 1)
            for i in range(1, n + 1):
                cur[i] = cur[i - 1]
                if i >= x:
                    cand = prev[i - x] + costs[i - x]
                    if cand < cur[i]:
                        cur[i] = cand
            prev = cur

        return prev[n]

from typing import List

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def bounded_pairs(left: int, right: int) -> int:
            # Count pairs (l, r): 1 <= l <= left, 1 <= r <= right, l + r - 1 <= k
            limit = k + 1
            m = min(left, limit - 1)
            if m <= 0:
                return 0

            full = min(m, max(0, limit - right))
            total = full * right

            cnt = m - full
            if cnt > 0:
                # Sum_{x=full+1..m} (limit - x)
                total += cnt * limit - (full + 1 + m) * cnt // 2

            return total

        def contribution(is_min: bool) -> int:
            prev = [-1] * n
            nxt = [n] * n
            stack = []

            if is_min:
                # Previous strictly smaller
                for i, x in enumerate(nums):
                    while stack and nums[stack[-1]] >= x:
                        stack.pop()
                    prev[i] = stack[-1] if stack else -1
                    stack.append(i)

                stack.clear()

                # Next smaller or equal
                for i in range(n - 1, -1, -1):
                    x = nums[i]
                    while stack and nums[stack[-1]] > x:
                        stack.pop()
                    nxt[i] = stack[-1] if stack else n
                    stack.append(i)
            else:
                # Previous strictly greater
                for i, x in enumerate(nums):
                    while stack and nums[stack[-1]] <= x:
                        stack.pop()
                    prev[i] = stack[-1] if stack else -1
                    stack.append(i)

                stack.clear()

                # Next greater or equal
                for i in range(n - 1, -1, -1):
                    x = nums[i]
                    while stack and nums[stack[-1]] < x:
                        stack.pop()
                    nxt[i] = stack[-1] if stack else n
                    stack.append(i)

            total = 0
            for i, x in enumerate(nums):
                left = i - prev[i]
                right = nxt[i] - i
                total += x * bounded_pairs(left, right)

            return total

        return contribution(True) + contribution(False)

from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        # alt[d][i][j]: longest 2/0 alternating diagonal run starting at (i, j)
        # in direction d, including (i, j). Cells with value 1 cannot be in this suffix.
        alt = []
        for dr, dc in dirs:
            dp = [[0] * m for _ in range(n)]
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)

            for i in rows:
                for j in cols:
                    v = grid[i][j]
                    if v == 1:
                        continue

                    dp[i][j] = 1
                    ni, nj = i + dr, j + dc
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 2 - v:
                        dp[i][j] += dp[ni][nj]

            alt.append(dp)

        ans = 0

        for d, (dr, dc) in enumerate(dirs):
            # pref[i][j]: longest valid straight segment ending at (i, j)
            # while moving in direction d, starting from a 1.
            pref = [[0] * m for _ in range(n)]

            rows = range(n) if dr == 1 else range(n - 1, -1, -1)
            cols = range(m) if dc == 1 else range(m - 1, -1, -1)

            turn_dir = (d + 1) % 4
            tr, tc = dirs[turn_dir]

            for i in rows:
                for j in cols:
                    v = grid[i][j]
                    cur = 0

                    if v == 1:
                        cur = 1
                    else:
                        pi, pj = i - dr, j - dc
                        if 0 <= pi < n and 0 <= pj < m:
                            prev = pref[pi][pj]
                            expected = 2 if prev % 2 == 1 else 0
                            if prev > 0 and v == expected:
                                cur = prev + 1

                    pref[i][j] = cur

                    if cur == 0:
                        continue

                    ans = max(ans, cur)

                    expected_next = 2 if cur % 2 == 1 else 0
                    ni, nj = i + tr, j + tc

                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == expected_next:
                        ans = max(ans, cur + alt[turn_dir][ni][nj])

        return ans

from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def prefix_steps(n: int) -> int:
            total = 0
            start = 1
            steps = 1
            while start <= n:
                end = min(n, start * 4 - 1)
                total += (end - start + 1) * steps
                start *= 4
                steps += 1
            return total

        ans = 0
        for l, r in queries:
            total_steps = prefix_steps(r) - prefix_steps(l - 1)
            ans += (total_steps + 1) // 2
        return ans

from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can(target: int) -> bool:
            if target == 0:
                return True

            moves = 0
            prev_visits = 0  # visits already given to current index from bouncing at previous index

            for i, p in enumerate(points):
                need = (target + p - 1) // p

                if need > prev_visits:
                    extra = need - prev_visits
                    moves += 2 * extra - 1
                    prev_visits = extra - 1
                else:
                    if i != n - 1:
                        moves += 1
                    prev_visits = 0

                if moves > m:
                    return False

            return moves <= m

        lo, hi = 0, min(points) * m
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        total = n + m - 1
        pat = [ord(ch) - ord('a') for ch in str2]

        fixed = [-1] * total
        for i, flag in enumerate(str1):
            if flag == 'T':
                for j, ch in enumerate(pat):
                    pos = i + j
                    if fixed[pos] != -1 and fixed[pos] != ch:
                        return ""
                    fixed[pos] = ch

        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and pat[i] != pat[j]:
                j = pi[j - 1]
            if pat[i] == pat[j]:
                j += 1
            pi[i] = j

        go = [[0] * 26 for _ in range(m)]
        for state in range(m):
            for c in range(26):
                if state > 0 and c != pat[state]:
                    go[state][c] = go[pi[state - 1]][c]
                else:
                    go[state][c] = state + 1 if c == pat[state] else state

        fallback = pi[-1]
        alphabet = tuple(range(26))

        dp = [None] * (total + 1)
        dp[total] = bytearray([1]) * m

        for pos in range(total - 1, -1, -1):
            next_ok = dp[pos + 1]
            cur = bytearray(m)
            start = pos - m + 1
            forbid_match = start >= 0 and str1[start] == 'F'
            forced = fixed[pos]

            if forced != -1:
                for state in range(m):
                    raw = go[state][forced]
                    if raw == m:
                        if not forbid_match and next_ok[fallback]:
                            cur[state] = 1
                    elif next_ok[raw]:
                        cur[state] = 1
            else:
                for state in range(m):
                    row = go[state]
                    for c in alphabet:
                        raw = row[c]
                        if raw == m:
                            if forbid_match:
                                continue
                            nxt = fallback
                        else:
                            nxt = raw

                        if next_ok[nxt]:
                            cur[state] = 1
                            break

            dp[pos] = cur

        if not dp[0][0]:
            return ""

        ans = []
        state = 0

        for pos in range(total):
            start = pos - m + 1
            forbid_match = start >= 0 and str1[start] == 'F'
            forced = fixed[pos]
            choices = (forced,) if forced != -1 else alphabet

            for c in choices:
                raw = go[state][c]
                if raw == m:
                    if forbid_match:
                        continue
                    nxt = fallback
                else:
                    nxt = raw

                if dp[pos + 1][nxt]:
                    ans.append(chr(c + ord('a')))
                    state = nxt
                    break

        return ''.join(ans)

from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        perimeter = 4 * side

        def boundary_pos(x: int, y: int) -> int:
            if y == 0:
                return x
            if x == side:
                return side + y
            if y == side:
                return 3 * side - x
            return 4 * side - y

        pos = sorted(boundary_pos(x, y) for x, y in points)
        n = len(pos)
        extended = pos + [p + perimeter for p in pos]
        m = 2 * n

        def can(dist: int) -> bool:
            nxt = [m] * m
            j = 0

            for i in range(m):
                if j <= i:
                    j = i + 1
                while j < m and extended[j] - extended[i] < dist:
                    j += 1
                nxt[i] = j

            for start in range(n):
                cur = start
                limit = start + n

                for _ in range(k - 1):
                    cur = nxt[cur]
                    if cur >= limit:
                        break

                if cur < limit and extended[cur] - extended[start] <= perimeter - dist:
                    return True

            return False

        lo, hi = 0, side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        CAP = 10**15 + 1

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(CAP, fact[i - 1] * i)

        def count_completions(odd_left: int, even_left: int, prev_parity: int) -> int:
            m = odd_left + even_left
            if m == 0:
                return 1

            next_parity = 1 - prev_parity
            if next_parity == 1:  # odd
                odd_slots = (m + 1) // 2
                even_slots = m // 2
            else:
                even_slots = (m + 1) // 2
                odd_slots = m // 2

            if odd_left != odd_slots or even_left != even_slots:
                return 0

            return min(CAP, fact[odd_left] * fact[even_left])

        unused = list(range(1, n + 1))
        odd_left = (n + 1) // 2
        even_left = n // 2
        ans = []
        prev_parity = -1

        for _ in range(n):
            chosen = None

            for x in unused:
                parity = x % 2
                if prev_parity != -1 and parity == prev_parity:
                    continue

                no = odd_left - (1 if parity == 1 else 0)
                ne = even_left - (1 if parity == 0 else 0)
                ways = count_completions(no, ne, parity)

                if k > ways:
                    k -= ways
                else:
                    chosen = x
                    break

            if chosen is None:
                return []

            ans.append(chosen)
            unused.remove(chosen)

            if chosen % 2:
                odd_left -= 1
                prev_parity = 1
            else:
                even_left -= 1
                prev_parity = 0

        return ans

from typing import List
from collections import defaultdict

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]

        for idx, (a, b) in enumerate(conflictingPairs):
            x, y = (a, b) if a < b else (b, a)
            by_right[y].append((x, idx))

        count_by_x = defaultdict(int)
        only_id_by_x = {}
        gains = [0] * len(conflictingPairs)

        max1 = 0
        max2 = 0
        total = 0

        for r in range(1, n + 1):
            for x, idx in by_right[r]:
                count_by_x[x] += 1
                only_id_by_x[x] = idx

                if x > max1:
                    max2 = max1
                    max1 = x
                elif x != max1 and x > max2:
                    max2 = x

            total += r - max1

            if max1 and count_by_x[max1] == 1:
                gains[only_id_by_x[max1]] += max1 - max2

        return total + (max(gains) if gains else 0)

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_up_to(n: int) -> int:
            if n <= 0:
                return 0

            digits = list(map(int, str(n)))
            max_sum = 9 * len(digits)
            total = 0

            for target_sum in range(1, max_sum + 1):
                memo = {}

                def dfs(pos: int, tight: bool, started: bool, digit_sum: int, prod_mod: int) -> int:
                    if digit_sum > target_sum:
                        return 0
                    if pos == len(digits):
                        return int(started and digit_sum == target_sum and prod_mod == 0)

                    key = (pos, tight, started, digit_sum, prod_mod)
                    if key in memo:
                        return memo[key]

                    limit = digits[pos] if tight else 9
                    ans = 0

                    for d in range(limit + 1):
                        ntight = tight and d == limit

                        if not started and d == 0:
                            ans += dfs(pos + 1, ntight, False, 0, 1 % target_sum)
                        else:
                            new_sum = digit_sum + d
                            if new_sum <= target_sum:
                                new_prod = (prod_mod * d) % target_sum if started else d % target_sum
                                ans += dfs(pos + 1, ntight, True, new_sum, new_prod)

                    memo[key] = ans
                    return ans

                total += dfs(0, True, False, 0, 1 % target_sum)

            return total

        return count_up_to(r) - count_up_to(l - 1)

import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M, A, B = data[:4]
    intervals = []
    idx = 4
    for _ in range(M):
        L, R = data[idx], data[idx + 1]
        intervals.append((L, R))
        idx += 2

    limit = (1 << B) - 1
    mask = 1  # after processing square 1, only square 1 is reachable

    if A == B:
        def apply_good(state, length):
            if state == 0 or length == 0:
                return state
            r = length % B
            if r == 0:
                return state
            return ((state << r) | (state >> (B - r))) & limit
    else:
        jump_mask = limit ^ ((1 << (A - 1)) - 1)
        SATURATION_STEPS = 1000

        def apply_good(state, length):
            if state == 0 or length == 0:
                return state
            if length > SATURATION_STEPS:
                return limit

            for _ in range(length):
                new_bit = 1 if (state & jump_mask) else 0
                state = ((state << 1) & limit) | new_bit
            return state

    def apply_bad(state, length):
        if state == 0:
            return 0
        if length >= B:
            return 0
        return (state << length) & limit

    current = 1

    for L, R in intervals:
        mask = apply_good(mask, L - current - 1)
        mask = apply_bad(mask, R - L + 1)
        current = R

        if mask == 0:
            print("No")
            return

    mask = apply_good(mask, N - current)
    print("Yes" if (mask & 1) else "No")


