import sys
import numpy as np

def main():
    N, P = map(int, sys.stdin.readline().split())
    half = N // 2
    max_edges = N * (N - 1) // 2
    PMAX = max_edges + 1

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % P
    invfact = [1] * (N + 1)
    invfact[N] = pow(fact[N], P - 2, P)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % P

    comb = [[1]]
    for i in range(1, PMAX):
        row = [1] * (i + 1)
        prev = comb[-1]
        for j in range(1, i):
            row[j] = (prev[j - 1] + prev[j]) % P
        comb.append(row)

    # In q = 1 + x basis:
    # within new layer of size b: q^(b(b-1)/2)
    # edges from previous layer size a to new layer of size b: (q^a - 1)^b
    transitions = {}
    for a in range(1, half + 1):
        for b in range(1, half + 1):
            base = b * (b - 1) // 2
            inv = invfact[b]
            terms = []
            for j in range(b + 1):
                c = comb[b][j] * inv % P
                if (b - j) & 1:
                    c = (-c) % P
                if c:
                    terms.append((base + a * j, c))
            transitions[(a, b)] = terms

    init = np.zeros(1, dtype=np.int64)
    init[0] = 1
    current = {(1, 0, 1): init}
    next_parity = 1
    final_q = np.zeros(PMAX, dtype=np.int64)

    while current:
        nxt = {}
        for (e, o, p), poly in current.items():
            if e == half and o == half:
                L = len(poly)
                final_q[:L] = (final_q[:L] + poly) % P
                continue
            remaining = half - o if next_parity else half - e
            if remaining <= 0:
                continue
            for b in range(1, remaining + 1):
                ne = e + (b if next_parity == 0 else 0)
                no = o + (b if next_parity == 1 else 0)
                key = (ne, no, b)
                max_shift = b * (b - 1) // 2 + p * b
                need = min(PMAX, len(poly) + max_shift)
                if key in nxt:
                    res = nxt[key]
                    if len(res) < need:
                        new_res = np.zeros(need, dtype=np.int64)
                        new_res[:len(res)] = res
                        res = new_res
                        nxt[key] = res
                else:
                    res = np.zeros(need, dtype=np.int64)
                    nxt[key] = res
                for shift, coef in transitions[(p, b)]:
                    limit = min(len(poly), PMAX - shift)
                    if limit > 0:
                        res[shift:shift + limit] = (res[shift:shift + limit] + poly[:limit] * coef) % P
        current = nxt
        next_parity ^= 1

    ans = np.zeros(PMAX, dtype=np.int64)
    label_factor = fact[N - 1]
    final_q_lf = final_q * label_factor % P
    for deg in range(PMAX):
        c = int(final_q_lf[deg])
        if c:
            row = np.array(comb[deg], dtype=np.int64)
            ans[:deg + 1] = (ans[:deg + 1] + c * row) % P

    print(" ".join(str(int(x)) for x in ans[N - 1:]))

if __name__ == "__main__":
    main()

import sys
from bisect import bisect_left

def main():
    input = sys.stdin.readline
    N, X = map(int, input().split())

    foods = [[] for _ in range(3)]
    for _ in range(N):
        v, a, c = map(int, input().split())
        foods[v - 1].append((a, c))

    dps = []
    for group in foods:
        dp = [0] * (X + 1)
        for a, c in group:
            for cal in range(X, c - 1, -1):
                nv = dp[cal - c] + a
                if nv > dp[cal]:
                    dp[cal] = nv

        for cal in range(1, X + 1):
            if dp[cal - 1] > dp[cal]:
                dp[cal] = dp[cal - 1]
        dps.append(dp)

    def feasible(target):
        total_cal = 0
        for dp in dps:
            idx = bisect_left(dp, target)
            if idx > X:
                return False
            total_cal += idx
            if total_cal > X:
                return False
        return True

    low, high = 0, min(dp[X] for dp in dps) + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(low)

if __name__ == "__main__":
    main()

import sys
from collections import defaultdict

MOD = 998244353

def main():
    data = sys.stdin.read().split()
    N = int(data[0])
    M = int(data[1])
    S = data[2]

    max_state = 1 << N

    lcs_row = []
    for mask in range(max_state):
        row = [0] * (N + 1)
        for j in range(1, N + 1):
            row[j] = row[j - 1] + ((mask >> (j - 1)) & 1)
        lcs_row.append(row)

    transitions = []
    for mask in range(max_state):
        old = lcs_row[mask]
        cnt = defaultdict(int)

        for x in range(26):
            c = chr(ord('a') + x)
            new = [0] * (N + 1)

            for j in range(1, N + 1):
                if S[j - 1] == c:
                    new[j] = old[j - 1] + 1
                else:
                    new[j] = max(old[j], new[j - 1])

            nxt = 0
            for j in range(1, N + 1):
                if new[j] - new[j - 1]:
                    nxt |= 1 << (j - 1)

            cnt[nxt] += 1

        transitions.append(list(cnt.items()))

    dp = [0] * max_state
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * max_state
        for mask in range(max_state):
            val = dp[mask]
            if val == 0:
                continue
            for nxt, ways in transitions[mask]:
                ndp[nxt] = (ndp[nxt] + val * ways) % MOD
        dp = ndp

    ans = [0] * (N + 1)
    for mask in range(max_state):
        k = bin(mask).count("1")
        ans[k] = (ans[k] + dp[mask]) % MOD

    print(*ans)

if __name__ == "__main__":
    main()

import sys
from collections import deque

def main():
    data = sys.stdin.buffer.read().split()
    N = int(data[0])
    C = [data[1 + i].decode() for i in range(N)]

    in_by_char = [[[] for _ in range(N)] for _ in range(26)]
    out_by_char = [[[] for _ in range(N)] for _ in range(26)]

    dist = [[-1] * N for _ in range(N)]
    q = deque()
    remaining = N * N

    for i in range(N):
        dist[i][i] = 0
        q.append((i, i))
        remaining -= 1

    for i in range(N):
        row_c = C[i]
        for j in range(N):
            ch = row_c[j]
            if ch != '-':
                k = ord(ch) - 97
                out_by_char[k][i].append(j)
                in_by_char[k][j].append(i)
                if dist[i][j] == -1:
                    dist[i][j] = 1
                    q.append((i, j))
                    remaining -= 1

    while q and remaining > 0:
        u, v = q.popleft()
        nd = dist[u][v] + 2
        in_u = [in_by_char[k][u] for k in range(26)]
        out_v = [out_by_char[k][v] for k in range(26)]
        done = False
        for k in range(26):
            lefts = in_u[k]
            if not lefts:
                continue
            rights = out_v[k]
            if not rights:
                continue
            for x in lefts:
                row = dist[x]
                for y in rights:
                    if row[y] == -1:
                        row[y] = nd
                        q.append((x, y))
                        remaining -= 1
                if remaining == 0:
                    done = True
                    break
            if done:
                break
        if done:
            break

    out_lines = []
    for row in dist:
        out_lines.append(' '.join(map(str, row)))
    sys.stdout.write('\n'.join(out_lines) + '\n')

if __name__ == "__main__":
    main()

import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    deg = [0] * n
    edges = []

    for i in range(1, len(data), 2):
        u = data[i] - 1
        v = data[i + 1] - 1
        edges.append((u, v))
        deg[u] += 1
        deg[v] += 1

    eligible = [d >= 4 for d in deg]
    if not any(eligible):
        print(-1)
        return

    adj = [[] for _ in range(n)]
    for u, v in edges:
        if eligible[u] and eligible[v]:
            adj[u].append(v)
            adj[v].append(u)

    parent = [-2] * n
    down = [0] * n
    up = [0] * n
    best = 0

    for start in range(n):
        if not eligible[start] or parent[start] != -2:
            continue

        parent[start] = -1
        order = [start]
        stack = [start]

        while stack:
            v = stack.pop()
            for to in adj[v]:
                if to == parent[v] or parent[to] != -2:
                    continue
                parent[to] = v
                stack.append(to)
                order.append(to)

        for v in reversed(order):
            vals = [down[to] for to in adj[v] if parent[to] == v]
            vals.sort(reverse=True)
            down[v] = 1 + sum(vals[:3])

        up[start] = 0

        for v in order:
            incoming = []

            if parent[v] != -1:
                incoming.append((up[v], parent[v]))

            for to in adj[v]:
                if parent[to] == v:
                    incoming.append((down[to], to))

            incoming.sort(reverse=True)
            best = max(best, 1 + sum(value for value, _ in incoming[:4]))

            top4 = incoming[:4]
            for to in adj[v]:
                if parent[to] != v:
                    continue

                total = 0
                used = 0
                for value, node in top4:
                    if node == to:
                        continue
                    total += value
                    used += 1
                    if used == 3:
                        break

                up[to] = 1 + total

    print(3 * best + 2)

