    main()

import sys

class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, x):
        while i <= self.n:
            self.bit[i] += x
            i += i & -i

    def sum(self, i):
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s

def main():
    data = sys.stdin.buffer.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    M = int(data[idx]); idx += 1
    A = [int(data[idx + i]) for i in range(N)]

    fw = Fenwick(M)
    inv = 0
    positions = [[] for _ in range(M)]

    for i, a in enumerate(A):
        inv += i - fw.sum(a + 1)
        fw.add(a + 1, 1)
        positions[a].append(i)

    delta = [0] * M
    for x in range(M):
        c = len(positions[x])
        if c:
            delta[x] = 2 * sum(positions[x]) - c * (N - 1)
        else:
            delta[x] = 0

    ans = inv
    out = []
    for k in range(M):
        out.append(str(ans))
        if k + 1 < M:
            wrap_value = M - 1 - k
            ans += delta[wrap_value]

    sys.stdout.write("\n".join(out) + "\n")

