import sys

def main():
    input = sys.stdin.buffer.readline
    N, K = map(int, input().split())
    V = N * K

    adj = [[] for _ in range(V)]
    for _ in range(V - 1):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        adj[u].append(v)
        adj[v].append(u)

    if K == 1:
        print("Yes")
        return

    parent = [-2] * V
    parent[0] = -1
    order = [0]

    for x in order:
        for y in adj[x]:
            if y != parent[x]:
                parent[y] = x
                order.append(y)

    rem = [0] * V
    ok = True

    for x in reversed(order):
        chains = []
        for y in adj[x]:
            if parent[y] == x and rem[y] > 0:
                chains.append(rem[y])
                if len(chains) > 2:
                    ok = False
                    break

        if not ok:
            break

        if len(chains) == 0:
            rem[x] = 1
        elif len(chains) == 1:
            length = chains[0] + 1
            if length == K:
                rem[x] = 0
            elif length < K:
                rem[x] = length
            else:
                ok = False
                break
        else:
            if chains[0] + chains[1] + 1 == K:
                rem[x] = 0
            else:
                ok = False
                break

    print("Yes" if ok and rem[0] == 0 else "No")

