    main()

import sys
sys.setrecursionlimit(1 << 25)

INF_NEG = -10**18

class SegTree:
    def __init__(self, arr):
        self.n = 1
        while self.n < len(arr):
            self.n *= 2
        self.maxv = [INF_NEG] * (2 * self.n)
        self.lazy = [0] * (2 * self.n)
        for i, v in enumerate(arr):
            self.maxv[self.n + i] = v
        for i in range(self.n - 1, 0, -1):
            self.maxv[i] = max(self.maxv[2 * i], self.maxv[2 * i + 1])

    def _push(self, node):
        z = self.lazy[node]
        if z:
            l, r = 2 * node, 2 * node + 1
            self.maxv[l] += z
            self.lazy[l] += z
            self.maxv[r] += z
            self.lazy[r] += z
            self.lazy[node] = 0

    def range_add(self, left, right, value, node=1, nl=0, nr=None):
        if nr is None:
            nr = self.n
        if right <= nl or nr <= left:
            return
        if left <= nl and nr <= right:
            self.maxv[node] += value
            self.lazy[node] += value
            return
        self._push(node)
        mid = (nl + nr) // 2
        self.range_add(left, right, value, 2 * node, nl, mid)
        self.range_add(left, right, value, 2 * node + 1, mid, nr)
        self.maxv[node] = max(self.maxv[2 * node], self.maxv[2 * node + 1])

    def range_max(self, left, right, node=1, nl=0, nr=None):
        if nr is None:
            nr = self.n
        if right <= nl or nr <= left:
            return INF_NEG
        if left <= nl and nr <= right:
            return self.maxv[node]
        self._push(node)
        mid = (nl + nr) // 2
        return max(
            self.range_max(left, right, 2 * node, nl, mid),
            self.range_max(left, right, 2 * node + 1, mid, nr),
        )

def main():
    data = sys.stdin.buffer.read().split()
    N = int(data[0])
    A = [0] + [int(x) for x in data[1:N+1]]

    pref = [0] * (N + 1)
    seen = [False] * (N + 2)
    count = 0
    for i in range(1, N + 1):
        if not seen[A[i]]:
            seen[A[i]] = True
            count += 1
        pref[i] = count

    suf = [0] * (N + 2)
    seen = [False] * (N + 2)
    count = 0
    for i in range(N, 0, -1):
        if not seen[A[i]]:
            seen[A[i]] = True
            count += 1
        suf[i] = count

    base = [INF_NEG] * (N + 1)
    for l in range(2, N + 1):
        base[l] = pref[l - 1]

    seg = SegTree(base)
    last = [0] * (N + 2)
    ans = 0

    for r in range(1, N):
        prev = last[A[r]]
        seg.range_add(prev + 1, r + 1, 1)
        last[A[r]] = r

        if r >= 2:
            cand = seg.range_max(2, r + 1) + suf[r + 1]
            if cand > ans:
                ans = cand

    print(ans)

if __name__ == "__main__":
    main()

import sys
from collections import deque

class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        fwd = [to, cap, None]
        rev = [fr, 0, fwd]
        fwd[2] = rev
        self.g[fr].append(fwd)
        self.g[to].append(rev)

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        q = deque([s])
        while q:
            v = q.popleft()
            for e in self.g[v]:
                if e[1] > 0 and self.level[e[0]] < 0:
                    self.level[e[0]] = self.level[v] + 1
                    q.append(e[0])
        return self.level[t] >= 0

    def dfs(self, s, t):
        # iterative DFS sending one unit-augmenting path? Use recursive with increased limit.
        INF = 10**18
        it = self.it
        level = self.level
        stack = [(s, INF, iter(range(len(self.g[s]))))]
        # Use recursive helper
        def _dfs(v, f):
            if v == t:
                return f
            while it[v] < len(self.g[v]):
                e = self.g[v][it[v]]
                if e[1] > 0 and level[v] + 1 == level[e[0]]:
                    ret = _dfs(e[0], min(f, e[1]))
                    if ret:
                        e[1] -= ret
                        e[2][1] += ret
                        return ret
                it[v] += 1
            return 0
        return _dfs(s, INF)

    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            self.it = [0] * self.n
            while True:
                pushed = self.dfs(s, t)
                if not pushed:
                    break
                flow += pushed
        return flow


def feasible(n, edges, k, d):
    if d == 0:
        return True

    total_vars = n * d
    src = total_vars
    sink = total_vars + 1
    dinic = Dinic(total_vars + 2)
    INF = 10**9

    def node(v, i):
        return v * d + (i - 1)

    s_vertex = 0
    t_vertex = n - 1

    for i in range(1, d + 1):
        dinic.add_edge(src, node(s_vertex, i), INF)
        dinic.add_edge(node(t_vertex, i), sink, INF)

    for v in range(n):
        for i in range(1, d):
            dinic.add_edge(node(v, i), node(v, i + 1), INF)

    for u, v in edges:
        for i in range(1, d + 1):
            dinic.add_edge(node(u, i), node(v, i), 1)
        for i in range(1, d):
            dinic.add_edge(node(u, i), node(v, i + 1), INF)

    return dinic.max_flow(src, sink) <= k


def main():
    sys.setrecursionlimit(100000)
    data = sys.stdin.read().split()
    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1
    k = int(data[idx]); idx += 1
    edges = []
    for _ in range(m):
        u = int(data[idx]) - 1; idx += 1
        v = int(data[idx]) - 1; idx += 1
        edges.append((u, v))

    for d in range(min(k, n - 1), -1, -1):
        if feasible(n, edges, k, d):
            print(d)
            return


