def main():
    data = sys.stdin.buffer.read().split()
    Q = int(data[0])
    queries = [int(x) for x in data[1:1+Q]]

    roots = [isqrt(a) for a in queries]
    max_root = max(roots) if roots else 0
    if max_root < 6:
        max_root = 6

    omega = bytearray(max_root + 1)
    for p in range(2, max_root + 1):
        if omega[p] == 0:
            for x in range(p, max_root + 1, p):
                omega[x] += 1

    best = [0] * (max_root + 1)
    cur = 0
    for i in range(max_root + 1):
        if omega[i] == 2:
            cur = i
        best[i] = cur

    out = []
    for r in roots:
        m = best[r]
        out.append(str(m * m))

    sys.stdout.write("\n".join(out))

