import sys
import numpy as np

def mat_mul(A, B, mod):
    n = A.shape[0]
    block = max(1, ((1 << 63) - 1) // (mod * mod))
    if n <= block:
        return (A @ B) % mod
    res = np.zeros((n, n), dtype=np.int64)
    for s in range(0, n, block):
        e = min(s + block, n)
        res = (res + A[:, s:e] @ B[s:e, :]) % mod
    return res

def mat_pow(A, exp, mod):
    n = A.shape[0]
    res = np.eye(n, dtype=np.int64)
    base = A.copy()
    while exp:
        if exp & 1:
            res = mat_mul(res, base, mod)
        exp >>= 1
        if exp:
            base = mat_mul(base, base, mod)
    return res

def main():
    data = sys.stdin.buffer.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    p = int(data[idx]); idx += 1
    A = []
    for i in range(N):
        row = [int(data[idx + j]) for j in range(N)]
        A.append(row)
        idx += N

    if p == 2:
        val = N % 2
        line = ' '.join([str(val)] * N)
        sys.stdout.write('\n'.join([line] * N) + '\n')
        return

    K = 0
    C = np.zeros((N, N), dtype=np.int64)
    for i in range(N):
        for j in range(N):
            if A[i][j] == 0:
                K += 1
            else:
                C[i][j] = A[i][j] % p

    ans = mat_pow(C, p, p)

    extra = np.zeros((N, N), dtype=np.int64)
    for u in range(N):
        if A[u][u] == 0:
            extra[:, u] = (extra[:, u] + C[:, u]) % p
            extra[u, :] = (extra[u, :] + C[u, :]) % p

    if p == 3:
        for u in range(N):
            for v in range(N):
                if u != v and A[u][v] == 0:
                    extra[u][v] = (extra[u][v] + C[v][u]) % p

    sign = 1 if K % 2 == 0 else p - 1
    result = ((ans + extra) % p) * sign % p

    out_lines = []
    for i in range(N):
        out_lines.append(' '.join(str(int(x)) for x in result[i]))
    sys.stdout.write('\n'.join(out_lines) + '\n')

if __name__ == "__main__":
    main()

import sys

def build_primes(limit: int):
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(limit ** 0.5) + 1):
        if is_prime[i]:
            step = i
            start = i * i
            is_prime[start:limit + 1:step] = [False] * (((limit - start) // step) + 1)
    return [i for i in range(2, limit + 1) if is_prime[i]]

PRIMES = build_primes(31623)

def factorize(n: int):
    res = []
    x = n
    for p in PRIMES:
        if p * p > x:
            break
        if x % p == 0:
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            res.append((p, e))
    if x > 1:
        res.append((x, 1))
    return res

def crt_pair(components):
    x = 0
    mod = 1
    for m, a in components:
        t = ((a - x) % m) * pow(mod % m, -1, m) % m
        x += mod * t
        mod *= m
        x %= mod
    return x, mod

def solve_one(n: int):
    if n == 1:
        return 1, 1

    components = []
    for p, e in factorize(n):
        if p == 2:
            if e == 1:
                components.append((4, 3))
            else:
                components.append((1 << (e + 2), 5))
        else:
            components.append((p ** (e + 1), p + 1))

    a, m = crt_pair(components)
    return a, m

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    t = data[0]
    out = []
    for i in range(1, t + 1):
        a, m = solve_one(data[i])
        out.append(f"{a} {m}")
    sys.stdout.write("\n".join(out) + "\n")

if __name__ == "__main__":
    main()

