import sys

MOD = 998244353
MAX_A = 1000


def build_spf(limit):
    spf = list(range(limit + 1))
    for i in range(2, limit + 1):
        if spf[i] == i:
            for j in range(i * i, limit + 1, i):
                if spf[j] == j:
                    spf[j] = i
    return spf


def factorize(x, spf):
    res = {}
    while x > 1:
        p = spf[x]
        cnt = 0
        while x % p == 0:
            x //= p
            cnt += 1
        res[p] = cnt
    return res


def main():
    data = sys.stdin.read().split()
    N = int(data[0])
    A = list(map(int, data[1:N]))

    spf = build_spf(MAX_A)
    factors = []
    primes = set()

    for x in A:
        f = factorize(x, spf)
        factors.append(f)
        primes.update(f.keys())

    ans = 1

    for p in primes:
        exps = [f.get(p, 0) for f in factors]
        total = sum(exps)
        max_e = max(exps)

        limit = max(total, N * max_e)
        pw = [1] * (limit + 1)
        for i in range(1, limit + 1):
            pw[i] = pw[i - 1] * p % MOD

        dp = [0] * (total + 1)
        dp[0] = 1
        active = 0

        for idx, e in enumerate(exps, start=1):
            ndp = [0] * (total + 1)

            if e == 0:
                for h in range(active + 1):
                    if dp[h]:
                        ndp[h] = dp[h] * pw[h] % MOD
            else:
                for h in range(active + 1):
                    val = dp[h]
                    if not val:
                        continue

                    up = h + e
                    ndp[up] = (ndp[up] + val * pw[up]) % MOD

                    down = h - e
                    if down >= 0:
                        ndp[down] = (ndp[down] + val * pw[down]) % MOD
                    else:
                        shift = -down
                        ndp[0] = (ndp[0] + val * pw[idx * shift]) % MOD

                active += e

            dp = ndp

        ans = ans * (sum(dp) % MOD) % MOD

    print(ans)


if __name__ == "__main__":
    main()

import sys

MOD = 998244353

def main():
    W, H, L, R, D, U = map(int, sys.stdin.readline().split())

    max_n = W + H + 4
    fact = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * (max_n + 1)
    invfact[max_n] = pow(fact[max_n], MOD - 2, MOD)
    for i in range(max_n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    def comb(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * invfact[k] % MOD * invfact[n - k] % MOD

    def pref(x, y):
        if x < 0 or y < 0:
            return 0
        return (comb(x + y + 2, x + 1) - 1) % MOD

    def suf(x, y):
        return pref(W - x, H - y)

    def total_full(a, b):
        if a < 0 or b < 0:
            return 0
        return (comb(a + b + 4, a + 2) - a - b - 4 - (a + 1) * (b + 1)) % MOD

    full = total_full(W, H)

    a1, a2 = W - R, W - L
    b1, b2 = H - U, H - D
    invalid = (
        total_full(a2, b2)
        - total_full(a1 - 1, b2)
        - total_full(a2, b1 - 1)
        + total_full(a1 - 1, b1 - 1)
    ) % MOD

    if D > 0:
        extra = 0
        for x in range(L, R + 1):
            extra = (extra + pref(x, D - 1) * suf(x, D)) % MOD
        invalid = (invalid + extra) % MOD

    if L > 0:
        extra = 0
        for y in range(D, U + 1):
            extra = (extra + pref(L - 1, y) * suf(L, y)) % MOD
        invalid = (invalid + extra) % MOD

    print((full - invalid) % MOD)

if __name__ == "__main__":
    main()

import sys

def main():
    MOD = 998244353
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    s = data[1]  # bytes
    ONE = 0x31  # ord('1')

    # States: 0:(0,0,0) 1:(0,0,1) 2:(0,1,0) 3:(0,1,1) 4:(0,1,2)
    # representing partition of (first_vertex, prev_vertex, hub)
    states_idx = {(0,0,0):0, (0,0,1):1, (0,1,0):2, (0,1,1):3, (0,1,2):4}
    dp = [0, 0, 0, 0, 0]

    sp0_opts = (0, 1) if s[0] == ONE else (0,)
    sp1_opts = (0, 1) if s[1] == ONE else (0,)

    for sp0 in sp0_opts:
        for rim in (0, 1):
            for sp1 in sp1_opts:
                comp = [0, 1, 2]  # v0, v1, hub
                ok = True
                if sp0:
                    if comp[0] == comp[2]:
                        ok = False
                    else:
                        a_, b_ = comp[0], comp[2]
                        for j in range(3):
                            if comp[j] == b_:
                                comp[j] = a_
                if ok and rim:
                    if comp[0] == comp[1]:
                        ok = False
                    else:
                        a_, b_ = comp[0], comp[1]
                        for j in range(3):
                            if comp[j] == b_:
                                comp[j] = a_
                if ok and sp1:
                    if comp[1] == comp[2]:
                        ok = False
                    else:
                        a_, b_ = comp[1], comp[2]
                        for j in range(3):
                            if comp[j] == b_:
                                comp[j] = a_
                if ok:
                    mp = {}
                    nxt = 0
                    cs = []
                    for x in comp:
                        if x not in mp:
                            mp[x] = nxt
                            nxt += 1
                        cs.append(mp[x])
                    dp[states_idx[tuple(cs)]] += 1

    a, b, c, d, e = dp

    # Main loop with inlined transitions
    for i in range(2, n):
        if s[i] == ONE:
            na = (3*a + b + 2*c) % MOD
            nc = (a + 2*c) % MOD
            nd = (b + 2*d + 2*e) % MOD
            ne = (b + d + 2*e) % MOD
            a = na
            c = nc
            d = nd
            e = ne
            # b unchanged
        else:
            nc = (a + 2*c) % MOD
            ne = (b + d + 2*e) % MOD
            c = nc
            e = ne
            # a, b, d unchanged

    # Close cycle with edge {N-1, 0}:
    # - exclude: contributes sum(dp)
    # - include: only valid when first and prev are in different components
    #   (states 2, 3, 4 where state[0] != state[1])
    ans = (a + b + 2*c + 2*d + 2*e) % MOD
    print(ans)

main()

import sys

ZERO = ord('0')
ONE = ord('1')


def possible(a_ones, n, b, x, last_b_one):
    m = n + 2 * x
    cnt = len(a_ones)
    trailing_b_zeros = n - 1 - last_b_one
    last_a_one = a_ones[-1] + x

    p = 0
    idx = 0
    made_one = False
    i = 0

    while i <= last_b_one:
        if b[i] == ZERO:
            j = i
            while j <= last_b_one and b[j] == ZERO:
                j += 1
            need = j - i

            while True:
                if p + need > m:
                    return False
                while idx < cnt and a_ones[idx] + x < p:
                    idx += 1
                if idx == cnt or a_ones[idx] + x >= p + need:
                    break

                # Extend the most recent '1' block by two characters.
                if not made_one:
                    return False
                p += 2
                if p > m:
                    return False

            p += need
            i = j
        else:
            if i == last_b_one:
                if last_a_one < p:
                    return False

                if trailing_b_zeros == 0:
                    return (m - p) % 2 == 1

                min_len = last_a_one - p + 1
                if min_len % 2 == 0:
                    min_len += 1
                return min_len <= m - p - trailing_b_zeros

            while idx < cnt and a_ones[idx] + x < p:
                idx += 1
            if idx == cnt:
                return False

            q = a_ones[idx] + x
            length = q - p + 1
            if length % 2 == 0:
                length += 1
            p += length
            if p > m:
                return False

            made_one = True
            i += 1

    return False


def solve():
    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    pos = 1
    ans = []

    for _ in range(t):
        n = int(data[pos])
        a = data[pos + 1]
        b = data[pos + 2]
        pos += 3

        a_ones = [i for i, ch in enumerate(a) if ch == ONE]
        first_a = a_ones[0]
        last_a = a_ones[-1]

        first_b = b.find(b'1')
        last_b = b.rfind(b'1')

        lower = max(
            0,
            first_b - first_a,
            (n - 1 - last_b) - (n - 1 - last_a),
        )

        if possible(a_ones, n, b, lower, last_b):
            ans.append(str(lower))
        elif possible(a_ones, n, b, lower + 1, last_b):
            ans.append(str(lower + 1))
        else:
            ans.append("-1")

    print("\n".join(ans))


if __name__ == "__main__":
    solve()

import sys

class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, v):
        while i <= self.n:
            self.bit[i] += v
            i += i & -i

    def sum(self, i):
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s

def main():
    data = sys.stdin.buffer.read().split()
    N = int(data[0])
    P = list(map(int, data[1:1 + N]))

    fw = Fenwick(N)
    ans = 0

    for t, x in enumerate(P, start=1):
        less = fw.sum(x - 1)
        ans += (t - 1) * t // 2 - less * (less + 1) // 2
        fw.add(x, 1)

    sys.stdout.write(str(ans) + "\n")

if __name__ == "__main__":
    main()

