import sys

def build(R, B):
    if R % 2 == 1:
        return None
    if R == 0 and B % 2 == 1:
        return None

    ans = []
    r = c = 0
    start = (0, 0)

    def add(piece, dr, dc):
        nonlocal r, c
        ans.append((piece, r, c))
        r += dr
        c += dc

    if R == 0:
        if B == 2:
            add('B', 1, 1)
            add('B', -1, -1)
        else:
            w = B // 2 - 1
            for _ in range(w):
                add('B', 1, 1)
            add('B', 1, -1)
            for _ in range(w):
                add('B', -1, -1)
            add('B', -1, 1)

    elif B % 2 == 0:
        h = (R - 2) // 2
        b = B // 2

        add('R', 1, 0)
        for _ in range(h):
            add('R', 0, 1)
        for _ in range(b):
            add('B', 1, 1)
        add('R', -1, 0)
        for _ in range(b):
            add('B', -1, -1)
        for _ in range(h):
            add('R', 0, -1)

    else:
        h_top = (R - 2) // 2
        h_bottom = R // 2
        b = (B - 1) // 2

        add('R', 1, 0)
        for _ in range(h_top):
            add('R', 0, 1)
        for _ in range(b):
            add('B', 1, 1)
        add('B', -1, 1)
        for _ in range(b):
            add('B', -1, -1)
        for _ in range(h_bottom):
            add('R', 0, -1)

    if (r, c) != start:
        return None

    min_r = min(x for _, x, _ in ans)
    min_c = min(y for _, _, y in ans)
    off_r = 1 - min_r
    off_c = 1 - min_c

    return [(p, x + off_r, y + off_c) for p, x, y in ans]


def main():
    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    idx = 1
    out = []

    for _ in range(t):
        R = int(data[idx]); B = int(data[idx + 1])
        idx += 2

        placement = build(R, B)
        if placement is None:
            out.append("No")
        else:
            out.append("Yes")
            for p, rr, cc in placement:
                out.append(f"{p} {rr} {cc}")

    sys.stdout.write("\n".join(out))


