from typing import List
from bisect import bisect_left

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        arr = [(l, r, w, i) for i, (l, r, w) in enumerate(intervals)]
        arr.sort(key=lambda x: x[1])
        n = len(arr)
        ends = [r for _, r, _, _ in arr]

        def better(a, b):
            if a[0] != b[0]:
                return a if a[0] > b[0] else b
            return a if a[1] <= b[1] else b

        dp = [[(0, ()) for _ in range(5)] for _ in range(n + 1)]

        for i in range(1, n + 1):
            l, r, w, idx = arr[i - 1]
            prev = bisect_left(ends, l)

            for k in range(1, 5):
                skip = dp[i - 1][k]
                prev_weight, prev_indices = dp[prev][k - 1]
                take = (prev_weight + w, tuple(sorted(prev_indices + (idx,))))
                dp[i][k] = better(skip, take)

        return list(dp[n][4])

from typing import List

class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        n = len(nums)
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        best_len = 0
        best_nodes = 1
        last_seen = {}
        dist_at_depth = []

        stack = [(0, -1, 0, 0, 0, 0, None)]  # node, parent, depth, dist, left, state, previous depth

        while stack:
            u, parent, depth, dist, left, state, prev_depth = stack.pop()
            val = nums[u]

            if state == 0:
                if depth == len(dist_at_depth):
                    dist_at_depth.append(dist)
                else:
                    dist_at_depth[depth] = dist

                prev_depth = last_seen.get(val, -1)
                new_left = max(left, prev_depth + 1)

                cur_len = dist - dist_at_depth[new_left]
                cur_nodes = depth - new_left + 1

                if cur_len > best_len:
                    best_len = cur_len
                    best_nodes = cur_nodes
                elif cur_len == best_len:
                    best_nodes = min(best_nodes, cur_nodes)

                last_seen[val] = depth
                stack.append((u, parent, depth, dist, left, 1, prev_depth))

                for v, w in reversed(graph[u]):
                    if v != parent:
                        stack.append((v, u, depth + 1, dist + w, new_left, 0, None))
            else:
                if prev_depth == -1:
                    del last_seen[val]
                else:
                    last_seen[val] = prev_depth

        return [best_len, best_nodes]

from typing import List
from collections import defaultdict

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        NEG_INF = -10**30

        positions = defaultdict(list)
        for i, v in enumerate(nums):
            if v < 0:
                positions[v].append(i)

        size = 1
        while size < n:
            size <<= 1

        total = [0] * (2 * size)
        pref = [NEG_INF] * (2 * size)
        suff = [NEG_INF] * (2 * size)
        best = [NEG_INF] * (2 * size)

        def pull(i: int) -> None:
            left, right = i * 2, i * 2 + 1
            total[i] = total[left] + total[right]
            pref[i] = max(pref[left], total[left] + pref[right])
            suff[i] = max(suff[right], total[right] + suff[left])
            best[i] = max(best[left], best[right], suff[left] + pref[right])

        for i, v in enumerate(nums):
            p = size + i
            total[p] = pref[p] = suff[p] = best[p] = v

        for i in range(size - 1, 0, -1):
            pull(i)

        def update(idx: int, value: int, active: bool) -> None:
            p = size + idx
            if active:
                total[p] = pref[p] = suff[p] = best[p] = value
            else:
                total[p] = 0
                pref[p] = suff[p] = best[p] = NEG_INF

            p >>= 1
            while p:
                pull(p)
                p >>= 1

        ans = best[1]

        for x, inds in positions.items():
            if len(inds) == n:
                continue

            for i in inds:
                update(i, x, False)

            ans = max(ans, best[1])

            for i in inds:
                update(i, x, True)

        return ans

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        def kmp_occurrences(text: str, pat: str) -> list[int]:
            if not pat:
                return list(range(len(text) + 1))

            lps = [0] * len(pat)
            j = 0
            for i in range(1, len(pat)):
                while j and pat[i] != pat[j]:
                    j = lps[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                    lps[i] = j

            occ = []
            j = 0
            for i, ch in enumerate(text):
                while j and ch != pat[j]:
                    j = lps[j - 1]
                if ch == pat[j]:
                    j += 1
                    if j == len(pat):
                        occ.append(i - len(pat) + 1)
                        j = lps[j - 1]
            return occ

        a, b, c = p.split("*")
        la, lb, lc = len(a), len(b), len(c)

        occ_a = kmp_occurrences(s, a)
        occ_b = kmp_occurrences(s, b)
        occ_c = kmp_occurrences(s, c)

        ans = float("inf")
        ai = 0
        ci = 0
        latest_a = -1

        for b_start in occ_b:
            while ai < len(occ_a) and occ_a[ai] + la <= b_start:
                latest_a = occ_a[ai]
                ai += 1

            if latest_a == -1:
                continue

            need_c = b_start + lb
            while ci < len(occ_c) and occ_c[ci] < need_c:
                ci += 1

            if ci == len(occ_c):
                break

            ans = min(ans, occ_c[ci] + lc - latest_a)

        return -1 if ans == float("inf") else ans

class Solution:
    def countSubstrings(self, s: str) -> int:
        counts = [None] + [[0] * m for m in range(1, 10)]
        ans = 0

        for ch in s:
            digit = ord(ch) - ord('0')
            new_counts = [None]

            for m in range(1, 10):
                cur = [0] * m

                for r, cnt in enumerate(counts[m]):
                    if cnt:
                        cur[(r * 10 + digit) % m] += cnt

                cur[digit % m] += 1
                new_counts.append(cur)

            counts = new_counts

            if digit != 0:
                ans += counts[digit][0]

        return ans

from typing import List

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def count_pairs(left_count: int, right_count: int) -> int:
            limit = k + 1
            x_max = min(left_count, limit - 1)
            if x_max <= 0:
                return 0

            full = min(x_max, max(0, limit - right_count))
            total = full * right_count

            rem = x_max - full
            if rem:
                first = full + 1
                last = x_max
                total += rem * limit - (first + last) * rem // 2

            return total

        def contribution(for_max: bool) -> int:
            prev = [-1] * n
            nxt = [n] * n
            stack = []

            for i, v in enumerate(nums):
                if for_max:
                    while stack and nums[stack[-1]] <= v:
                        stack.pop()
                else:
                    while stack and nums[stack[-1]] >= v:
                        stack.pop()
                prev[i] = stack[-1] if stack else -1
                stack.append(i)

            stack.clear()

            for i in range(n - 1, -1, -1):
                v = nums[i]
                if for_max:
                    while stack and nums[stack[-1]] < v:
                        stack.pop()
                else:
                    while stack and nums[stack[-1]] > v:
                        stack.pop()
                nxt[i] = stack[-1] if stack else n
                stack.append(i)

            total = 0
            for i, v in enumerate(nums):
                total += v * count_pairs(i - prev[i], nxt[i] - i)
            return total

        return contribution(True) + contribution(False)

from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = ((1, 1), (1, -1), (-1, -1), (-1, 1))

        alt = []
        for dr, dc in dirs:
            dp = [[0] * m for _ in range(n)]
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)

            for i in rows:
                for j in cols:
                    v = grid[i][j]
                    if v in (0, 2):
                        ni, nj = i + dr, j + dc
                        dp[i][j] = 1
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 2 - v:
                            dp[i][j] += dp[ni][nj]
            alt.append(dp)

        ans = 0

        for d, (dr, dc) in enumerate(dirs):
            turn_d = (d + 1) % 4
            tdr, tdc = dirs[turn_d]
            suffix = alt[turn_d]

            pref = [[0] * m for _ in range(n)]
            rows = range(n) if dr == 1 else range(n - 1, -1, -1)
            cols = range(m) if dc == 1 else range(m - 1, -1, -1)

            for i in rows:
                for j in cols:
                    v = grid[i][j]

                    if v == 1:
                        length = 1
                    else:
                        length = 0
                        pi, pj = i - dr, j - dc
                        if 0 <= pi < n and 0 <= pj < m:
                            prev = pref[pi][pj]
                            expected = 2 if prev & 1 else 0
                            if prev and v == expected:
                                length = prev + 1

                    pref[i][j] = length

                    if length:
                        ans = max(ans, length)

                        ni, nj = i + tdr, j + tdc
                        expected = 2 if length & 1 else 0
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == expected:
                            ans = max(ans, length + suffix[ni][nj])

        return ans

class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7
        total_cells = m * n

        fact = [1] * (total_cells + 1)
        for i in range(1, total_cells + 1):
            fact[i] = fact[i - 1] * i % MOD

        inv_fact = [1] * (total_cells + 1)
        inv_fact[total_cells] = pow(fact[total_cells], MOD - 2, MOD)
        for i in range(total_cells, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        def comb(a: int, b: int) -> int:
            if b < 0 or b > a:
                return 0
            return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

        def one_dim_sum(length: int) -> int:
            return length * (length - 1) * (length + 1) // 6

        ways = comb(total_cells - 2, k - 2)

        row_sum = n * n * one_dim_sum(m)
        col_sum = m * m * one_dim_sum(n)

        return ways * ((row_sum + col_sum) % MOD) % MOD

from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def prefix_steps(n: int) -> int:
            total = 0
            start = 1
            steps = 1

            while start <= n:
                end = min(n, start * 4 - 1)
                total += (end - start + 1) * steps
                start *= 4
                steps += 1

            return total

        ans = 0
        for l, r in queries:
            total_steps = prefix_steps(r) - prefix_steps(l - 1)
            ans += (total_steps + 1) // 2

        return ans

from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can(target: int) -> bool:
            visits_next = 0
            moves = 0

            for i in range(n - 1):
                need = (target + points[i] - 1) // points[i]
                extra = max(0, need - visits_next)

                moves += 2 * extra + 1
                if moves > m:
                    return False

                visits_next = extra + 1

            need = (target + points[-1] - 1) // points[-1]
            extra = max(0, need - visits_next)
            moves += 2 * extra - 1

            return moves <= m

        lo, hi = 0, min(points) * m
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        total = n + m - 1

        word = [""] * total

        for i, ch in enumerate(str1):
            if ch == "T":
                for j, c in enumerate(str2):
                    pos = i + j
                    if word[pos] and word[pos] != c:
                        return ""
                    word[pos] = c

        for i in range(total):
            if not word[i]:
                word[i] = "a"

        z = [0] * m
        left = right = 0
        for i in range(1, m):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < m and str2[z[i]] == str2[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        lcp = [0] * total
        left = right = 0
        s = str2 + "#" + "".join(word)
        for i in range(m + 1, len(s)):
            if i <= right:
                lcp[i - m - 1] = min(right - i + 1, lcp[i - left])
            while (
                lcp[i - m - 1] < m
                and i + lcp[i - m - 1] < len(s)
                and s[lcp[i - m - 1]] == s[i + lcp[i - m - 1]]
            ):
                lcp[i - m - 1] += 1
            if i + lcp[i - m - 1] - 1 > right:
                left, right = i, i + lcp[i - m - 1] - 1

        bad = []
        for i, ch in enumerate(str1):
            if ch == "F" and lcp[i] >= m:
                bad.append(i)

        if not bad:
            return "".join(word)

        forced = [c != "" for c in word]
        last_changed = -1

        for start in bad:
            if start <= last_changed:
                continue

            changed = False
            for pos in range(start + m - 1, start - 1, -1):
                if forced[pos]:
                    continue

                original = word[pos]
                for code in range(ord(original) + 1, ord("z") + 1):
                    candidate = chr(code)
                    if candidate != str2[pos - start]:
                        word[pos] = candidate
                        last_changed = pos
                        changed = True
                        break

                if changed:
                    break

            if not changed:
                return ""

        ans = "".join(word)

        for i, ch in enumerate(str1):
            sub = ans[i : i + m]
            if (ch == "T" and sub != str2) or (ch == "F" and sub == str2):
                return ""

        return ans

from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        total = sum(nums)
        if k < -total or k > total:
            return -1

        offset = total
        width = 2 * total + 1
        mask = (1 << width) - 1
        overflow = limit + 1

        dp_odd = {}
        dp_even = {}

        def mul_bucket(p: int, x: int) -> int:
            if x == 0:
                return 0
            if p == overflow:
                return overflow
            q = p * x
            return q if q <= limit else overflow

        for x in nums:
            odd_items = list(dp_odd.items())
            even_items = list(dp_even.items())

            next_odd = dp_odd.copy()
            next_even = dp_even.copy()

            start_product = x if x <= limit else overflow
            next_odd[start_product] = next_odd.get(start_product, 0) | (1 << (offset + x))

            for p, bits in even_items:
                q = mul_bucket(p, x)
                shifted = (bits << x) & mask
                next_odd[q] = next_odd.get(q, 0) | shifted

            for p, bits in odd_items:
                q = mul_bucket(p, x)
                shifted = bits >> x
                next_even[q] = next_even.get(q, 0) | shifted

            dp_odd, dp_even = next_odd, next_even

        target_bit = 1 << (offset + k)
        for product in range(limit, -1, -1):
            if (dp_odd.get(product, 0) | dp_even.get(product, 0)) & target_bit:
                return product

        return -1

from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        perim = 4 * side

        def pos(x: int, y: int) -> int:
            if y == 0:
                return x
            if x == side:
                return side + y
            if y == side:
                return 3 * side - x
            return 4 * side - y

        p = sorted(pos(x, y) for x, y in points)
        n = len(p)
        q = p + [v + perim for v in p]

        def feasible(d: int) -> bool:
            nxt = [2 * n] * (2 * n)
            r = 0
            for i in range(2 * n):
                if r <= i:
                    r = i + 1
                while r < 2 * n and q[r] - q[i] < d:
                    r += 1
                nxt[i] = r

            for start in range(n):
                cur = start
                for _ in range(k - 1):
                    cur = nxt[cur]
                    if cur >= start + n:
                        break
                else:
                    if q[cur] - q[start] <= perim - d:
                        return True
            return False

        lo, hi = 0, side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        CAP = 10**15

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(CAP, fact[i - 1] * i)

        def count_completions(odds: int, evens: int, next_parity: int) -> int:
            length = odds + evens
            if length == 0:
                return 1

            if next_parity == 1:
                odd_slots = (length + 1) // 2
            else:
                odd_slots = length // 2

            even_slots = length - odd_slots
            if odds != odd_slots or evens != even_slots:
                return 0

            return min(CAP, fact[odds] * fact[evens])

        unused = list(range(1, n + 1))
        odds = (n + 1) // 2
        evens = n // 2
        ans = []
        required_parity = None

        for _ in range(n):
            chosen_index = -1

            for i, x in enumerate(unused):
                parity = x & 1
                if required_parity is not None and parity != required_parity:
                    continue

                new_odds = odds - (parity == 1)
                new_evens = evens - (parity == 0)
                cnt = count_completions(new_odds, new_evens, parity ^ 1)

                if k > cnt:
                    k -= cnt
                else:
                    chosen_index = i
                    break

            if chosen_index == -1:
                return []

            x = unused.pop(chosen_index)
            parity = x & 1
            ans.append(x)
            odds -= parity == 1
            evens -= parity == 0
            required_parity = parity ^ 1

        return ans

from typing import List


class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n

        children = [{}]
        count = [0]
        depth = [0]

        for word in words:
            node = 0
            for ch in word:
                if ch not in children[node]:
                    children[node][ch] = len(children)
                    children.append({})
                    count.append(0)
                    depth.append(depth[node] + 1)
                node = children[node][ch]
                count[node] += 1

        max_len = max(len(word) for word in words)
        valid_at_depth = [0] * (max_len + 1)

        for node in range(1, len(children)):
            if count[node] >= k:
                valid_at_depth[depth[node]] += 1

        size = 1
        while size <= max_len:
            size *= 2

        seg = [-1] * (2 * size)
        seg[size] = 0

        for d in range(1, max_len + 1):
            if valid_at_depth[d] > 0:
                seg[size + d] = d

        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[2 * i], seg[2 * i + 1])

        def update(pos: int) -> None:
            idx = size + pos
            seg[idx] = pos if pos == 0 or valid_at_depth[pos] > 0 else -1
            idx //= 2
            while idx:
                seg[idx] = max(seg[2 * idx], seg[2 * idx + 1])
                idx //= 2

        answer = []

        for word in words:
            node = 0
            changed_depths = []

            for ch in word:
                node = children[node][ch]
                if count[node] == k:
                    d = depth[node]
                    valid_at_depth[d] -= 1
                    update(d)
                    changed_depths.append(d)

            answer.append(seg[1])

            for d in changed_depths:
                valid_at_depth[d] += 1
                update(d)

        return answer

from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)

        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, idx))

        base = 0
        gain = [0] * m

        max1 = 0
        max1_count = 0
        max1_id = -1
        max2 = 0

        for right in range(1, n + 1):
            for left, idx in by_right[right]:
                if left > max1:
                    max2 = max1
                    max1 = left
                    max1_count = 1
                    max1_id = idx
                elif left == max1:
                    max1_count += 1
                elif left > max2:
                    max2 = left

            base += right - max1

            if max1_count == 1:
                gain[max1_id] += max1 - max2

        return base + max(gain)

from functools import lru_cache

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_upto(n: int) -> int:
            if n <= 0:
                return 0

            digits = list(map(int, str(n)))
            m = len(digits)
            total = 0

            for target_sum in range(1, 9 * m + 1):
                @lru_cache(None)
                def dp(pos: int, digit_sum: int, prod_mod: int, started: bool, tight: bool) -> int:
                    if digit_sum > target_sum:
                        return 0

                    if digit_sum + 9 * (m - pos) < target_sum:
                        return 0

                    if pos == m:
                        return int(started and digit_sum == target_sum and prod_mod == 0)

                    limit = digits[pos] if tight else 9
                    ans = 0

                    for d in range(limit + 1):
                        next_tight = tight and d == limit

                        if not started and d == 0:
                            ans += dp(pos + 1, digit_sum, 1 % target_sum, False, next_tight)
                        else:
                            next_sum = digit_sum + d
                            next_prod = (prod_mod * d) % target_sum if started else d % target_sum
                            ans += dp(pos + 1, next_sum, next_prod, True, next_tight)

                    return ans

                total += dp(0, 0, 1 % target_sum, False, True)

            return total

        return count_upto(r) - count_upto(l - 1)

import sys

def main():
    input = sys.stdin.readline
    N, M, A, B = map(int, input().split())
    bad = [tuple(map(int, input().split())) for _ in range(M)]

    points = {1, N}
    for L, R in bad:
        for x in range(max(1, L - B), L):
            points.add(x)
        for x in range(R + 1, min(N, R + B) + 1):
            points.add(x)

    points = sorted(points)
    reachable = set()

    if A == B:
        seen = {}
        idx = 0

        for x in points:
            while idx < M and bad[idx][1] < x:
                idx += 1
            if idx < M and bad[idx][0] <= x <= bad[idx][1]:
                continue

            seg = idx
            ok = (x == 1) or (x - A in reachable) or ((seg, x % A) in seen)

            if ok:
                if x == N:
                    print("Yes")
                    return
                reachable.add(x)
                seen[(seg, x % A)] = True

    else:
        max_d = B * B + B
        representable = [False] * (max_d + 1)
        representable[0] = True
        for d in range(max_d + 1):
            if representable[d]:
                for s in range(A, B + 1):
                    if d + s <= max_d:
                        representable[d + s] = True

        threshold = 0
        for t in range(max_d + 1):
            if all(representable[d] for d in range(t, max_d + 1)):
                threshold = t
                break

        min_reach = [None] * (M + 1)
        idx = 0

        for x in points:
            while idx < M and bad[idx][1] < x:
                idx += 1
            if idx < M and bad[idx][0] <= x <= bad[idx][1]:
                continue

            seg = idx
            ok = (x == 1)

            if not ok:
                for s in range(A, B + 1):
                    if x - s in reachable:
                        ok = True
                        break

            if not ok:
                mn = min_reach[seg]
                if mn is not None and x - mn >= threshold:
                    ok = True

            if ok:
                if x == N:
                    print("Yes")
                    return
                reachable.add(x)
                if min_reach[seg] is None or x < min_reach[seg]:
                    min_reach[seg] = x

    print("No")

