import sys

def main():
    input = sys.stdin.buffer.readline

    N = int(input())
    contests = [tuple(map(int, input().split())) for _ in range(N)]

    Q = int(input())
    queries = [int(input()) for _ in range(Q)]

    M = max(queries)

    size = 1
    log = 0
    while size < M:
        size <<= 1
        log += 1

    INF_NEG = -10**18
    seg = [INF_NEG] * (2 * size)
    lazy = [0] * size

    for i in range(M):
        seg[size + i] = i + 1
    for i in range(size - 1, 0, -1):
        seg[i] = max(seg[i << 1], seg[i << 1 | 1])

    def apply(k, v):
        seg[k] += v
        if k < size:
            lazy[k] += v

    def push(k):
        if lazy[k]:
            v = lazy[k]
            apply(k << 1, v)
            apply(k << 1 | 1, v)
            lazy[k] = 0

    def first_ge(x):
        if seg[1] < x:
            return M

        k = 1
        while k < size:
            push(k)
            if seg[k << 1] >= x:
                k <<= 1
            else:
                k = k << 1 | 1
        return k - size

    def range_add(l, r, v):
        if l >= r:
            return

        l += size
        r += size
        l0, r0 = l, r

        for i in range(log, 0, -1):
            if ((l0 >> i) << i) != l0:
                push(l0 >> i)
            if ((r0 >> i) << i) != r0:
                push((r0 - 1) >> i)

        while l < r:
            if l & 1:
                apply(l, v)
                l += 1
            if r & 1:
                r -= 1
                apply(r, v)
            l >>= 1
            r >>= 1

        for i in range(1, log + 1):
            if ((l0 >> i) << i) != l0:
                k = l0 >> i
                seg[k] = max(seg[k << 1], seg[k << 1 | 1])
            if ((r0 >> i) << i) != r0:
                k = (r0 - 1) >> i
                seg[k] = max(seg[k << 1], seg[k << 1 | 1])

    for L, R in contests:
        l = first_ge(L)
        r = first_ge(R + 1)
        range_add(l, r, 1)

    for k in range(1, size):
        push(k)

    print("\n".join(str(seg[size + x - 1]) for x in queries))

if __name__ == "__main__":
    main()

import sys

def main():
    N, P = map(int, sys.stdin.readline().split())
    half = N // 2
    max_edges = N * (N - 1) // 2

    fact = [1] * (max_edges + 1)
    invfact = [1] * (max_edges + 1)
    for i in range(1, max_edges + 1):
        fact[i] = fact[i - 1] * i % P
    invfact[max_edges] = pow(fact[max_edges], P - 2, P)
    for i in range(max_edges, 0, -1):
        invfact[i - 1] = invfact[i] * i % P

    def comb(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * invfact[k] % P * invfact[n - k] % P

    binom = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N + 1):
        binom[i][0] = binom[i][i] = 1
        for j in range(1, i):
            binom[i][j] = (binom[i - 1][j - 1] + binom[i - 1][j]) % P

    def multiply(poly_a, poly_b):
        off_a, a = poly_a
        off_b, b = poly_b
        off = off_a + off_b
        max_len = max_edges - off + 1
        length = min(len(a) + len(b) - 1, max_len)

        res = [0] * length
        for i, ai in enumerate(a):
            if ai == 0:
                continue
            upto = min(len(b), length - i)
            if upto <= 0:
                break
            for j in range(upto):
                res[i + j] = (res[i + j] + ai * b[j]) % P

        return off, res

    transition_cache = {}

    def transition(prev_size, cur_size):
        key = (prev_size, cur_size)
        if key in transition_cache:
            return transition_cache[key]

        base = (1, [binom[prev_size][k] for k in range(1, prev_size + 1)])
        poly = (0, [1])

        for _ in range(cur_size):
            poly = multiply(poly, base)

        inside = cur_size * (cur_size - 1) // 2
        poly = multiply(poly, (0, [comb(inside, k) for k in range(inside + 1)]))

        off, coef = poly
        inv = invfact[cur_size]
        coef = [v * inv % P for v in coef]

        transition_cache[key] = (off, coef)
        return transition_cache[key]

    buckets = [dict() for _ in range(N + 1)]
    buckets[1][(1, 1, 1)] = (0, [1])

    for used in range(1, N):
        for (even_count, last_size, next_parity), poly in list(buckets[used].items()):
            for cur_size in range(1, N - used + 1):
                new_used = used + cur_size
                new_even = even_count + (cur_size if next_parity == 0 else 0)
                new_odd = new_used - new_even

                if new_even > half or new_odd > half:
                    continue

                new_poly = multiply(poly, transition(last_size, cur_size))
                key = (new_even, cur_size, 1 - next_parity)

                if key not in buckets[new_used]:
                    buckets[new_used][key] = new_poly
                else:
                    old_off, old_coef = buckets[new_used][key]
                    new_off, new_coef = new_poly
                    if len(old_coef) < len(new_coef):
                        old_coef.extend([0] * (len(new_coef) - len(old_coef)))
                    for i, v in enumerate(new_coef):
                        old_coef[i] = (old_coef[i] + v) % P

    ans = [0] * (max_edges - (N - 1) + 1)
    for (even_count, _, _), (_, coef) in buckets[N].items():
        if even_count == half:
            for i, v in enumerate(coef):
                ans[i] = (ans[i] + v) % P

    label_factor = fact[N - 1]
    ans = [v * label_factor % P for v in ans]

    print(*ans)

if __name__ == "__main__":
    main()

import sys

def main():
    input = sys.stdin.readline
    N, X = map(int, input().split())

    foods = [[] for _ in range(3)]
    for _ in range(N):
        v, a, c = map(int, input().split())
        foods[v - 1].append((a, c))

    dps = []
    for group in foods:
        dp = [0] * (X + 1)
        for a, c in group:
            for cal in range(X, c - 1, -1):
                dp[cal] = max(dp[cal], dp[cal - c] + a)
        dps.append(dp)

    def min_cost(dp, target):
        for cal, value in enumerate(dp):
            if value >= target:
                return cal
        return X + 1

    def feasible(target):
        total = 0
        for dp in dps:
            total += min_cost(dp, target)
            if total > X:
                return False
        return True

    low = 0
    high = min(dp[X] for dp in dps) + 1

    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(low)

