import sys

MOD = 998244353

def main():
    N = int(sys.stdin.readline())
    max_len = len(str(N))

    p10 = [1] * (max_len + 1)
    for i in range(1, max_len + 1):
        p10[i] = p10[i - 1] * 10

    cnt = [0] * (max_len + 1)
    sum_by_len = [0] * (max_len + 1)

    for d in range(1, max_len + 1):
        lo = 1 if d == 1 else p10[d - 1]
        hi = min(N, p10[d] - 1)
        if lo <= hi:
            c = hi - lo + 1
            cnt[d] = c
            sum_by_len[d] = ((lo + hi) * c // 2) % MOD

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD

    inv = [0] * (N + 1)
    if N >= 1:
        inv[1] = 1
    for i in range(2, N + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    weights = [pow(10, d, MOD) for d in range(1, max_len + 1)]
    D = max_len
    n = N - 1

    q = [1]
    for a in weights:
        q.append(0)
        for i in range(len(q) - 2, -1, -1):
            q[i + 1] = (q[i + 1] + q[i] * a) % MOD

    excl_polys = []
    for skip in range(D):
        poly = [1]
        for i, a in enumerate(weights):
            if i == skip:
                continue
            poly.append(0)
            for j in range(len(poly) - 2, -1, -1):
                poly[j + 1] = (poly[j + 1] + poly[j] * a) % MOD
        excl_polys.append(poly)

    def calc_g(m):
        r = [0] * D
        for i, a in enumerate(weights):
            multiplicity = m[i + 1] % MOD
            if multiplicity == 0:
                continue
            coef = multiplicity * a % MOD
            poly = excl_polys[i]
            for j in range(D):
                r[j] = (r[j] + coef * poly[j]) % MOD

        e = [0] * (n + 1)
        e[0] = 1
        total = fact[n]

        for k in range(n):
            val = 0

            for j in range(min(D - 1, k) + 1):
                val += r[j] * e[k - j]

            for j in range(1, min(D, k) + 1):
                idx = k - j + 1
                val -= q[j] * idx * e[idx]

            e[k + 1] = (val % MOD) * inv[k + 1] % MOD
            total = (total + fact[k + 1] * fact[n - k - 1] % MOD * e[k + 1]) % MOD

        return total

    ans = 0
    for d in range(1, max_len + 1):
        if cnt[d] == 0:
            continue
        m = cnt[:]
        m[d] -= 1
        ans = (ans + sum_by_len[d] * calc_g(m)) % MOD

    print(ans)

if __name__ == "__main__":
    main()

