import sys

MOD = 998244353

def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    S = input().strip()

    size = 1 << N

    rows = []
    for mask in range(size):
        row = [0] * (N + 1)
        for i in range(N):
            row[i + 1] = row[i] + ((mask >> i) & 1)
        rows.append(row)

    trans = [[0] * 26 for _ in range(size)]
    for mask in range(size):
        dp = rows[mask]
        for c in range(26):
            ch = chr(ord("a") + c)
            ndp = [0] * (N + 1)
            next_mask = 0

            for j in range(1, N + 1):
                val = max(dp[j], ndp[j - 1])
                if S[j - 1] == ch:
                    val = max(val, dp[j - 1] + 1)

                ndp[j] = val
                if ndp[j] > ndp[j - 1]:
                    next_mask |= 1 << (j - 1)

            trans[mask][c] = next_mask

    dp = [0] * size
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * size
        for mask, count in enumerate(dp):
            if count == 0:
                continue
            for c in range(26):
                nmask = trans[mask][c]
                ndp[nmask] += count
                if ndp[nmask] >= MOD:
                    ndp[nmask] -= MOD
        dp = ndp

    ans = [0] * (N + 1)
    for mask, count in enumerate(dp):
        ans[mask.bit_count()] = (ans[mask.bit_count()] + count) % MOD

    print(*ans)

if __name__ == "__main__":
    main()

import sys


def main():
    data = sys.stdin.buffer.read()
    length = len(data)
    pos = 0

    def next_int():
        nonlocal pos
        while pos < length and data[pos] <= 32:
            pos += 1
        val = 0
        while pos < length and data[pos] > 32:
            val = val * 10 + (data[pos] - 48)
            pos += 1
        return val

    n = next_int()
    k = next_int()

    a = [0] * n
    max_a = 0
    freq = [0] * (10**6 + 1)

    for i in range(n):
        x = next_int()
        a[i] = x
        freq[x] += 1
        if x > max_a:
            max_a = x

    if k == 1:
        sys.stdout.write("\n".join(map(str, a)) + "\n")
        return

    ans = [0] * (max_a + 1)

    for d in range(1, max_a + 1):
        cnt = 0
        for m in range(d, max_a + 1, d):
            cnt += freq[m]

        if cnt >= k:
            for m in range(d, max_a + 1, d):
                ans[m] = d

    sys.stdout.write("\n".join(str(ans[x]) for x in a) + "\n")


