import sys
from collections import deque

def main():
    input = sys.stdin.readline
    N = int(input())
    C = [input().strip() for _ in range(N)]

    incoming = [[[] for _ in range(26)] for _ in range(N)]
    outgoing = [[[] for _ in range(26)] for _ in range(N)]

    for i in range(N):
        for j, ch in enumerate(C[i]):
            if ch != '-':
                k = ord(ch) - ord('a')
                outgoing[i][k].append(j)
                incoming[j][k].append(i)

    dist = [[-1] * N for _ in range(N)]
    q = deque()

    for i in range(N):
        dist[i][i] = 0
        q.append((i, i))

    for i in range(N):
        for j, ch in enumerate(C[i]):
            if ch != '-' and dist[i][j] == -1:
                dist[i][j] = 1
                q.append((i, j))

    while q:
        u, v = q.popleft()
        nd = dist[u][v] + 2

        for c in range(26):
            for a in incoming[u][c]:
                row = dist[a]
                for b in outgoing[v][c]:
                    if row[b] == -1:
                        row[b] = nd
                        q.append((a, b))

    print('\n'.join(' '.join(map(str, row)) for row in dist))

