import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    adj = [[] for _ in range(n)]
    idx = 1
    for _ in range(n - 1):
        a = data[idx] - 1
        b = data[idx + 1] - 1
        idx += 2
        adj[a].append(b)
        adj[b].append(a)

    parent = [-1] * n
    order = [0]
    for u in order:
        for v in adj[u]:
            if v == parent[u]:
                continue
            parent[v] = u
            order.append(v)

    down = [1] * n
    for u in reversed(order):
        best = []
        for v in adj[u]:
            if parent[v] == u:
                best.append(down[v])
        best.sort(reverse=True)
        if len(best) >= 3:
            down[u] = 1 + sum(best[:3])

    up = [0] * n
    ans = -1

    for u in order:
        branches = []
        if parent[u] != -1:
            branches.append((up[u], parent[u]))

        for v in adj[u]:
            if parent[v] == u:
                branches.append((down[v], v))

        branches.sort(reverse=True)

        if len(branches) >= 4:
            ans = max(ans, 1 + sum(val for val, _ in branches[:4]))

        for v in adj[u]:
            if parent[v] != u:
                continue

            chosen = []
            for val, to in branches:
                if to != v:
                    chosen.append(val)
                    if len(chosen) == 3:
                        break

            if len(chosen) == 3:
                up[v] = 1 + sum(chosen)
            else:
                up[v] = 1

    print(ans)

if __name__ == "__main__":
    main()

import sys

class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, x):
        i += 1
        while i <= self.n:
            self.bit[i] += x
            i += i & -i

    def sum(self, i):
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s

def main():
    input = sys.stdin.buffer.readline
    N, M = map(int, input().split())
    A = list(map(int, input().split()))

    fw = Fenwick(M)
    inv = 0
    delta = [0] * M

    for i, a in enumerate(A, start=1):
        inv += (i - 1) - fw.sum(a + 1)
        fw.add(a, 1)
        delta[a] += 2 * i - N - 1

    ans = []
    cur = inv
    for k in range(M):
        ans.append(str(cur))
        if k + 1 < M:
            cur += delta[M - 1 - k]

    print("\n".join(ans))

if __name__ == "__main__":
    main()

