def main():
    input = sys.stdin.buffer.readline
    N, K = map(int, input().split())
    M = N * K

    adj = [[] for _ in range(M)]
    for _ in range(M - 1):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        adj[u].append(v)
        adj[v].append(u)

    if K == 1:
        print("Yes")
        return

    parent = [-1] * M
    order = [0]
    parent[0] = -2

    for v in order:
        for to in adj[v]:
            if to == parent[v]:
                continue
            parent[to] = v
            order.append(to)

    rem = [0] * M

    for v in reversed(order):
        chains = []
        for to in adj[v]:
            if parent[to] == v and rem[to] > 0:
                chains.append(rem[to])
                if len(chains) > 2:
                    print("No")
                    return

        if len(chains) == 0:
            rem[v] = 1
        elif len(chains) == 1:
            length = chains[0] + 1
            if length < K:
                rem[v] = length
            elif length == K:
                rem[v] = 0
            else:
                print("No")
                return
        else:
            if chains[0] + chains[1] + 1 == K:
                rem[v] = 0
            else:
                print("No")
                return

    print("Yes" if rem[0] == 0 else "No")

