import sys
from collections import deque


class Edge:
    __slots__ = ("to", "rev", "cap")

    def __init__(self, to, rev, cap):
        self.to = to
        self.rev = rev
        self.cap = cap


class Dinic:
    def __init__(self, n):
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        fwd = Edge(to, len(self.g[to]), cap)
        rev = Edge(fr, len(self.g[fr]), 0)
        self.g[fr].append(fwd)
        self.g[to].append(rev)

    def max_flow(self, s, t, limit):
        flow = 0
        n = len(self.g)

        while flow < limit:
            level = [-1] * n
            level[s] = 0
            q = deque([s])

            while q:
                v = q.popleft()
                for e in self.g[v]:
                    if e.cap > 0 and level[e.to] == -1:
                        level[e.to] = level[v] + 1
                        q.append(e.to)

            if level[t] == -1:
                return flow

            it = [0] * n

            def dfs(v, f):
                if v == t:
                    return f

                while it[v] < len(self.g[v]):
                    e = self.g[v][it[v]]
                    if e.cap > 0 and level[e.to] == level[v] + 1:
                        ret = dfs(e.to, min(f, e.cap))
                        if ret:
                            e.cap -= ret
                            self.g[e.to][e.rev].cap += ret
                            return ret
                    it[v] += 1

                return 0

            while flow < limit:
                pushed = dfs(s, limit - flow)
                if pushed == 0:
                    break
                flow += pushed

        return flow


def min_edges_needed(n, edges, d, k):
    inf = k + 1
    total_vars = n * d
    source = total_vars
    sink = source + 1
    dinic = Dinic(total_vars + 2)

    def node(v, i):
        return v * d + (i - 1)

    for i in range(1, d + 1):
        dinic.add_edge(node(0, i), sink, inf)
        dinic.add_edge(source, node(n - 1, i), inf)

    for v in range(n):
        for i in range(1, d):
            dinic.add_edge(node(v, i + 1), node(v, i), inf)

    for u, v in edges:
        for i in range(1, d + 1):
            dinic.add_edge(node(v, i), node(u, i), 1)

        for i in range(2, d + 1):
            dinic.add_edge(node(v, i), node(u, i - 1), inf)

    return dinic.max_flow(source, sink, inf)


def main():
    input = sys.stdin.readline
    n, m, k = map(int, input().split())
    edges = [tuple(int(x) - 1 for x in input().split()) for _ in range(m)]

    ans = 0
    for d in range(1, n):
        if min_edges_needed(n, edges, d, k) <= k:
            ans = d

    print(ans)


