import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    s = data[1]
    t = data[2]

    to = [-1] * 26
    target_used = [False] * 26

    for sc, tc in zip(s, t):
        a = ord(sc) - ord('a')
        b = ord(tc) - ord('a')
        target_used[b] = True

        if to[a] == -1:
            to[a] = b
        elif to[a] != b:
            print(-1)
            return

    base_ops = 0
    indeg = [0] * 26

    for i in range(26):
        if to[i] != -1:
            indeg[to[i]] += 1
            if to[i] != i:
                base_ops += 1

    visited = [False] * 26
    extra_cycles = 0

    for start in range(26):
        if visited[start] or to[start] == -1 or to[start] == start:
            continue

        path = []
        pos = {}
        cur = start

        while True:
            if cur == -1 or to[cur] == -1 or to[cur] == cur or visited[cur]:
                break

            if cur in pos:
                cycle = path[pos[cur]:]
                if all(indeg[v] == 1 for v in cycle):
                    extra_cycles += 1
                break

            pos[cur] = len(path)
            path.append(cur)
            cur = to[cur]

        for v in path:
            visited[v] = True

    if extra_cycles and sum(target_used) == 26:
        print(-1)
    else:
        print(base_ops + extra_cycles)

