import sys

INF = 10**30

SRC = []
for used in range(4):
    cur = []
    for delta in range(-used, used + 1):
        didx = delta + 4
        for parity in range(8):
            idx = ((used * 9 + didx) * 8 + parity)
            cur.append((idx, didx, parity))
    SRC.append(cur)


def solve_case(items, k):
    m = 2 * k

    enriched = []
    for x, y, z in items:
        vals = (x, y, z)
        best = max(vals)
        label = vals.index(best)
        enriched.append((best, label, vals))

    enriched.sort(key=lambda e: e[0], reverse=True)

    base = 0
    need = 0
    for i in range(m):
        best, label, _ = enriched[i]
        base += best
        need ^= 1 << label

    if need == 0:
        return base

    dp = [INF] * (5 * 9 * 8)
    dp[(0 * 9 + 4) * 8 + 0] = 0

    for i, (best, label, vals) in enumerate(enriched):
        if i < m:
            transitions = [(-1, 1 << label, best)]
            for d in range(3):
                if d != label:
                    transitions.append((0, (1 << label) ^ (1 << d), best - vals[d]))
        else:
            transitions = [(1, 1 << d, -vals[d]) for d in range(3)]

        for used in range(3, -1, -1):
            next_base = (used + 1) * 9 * 8
            for idx, didx, parity in SRC[used]:
                cur = dp[idx]
                if cur == INF:
                    continue
                for dd, mask, cost in transitions:
                    nd = didx + dd
                    if 0 <= nd < 9:
                        ni = next_base + nd * 8 + (parity ^ mask)
                        nv = cur + cost
                        if nv < dp[ni]:
                            dp[ni] = nv

    loss = min(dp[(used * 9 + 4) * 8 + need] for used in range(5))
    return base - loss


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    t = next(it)
    ans = []

    for _ in range(t):
        n = next(it)
        k = next(it)
        items = [(next(it), next(it), next(it)) for _ in range(n)]
        ans.append(str(solve_case(items, k)))

    print("\n".join(ans))


if __name__ == "__main__":
    main()

import sys

def mat_mul(A, B, mod):
    n = len(A)
    R = []
    for i in range(n):
        row = [0] * n
        Ai = A[i]
        for k, a in enumerate(Ai):
            if a:
                Bk = B[k]
                row = [x + a * y for x, y in zip(row, Bk)]
        R.append([x % mod for x in row])
    return R

def mat_pow(A, e, mod):
    n = len(A)
    R = [[0] * n for _ in range(n)]
    for i in range(n):
        R[i][i] = 1

    while e:
        if e & 1:
            R = mat_mul(R, A, mod)
        e >>= 1
        if e:
            A = mat_mul(A, A, mod)
    return R

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N, p = data[0], data[1]
    vals = data[2:]
    A = [vals[i * N:(i + 1) * N] for i in range(N)]

    if p == 2:
        v = N % 2
        print("\n".join(" ".join([str(v)] * N) for _ in range(N)))
        return

    zeros = []
    for i in range(N):
        for j in range(N):
            if A[i][j] == 0:
                zeros.append((i, j))

    ans = mat_pow(A, p, p)

    for a, b in zeros:
        if a == b:
            for i in range(N):
                ans[i][a] += A[i][a]
            for j in range(N):
                ans[a][j] += A[a][j]
        elif p == 3:
            ans[a][b] += A[b][a]

    negate = len(zeros) % 2 == 1

    out = []
    for i in range(N):
        row = []
        for j in range(N):
            x = ans[i][j] % p
            if negate:
                x = (-x) % p
            row.append(str(x))
        out.append(" ".join(row))

    print("\n".join(out))

if __name__ == "__main__":
    main()

import sys

LIMIT = 31623

is_prime = [True] * (LIMIT + 1)
primes = []
for i in range(2, LIMIT + 1):
    if is_prime[i]:
        primes.append(i)
        if i * i <= LIMIT:
            for j in range(i * i, LIMIT + 1, i):
                is_prime[j] = False


def factorize(n):
    res = []
    for p in primes:
        if p * p > n:
            break
        if n % p == 0:
            e = 0
            while n % p == 0:
                n //= p
                e += 1
            res.append((p, e))
    if n > 1:
        res.append((n, 1))
    return res


def construct(n):
    if n == 1:
        return 1, 1

    fs = factorize(n)
    m = 1
    for p, e in fs:
        m *= p ** (e + 1)

    return m + 1, m * m


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    t = data[0]
    ans = []

    for i in range(1, t + 1):
        a, m = construct(data[i])
        ans.append(f"{a} {m}")

    print("\n".join(ans))


