import sys

MOD = 998244353
MAX_A = 1000


def build_spf(limit):
    spf = list(range(limit + 1))
    for i in range(2, int(limit ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, limit + 1, i):
                if spf[j] == j:
                    spf[j] = i
    return spf


def factorize(x, spf):
    res = []
    while x > 1:
        p = spf[x]
        cnt = 0
        while x % p == 0:
            x //= p
            cnt += 1
        res.append((p, cnt))
    return res


def contribution(p, exps):
    total = sum(exps)
    max_add = total

    for i, e in enumerate(exps, 1):
        max_add = max(max_add, i * e)

    pow_p = [1] * (max_add + 1)
    for i in range(max_add):
        pow_p[i + 1] = pow_p[i] * p % MOD

    dp = [0] * (total + 1)
    dp[0] = 1
    max_h = 0

    for i, e in enumerate(exps, 1):
        ndp = [0] * (total + 1)

        if e == 0:
            for h in range(max_h + 1):
                if dp[h]:
                    ndp[h] = dp[h] * pow_p[h] % MOD
        else:
            for h in range(max_h + 1):
                cur = dp[h]
                if cur == 0:
                    continue

                up = h + e
                ndp[up] = (ndp[up] + cur * pow_p[up]) % MOD

                if h >= e:
                    down = h - e
                    add = down
                else:
                    down = 0
                    add = i * (e - h)

                ndp[down] = (ndp[down] + cur * pow_p[add]) % MOD

            max_h += e

        dp = ndp

    return sum(dp) % MOD


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    spf = build_spf(MAX_A)
    exps_by_prime = {}

    for i, x in enumerate(a):
        for p, e in factorize(x, spf):
            if p not in exps_by_prime:
                exps_by_prime[p] = [0] * (n - 1)
            exps_by_prime[p][i] = e

    ans = 1
    for p, exps in exps_by_prime.items():
        ans = ans * contribution(p, exps) % MOD

    print(ans)


if __name__ == "__main__":
    main()

import sys

MOD = 998244353

W, H, L, R, D, U = map(int, sys.stdin.readline().split())

max_n = W + H + 5
fact = [1] * (max_n + 1)
for i in range(1, max_n + 1):
    fact[i] = fact[i - 1] * i % MOD

invfact = [1] * (max_n + 1)
invfact[max_n] = pow(fact[max_n], MOD - 2, MOD)
for i in range(max_n, 0, -1):
    invfact[i - 1] = invfact[i] * i % MOD


def comb(n, k):
    if k < 0 or k > n:
        return 0
    return fact[n] * invfact[k] % MOD * invfact[n - k] % MOD


def paths_to(a, b):
    if a < 0 or b < 0:
        return 0
    return (comb(a + b + 2, a + 1) - 1) % MOD


def all_paths(a, b):
    if a < 0 or b < 0:
        return 0
    return (comb(a + b + 4, a + 2) - a - b - 4 - (a + 1) * (b + 1)) % MOD


def rect_sum(x1, x2, y1, y2):
    if x1 > x2 or y1 > y2:
        return 0
    return (
        all_paths(x2, y2)
        - all_paths(x1 - 1, y2)
        - all_paths(x2, y1 - 1)
        + all_paths(x1 - 1, y1 - 1)
    ) % MOD


ans = all_paths(W, H)

# Paths entirely inside the removed rectangle.
ans -= rect_sum(W - R, W - L, H - U, H - D)

# Paths that enter the removed rectangle from below.
if D > 0:
    for x in range(L, R + 1):
        ans -= paths_to(x, D - 1) * paths_to(W - x, H - D)
        ans %= MOD

# Paths that enter the removed rectangle from the left.
if L > 0:
    for y in range(D, U + 1):
        ans -= paths_to(L - 1, y) * paths_to(W - L, H - y)
        ans %= MOD

print(ans % MOD)

import sys


class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, v):
        while i <= self.n:
            self.bit[i] += v
            i += i & -i

    def sum(self, i):
        res = 0
        while i > 0:
            res += self.bit[i]
            i -= i & -i
        return res


def main():
    input = sys.stdin.readline
    n = int(input())
    p = list(map(int, input().split()))

    pos = [0] * (n + 1)
    fw = Fenwick(n)

    for i, x in enumerate(p, 1):
        pos[x] = i
        fw.add(i, 1)

    ans = 0

    for x in range(n, 0, -1):
        cur = fw.sum(pos[x])
        ans += (cur + x - 1) * (x - cur) // 2
        fw.add(pos[x], -1)

    print(ans)


if __name__ == "__main__":
    main()

import sys
import heapq


class HalfDiff:
    def __init__(self):
        self.low = []
        self.high = []
        self.sum_low = 0
        self.sum_high = 0

    def add(self, x):
        if not self.low or x <= -self.low[0]:
            heapq.heappush(self.low, -x)
            self.sum_low += x
        else:
            heapq.heappush(self.high, x)
            self.sum_high += x

        if len(self.low) > len(self.high) + 1:
            v = -heapq.heappop(self.low)
            self.sum_low -= v
            heapq.heappush(self.high, v)
            self.sum_high += v
        elif len(self.low) < len(self.high):
            v = heapq.heappop(self.high)
            self.sum_high -= v
            heapq.heappush(self.low, -v)
            self.sum_low += v

    def diff(self):
        return self.sum_high - self.sum_low


def main():
    input = sys.stdin.readline
    N = int(input())
    A = list(map(int, input().split()))

    pref = [0] * (N + 1)
    hd = HalfDiff()
    for i, x in enumerate(A, 1):
        hd.add(x)
        if i % 2 == 0:
            pref[i] = hd.diff()

    if N % 2 == 0:
        print(pref[N])
        return

    suff = [0] * (N + 2)
    hd = HalfDiff()
    for i in range(N, 0, -1):
        hd.add(A[i - 1])
        if (N - i + 1) % 2 == 0:
            suff[i] = hd.diff()

    ans = 0
    for i in range(1, N + 1, 2):
        ans = max(ans, pref[i - 1] + suff[i + 1])

    print(ans)


if __name__ == "__main__":
    main()

import sys
from heapq import heappush, heappop

INF = 10 ** 9


def main():
    input = sys.stdin.readline
    N, M, Q = map(int, input().split())

    left = [0] * (M + 1)
    right = [0] * (M + 1)
    sign = [0] * (M + 1)

    for i in range(1, M + 1):
        s, t = map(int, input().split())
        if s < t:
            left[i], right[i], sign[i] = s, t, 1
        else:
            left[i], right[i], sign[i] = t, s, -1

    bad = [INF] * (M + 1)

    last = [0] * (N + 1)
    for i in range(1, M + 1):
        x = left[i]
        if last[x]:
            bad[last[x]] = min(bad[last[x]], i)
        last[x] = i

    last = [0] * (N + 1)
    for i in range(1, M + 1):
        x = right[i]
        if last[x]:
            bad[last[x]] = min(bad[last[x]], i)
        last[x] = i

    def process_cross(target_sign):
        size = 1
        while size < N + 2:
            size <<= 1

        min_val = [INF] * (2 * size)
        min_idx = [0] * (2 * size)
        max_val = [-INF] * (2 * size)
        max_idx = [0] * (2 * size)

        heaps_by_r = {}
        heaps_by_l = {}
        active = [False] * (M + 1)

        def pull_min(pos):
            h = heaps_by_r.get(pos)
            while h and not active[h[0][1]]:
                heappop(h)

            p = pos + size
            if h:
                min_val[p], min_idx[p] = h[0]
            else:
                min_val[p], min_idx[p] = INF, 0

            p >>= 1
            while p:
                lc = p << 1
                rc = lc | 1
                if min_val[lc] <= min_val[rc]:
                    min_val[p], min_idx[p] = min_val[lc], min_idx[lc]
                else:
                    min_val[p], min_idx[p] = min_val[rc], min_idx[rc]
                p >>= 1

        def pull_max(pos):
            h = heaps_by_l.get(pos)
            while h and not active[h[0][1]]:
                heappop(h)

            p = pos + size
            if h:
                max_val[p], max_idx[p] = -h[0][0], h[0][1]
            else:
                max_val[p], max_idx[p] = -INF, 0

            p >>= 1
            while p:
                lc = p << 1
                rc = lc | 1
                if max_val[lc] >= max_val[rc]:
                    max_val[p], max_idx[p] = max_val[lc], max_idx[lc]
                else:
                    max_val[p], max_idx[p] = max_val[rc], max_idx[rc]
                p >>= 1

        def range_min(ql, qr):
            ql += size
            qr += size
            best_v = INF
            best_i = 0
            while ql <= qr:
                if ql & 1:
                    if min_val[ql] < best_v:
                        best_v, best_i = min_val[ql], min_idx[ql]
                    ql += 1
                if not (qr & 1):
                    if min_val[qr] < best_v:
                        best_v, best_i = min_val[qr], min_idx[qr]
                    qr -= 1
                ql >>= 1
                qr >>= 1
            return best_v, best_i

        def range_max(ql, qr):
            ql += size
            qr += size
            best_v = -INF
            best_i = 0
            while ql <= qr:
                if ql & 1:
                    if max_val[ql] > best_v:
                        best_v, best_i = max_val[ql], max_idx[ql]
                    ql += 1
                if not (qr & 1):
                    if max_val[qr] > best_v:
                        best_v, best_i = max_val[qr], max_idx[qr]
                    qr -= 1
                ql >>= 1
                qr >>= 1
            return best_v, best_i

        def deactivate(idx):
            active[idx] = False
            pull_min(right[idx])
            pull_max(left[idx])

        def activate(idx):
            active[idx] = True

            h = heaps_by_r.setdefault(right[idx], [])
            heappush(h, (left[idx], idx))
            pull_min(right[idx])

            h = heaps_by_l.setdefault(left[idx], [])
            heappush(h, (-right[idx], idx))
            pull_max(left[idx])

        for j in range(1, M + 1):
            if sign[j] != target_sign:
                continue

            l, r = left[j], right[j]
            ql, qr = l + 1, r - 1

            while True:
                v, idx = range_min(ql, qr)
                if idx == 0 or v >= l:
                    break
                bad[idx] = min(bad[idx], j)
                deactivate(idx)

            while True:
                v, idx = range_max(ql, qr)
                if idx == 0 or v <= r:
                    break
                bad[idx] = min(bad[idx], j)
                deactivate(idx)

            activate(j)

    process_cross(1)
    process_cross(-1)

    size = 1
    while size < M:
        size <<= 1

    seg = [INF] * (2 * size)
    for i in range(1, M + 1):
        seg[size + i - 1] = bad[i]

    for p in range(size - 1, 0, -1):
        seg[p] = min(seg[p << 1], seg[p << 1 | 1])

    def query(l, r):
        l = l - 1 + size
        r = r - 1 + size
        ans = INF
        while l <= r:
            if l & 1:
                ans = min(ans, seg[l])
                l += 1
            if not (r & 1):
                ans = min(ans, seg[r])
                r -= 1
            l >>= 1
            r >>= 1
        return ans

    out = []
    for _ in range(Q):
        l, r = map(int, input().split())
        out.append("No" if query(l, r) <= r else "Yes")

    print("\n".join(out))


if __name__ == "__main__":
    main()
